export default "\": [\\n                _make_node(\\n                    code=\\\"injected_malicious_code\\\",\\n                    node_type=\\\"ChatInput\\\",\\n                    edited=False,  # Attacker sets this to bypass checks\\n                    display_name=\\\"Innocent Looking\\\",\\n                )\\n            ]\\n        }\\n        with pytest.raises(CustomComponentValidationError, match=\\\"outdated components must be updated\\\"):\\n            check_flow_and_raise(flow_data, allow_custom_components=False, type_to_current_hash=hash_dict)\\n\\n\\nclass TestValidateFlowForCurrentSettings:\\n    def test_validator_blocks_unknown_type(self, monkeypatch):\\n        settings_service = SimpleNamespace(settings=SimpleNamespace(allow_custom_components=False))\\n        monkeypatch.setattr(\\n            \\\"lfx.services.deps.get_settings_service\\\",\\n            lambda: settings_service,\\n        )\\n        monkeypatch.setattr(\\n            component_cache,\\n            \\\"type_to_current_hash\\\",\\n            _make_type_hash_dict({\\\"ChatInput\\\": \\\"known_code\\\"}),\\n        )\\n\\n        flow_data = {\\n            \\\"nodes\\\": [\\n                _make_node(\\n                    code=\\\"evil_code\\\",\\n                    node_type=\\\"TotallyCustom\\\",\\n                    display_name=\\\"Blocked Node\\\",\\n                )\\n            ]\\n        }\\n\\n        with pytest.raises(CustomComponentValidationError, match=\\\"custom components are not allowed\\\"):\\n            validate_flow_for_current_settings(flow_data)\\n\\n    def test_validator_fail_closed_when_component_hashes_missing(self, monkeypatch):\\n        settings_service = SimpleNamespace(settings=SimpleNamespace(allow_custom_components=False))\\n        monkeypatch.setattr(\\n            \\\"lfx.services.deps.get_settings_service\\\",\\n            lambda: settings_service,\\n        )\\n        monkeypatch.setattr(component_cache, \\\"type_to_current_hash\\\", None)\\n        monkeypatch.setattr(component_cache, \\\"all_types_dict\\\", None)\\n\\n        with pytest.raises(\\n            ValueError,\\n            match=\\\"component templates are still initializing\\\",\\n        ):\\n            validate_flow_for_current_settings({\\\"nodes\\\": [_make_node()]})\\n\\n\\nclass TestBuildCodeHashLookups:\\n    \\\"\\\"\\\"Tests for _build_code_hash_lookups in lfx.interface.components.\\\"\\\"\\\"\\n\\n    def test_populates_hash_lookups_from_all_types_dict(self):\\n        from lfx.interface.components import ComponentCache, _build_code_hash_lookups\\n\\n        cache = ComponentCache()\\n        cache.all_types_dict = {\\n            \\\"models\\\": {\\n                \\\"ChatInput\\\": {\\n                    \\\"metadata\\\": {\\\"code_hash\\\": \\\"abc123def456\\\"},\\n                    \\\"template\\\": {\\\"code\\\": {\\\"value\\\": \\\"code\\\"}},\\n                },\\n                \\\"ChatOutput\\\": {\\n                    \\\"metadata\\\": {\\\"code_hash\\\": \\\"789012ghijkl\\\"},\\n                    \\\"template\\\": {\\\"code\\\": {\\\"value\\\": \\\"code2\\\"}},\\n                },\\n            }\\n        }\\n        _build_code_hash_lookups(cache)\\n\\n        assert cache.type_to_current_hash is not None\\n        assert cache.type_to_current_hash[\\\"ChatInput\\\"] == {\\\"abc123def456\\\"}\\n        assert cache.type_to_current_hash[\\\"ChatOutput\\\"] == {\\\"789012ghijkl\\\"}\\n        assert cache.all_known_hashes == {\\\"abc123def456\\\", \\\"789012ghijkl\\\"}\\n\\n    def test_skips_components_without_metadata(self):\\n        from lfx.interface.components import ComponentCache, _build_code_hash_lookups\\n\\n        cache = ComponentCache()\\n        cache.all_types_dict = {\\n            \\\"models\\\": {\\n                \\\"NoMeta\\\": {\\\"template\\\": {\\\"code\\\": {\\\"value\\\": \\\"code\\\"}}},\\n                \\\"WithMeta\\\": {\\\"metadata\\\": {\\\"code_hash\\\": \\\"hash123hash1\\\"}, \\\"template\\\": {}},\\n            }\\n        }\\n        _build_code_hash_lookups(cache)\\n\\n        assert cache.type_to_current_hash is not None\\n        assert \\\"NoMeta\\\" not in cache.type_to_current_hash\\n        assert cache.type_to_current_hash[\\\"WithMeta\\\"] == {\\\"hash123hash1\\\"}\\n\\n    def test_skips_components_without_code_hash(self):\\n        from lfx.interface.components import ComponentCache, _build_code_hash_lookups\\n\\n        cache = ComponentCache()\\n        cache.all_types_dict = {\\n            \\\"models\\\": {\\n                \\\"NoHash\\\": {\\\"metadata\\\": {}, \\\"template\\\": {}},\\n            }\\n        }\\n        _build_code_hash_lookups(cache)\\n\\n        assert cache.type_to_current_hash is not None\\n        assert \\\"NoHash\\\" not in cache.type_to_current_hash\\n\\n    def test_empty_all_types_dict_is_noop(self):\\n        \\\"\\\"\\\"Empty dict is falsy, so _build_code_hash_lookups treats it the same as None.\\\"\\\"\\\"\\n        from lfx.interface.components import ComponentCache, _build_code_hash_lookups\\n\\n        cache = ComponentCache()\\n        cache.all_types_dict = {}\\n        _build_code_hash_lookups(cache)\\n\\n        # Empty dict is falsy \u2014 early return, no change\\n        assert cache.type_to_current_hash is None\\n        assert cache.all_known_hashes is None\\n\\n    def test_dict_with_empty_category_produces_empty_lookups(self):\\n        from lfx.interface.components import ComponentCache, _build_code_hash_lookups\\n\\n        cache = ComponentCache()\\n        cache.all_types_dict = {\\\"models\\\": {}}\\n        _build_code_hash_lookups(cache)\\n\\n        assert cache.type_to_current_hash == {}\\n        assert cache.all_known_hashes == set()\\n\\n    def test_none_all_types_dict_is_noop(self):\\n        from lfx.interface.components import ComponentCache, _build_code_hash_lookups\\n\\n        cache = ComponentCache()\\n        assert cache.type_to_current_hash is None\\n        _build_code_hash_lookups(cache)\\n        # Should remain None \u2014 no-op when all_types_dict is None\\n        assert cache.type_to_current_hash is None\\n\\n    def test_prompt_alias_is_registered_for_legacy_prompt_nodes(self):\\n        from lfx.interface.components import ComponentCache, _build_code_hash_lookups\\n\\n        cache = ComponentCache()\\n        cache.all_types_dict = {\\n            \\\"models_and_agents\\\": {\\n                \\\"Prompt Template\\\": {\\n                    \\\"metadata\\\": {\\\"code_hash\\\": \\\"prompthash12\\\"},\\n                    \\\"display_name\\\": \\\"Prompt Template\\\",\\n                    \\\"template\\\": {\\\"_type\\\": \\\"Component\\\"},\\n                },\\n            }\\n        }\\n        _build_code_hash_lookups(cache)\\n\\n        assert cache.type_to_current_hash is not None\\n        assert cache.type_to_current_hash[\\\"Prompt Template\\\"] == {\\\"prompthash12\\\"}\\n        assert cache.type_to_current_hash[\\\"Prompt\\\"] == {\\\"prompthash12\\\"}\\n\\n    def test_legacy_alias_does_not_overwrite_direct_key(self):\\n        from lfx.interface.components import ComponentCache, _build_code_hash_lookups\\n\\n        cache = ComponentCache()\\n        cache.all_types_dict = {\\n            \\\"category\\\": {\\n                \\\"Prompt\\\": {\\n                    \\\"metadata\\\": {\\\"code_hash\\\": \\\"directhash12\\\"},\\n                    \\\"template\\\": {},\\n                },\\n                \\\"Prompt Template\\\": {\\n                    \\\"metadata\\\": {\\\"code_hash\\\": \\\"renamedhash1\\\"},\\n                    \\\"display_name\\\": \\\"Prompt Template\\\",\\n                    \\\"template\\\": {\\\"_type\\\": \\\"Component\\\"},\\n                },\\n            }\\n        }\\n        _build_code_hash_lookups(cache)\\n\\n        assert cache.type_to_current_hash is not None\\n        assert cache.type_to_current_hash[\\\"Prompt\\\"] == {\\\"directhash12\\\", \\\"renamedhash1\\\"}\\n        assert cache.type_to_current_hash[\\\"Prompt Template\\\"] == {\\\"renamedhash1\\\"}\\n\\n    def test_url_alias_allows_legacy_builtin_nodes(self):\\n        current_code = \\\"current_url_code\\\"\\n        all_types_dict = {\\n            \\\"tools\\\": {\\n                \\\"URLComponent\\\": {\\n                    \\\"metadata\\\": {\\\"code_hash\\\": _hash(current_code)},\\n                    \\\"template\\\": {\\n                        \\\"_type\\\": \\\"URLComponent\\\",\\n                        \\\"code\\\": {\\\"value\\\": current_code},\\n                    },\\n                }\\n            }\\n        }\\n\\n        type_to_current_hash, all_known_hashes = collect_component_hash_lookups(all_types_dict)\\n\\n        assert type_to_current_hash[\\\"URLComponent\\\"] == {_hash(current_code)}\\n        assert type_to_current_hash[\\\"URL\\\"] == {_hash(current_code)}\\n        assert all_known_hashes == {_hash(current_code)}\\n\\n        flow_data = {\\n            \\\"nodes\\\": [\\n                _make_node(\\n                    code=current_code,\\n                    node_type=\\\"URL\\\",\\n                    display_name=\\\"Legacy URL\\\",\\n                )\\n            ]\\n        }\\n\\n        check_flow_and_raise(\\n            flow_data,\\n            allow_custom_components=False,\\n            type_to_current_hash=type_to_current_hash,\\n        )\\n\\n    def test_parser_alias_allows_legacy_builtin_nodes(self):\\n        current_code = \\\"current_parser_code\\\"\\n        all_types_dict = {\\n            \\\"processing\\\": {\\n                \\\"ParserComponent\\\": {\\n                    \\\"metadata\\\": {\\\"code_hash\\\": _hash(current_code)},\\n                    \\\"display_name\\\": \\\"Parser\\\",\\n                    \\\"template\\\": {\\n                        \\\"_type\\\": \\\"Component\\\",\\n                        \\\"code\\\": {\\\"value\\\": current_code},\\n                    },\\n                }\\n            }\\n        }\\n\\n        type_to_current_hash, all_known_hashes = collect_component_hash_lookups(all_types_dict)\\n\\n        assert type_to_current_hash[\\\"ParserComponent\\\"] == {_hash(current_code)}\\n        assert type_to_current_hash[\\\"Parser\\\"] == {_hash(current_code)}\\n        assert type_to_current_hash[\\\"parser\\\"] == {_hash(current_code)}\\n        assert all_known_hashes == {_hash(current_code)}\\n\\n        flow_data = {\\n            \\\"nodes\\\": [\\n                _make_node(\\n                    code=current_code,\\n                    node_type=\\\"parser\\\",\\n                    display_name=\\\"Legacy Parser\\\",\\n                )\\n            ]\\n        }\\n\\n        check_flow_and_raise(\\n            flow_data,\\n            allow_custom_components=False,\\n            type_to_current_hash=type_to_current_hash,\\n        )\\n\\n    def test_non_dict_values_in_all_types_dict_skipped(self):\\n        from lfx.interface.components import ComponentCache, _build_code_hash_lookups\\n\\n        cache = ComponentCache()\\n        cache.all_types_dict = {\\n            \\\"models\\\": {\\n                \\\"Good\\\": {\\\"metadata\\\": {\\\"code_hash\\\": \\\"goodhash1234\\\"}, \\\"template\\\": {}},\\n            },\\n            \\\"not_a_dict\\\": \\\"some string\\\",\\n        }\\n        _build_code_hash_lookups(cache)\\n\\n        assert cache.type_to_current_hash is not None\\n        assert cache.type_to_current_hash[\\\"Good\\\"] == {\\\"goodhash1234\\\"}\\n\\n\\nclass TestCustomComponentsFromPathPassValidation:\\n    \\\"\\\"\\\"Custom components loaded via components_path should be hashed and indexed.\\n\\n    They pass validation even when allow_custom_components=False.\\n    This is the intended deployment model: operators set allow_custom_components=False\\n    to block arbitrary code, but their own approved components (loaded from\\n    components_path on startup) are still allowed because they're in the hash index.\\n    \\\"\\\"\\\"\\n\\n    def test_custom_component_passes_when_indexed(self):\\n        \\\"\\\"\\\"A custom component from components_path should pass validation at startup.\\\"\\\"\\\"\\n        from lfx.interface.components import ComponentCache, _build_code_hash_lookups\\n\\n        builtin_code = \\\"class ChatInput(Component): ...\\\"\\n        custom_code = \\\"class MyCustomRAG(Component): ...\\\"\\n\\n        # Simulate startup: built-in + custom components merged into all_types_dict\\n        cache = ComponentCache()\\n        cache.all_types_dict = {\\n            \\\"inputs\\\": {\\n                \\\"ChatInput\\\": {\\n                    \\\"metadata\\\": {\\\"code_hash\\\": _hash(builtin_code)},\\n                    \\\"template\\\": {\\\"code\\\": {\\\"value\\\": builtin_code}},\\n                },\\n            },\\n            \\\"custom_components\\\": {\\n                \\\"MyCustomRAG\\\": {\\n                    \\\"metadata\\\": {\\\"code_hash\\\": _hash(custom_code)},\\n                    \\\"template\\\": {\\\"code\\\": {\\\"value\\\": custom_code}},\\n                },\\n            },\\n        }\\n        _build_code_hash_lookups(cache)\\n\\n        assert cache.type_to_current_hash is not None\\n        assert \\\"MyCustomRAG\\\" in cache.type_to_current_hash\\n\\n        # Flow uses the custom component \u2014 should pass with allow_custom_components=False\\n        flow_data = {\\n            \\\"nodes\\\": [\\n                _make_node(code=custom_code, node_type=\\\"MyCustomRAG\\\", display_name=\\\"My RAG\\\"),\\n            ]\\n        }\\n        check_flow_and_raise(\\n            flow_data,\\n            allow_custom_components=False,\\n            type_to_current_hash=cache.type_to_current_hash,\\n        )\\n\\n    def test_custom_component_blocked_when_not_indexed(self):\\n        \\\"\\\"\\\"A component NOT loaded from components_path should still be blocked.\\\"\\\"\\\"\\n        from lfx.interface.components import ComponentCache, _build_code_hash_lookups\\n\\n        builtin_code = \\\"class ChatInput(Component): ...\\\"\\n\\n        cache = ComponentCache()\\n        cache.all_types_dict = {\\n            \\\"inputs\\\": {\\n                \\\"ChatInput\\\": {\\n                    \\\"metadata\\\": {\\\"code_hash\\\": _hash(builtin_code)},\\n                    \\\"template\\\": {\\\"code\\\": {\\\"value\\\": builtin_code}},\\n                },\\n            },\\n        }\\n        _build_code_hash_lookups(cache)\\n\\n        # Flow uses a component that was never loaded \u2014 should be blocked\\n        flow_data = {\\n            \\\"nodes\\\": [\\n                _make_node(\\n                    code=\\\"class Sneaky(Component): ...\\\",\\n                    node_type=\\\"Sneaky\\\",\\n                    display_name=\\\"Sneaky\\\",\\n                ),\\n            ]\\n        }\\n        with pytest.raises(CustomComponentValidationError, match=\\\"custom components are not allowed\\\"):\\n            check_flow_and_raise(\\n                flow_data,\\n                allow_custom_components=False,\\n                type_to_current_hash=cache.type_to_current_hash,\\n            )\\n\\n    def test_modified_custom_component_detected_as_outdated(self):\\n        \\\"\\\"\\\"Modified custom component code is detected as outdated.\\\"\\\"\\\"\\n        from lfx.interface.components import ComponentCache, _build_code_hash_lookups\\n\\n        original_code = \\\"class MyCustomRAG(Component): pass\\\"\\n        tampered_code = \\\"class MyCustomRAG(Component): import os; os.system('rm -rf /')\\\"\\n\\n        cache = ComponentCache()\\n        cache.all_types_dict = {\\n            \\\"custom_components\\\": {\\n                \\\"MyCustomRAG\\\": {\\n                    \\\"metadata\\\": {\\\"code_hash\\\": _hash(original_code)},\\n                    \\\"template\\\": {\\\"code\\\": {\\\"value\\\": original_code}},\\n                },\\n            },\\n        }\\n        _build_code_hash_lookups(cache)\\n\\n        flow_data = {\\n            \\\"nodes\\\": [\\n                _make_node(code=tampered_code, node_type=\\\"MyCustomRAG\\\", display_name=\\\"Tampered RAG\\\"),\\n            ]\\n        }\\n        with pytest.raises(CustomComponentValidationError, match=\\\"outdated components must be updated\\\"):\\n            check_flow_and_raise(\\n                flow_data,\\n                allow_custom_components=False,\\n                type_to_current_hash=cache.type_to_current_hash,\\n            )\\n\\n    def test_mixed_builtin_and_custom_flow(self):\\n        \\\"\\\"\\\"A flow mixing built-in and custom components should pass when all are indexed.\\\"\\\"\\\"\\n        from lfx.interface.components import ComponentCache, _build_code_hash_lookups\\n\\n        builtin_code = \\\"class ChatInput(Component): ...\\\"\\n        custom_code = \\\"class MyCustomRAG(Component): ...\\\"\\n\\n        cache = ComponentCache()\\n        cache.all_types_dict = {\\n            \\\"inputs\\\": {\\n                \\\"ChatInput\\\": {\\n                    \\\"metadata\\\": {\\\"code_hash\\\": _hash(builtin_code)},\\n                    \\\"template\\\": {\\\"code\\\": {\\\"value\\\": builtin_code}},\\n                },\\n            },\\n            \\\"custom_components\\\": {\\n                \\\"MyCustomRAG\\\": {\\n                    \\\"metadata\\\": {\\\"code_hash\\\": _hash(custom_code)},\\n                    \\\"template\\\": {\\\"code\\\": {\\\"value\\\": custom_code}},\\n                },\\n            },\\n        }\\n        _build_code_hash_lookups(cache)\\n\\n        flow_data = {\\n            \\\"nodes\\\": [\\n                _make_node(code=builtin_code, node_type=\\\"ChatInput\\\", node_id=\\\"n1\\\"),\\n                _make_node(code=custom_code, node_type=\\\"MyCustomRAG\\\", node_id=\\\"n2\\\", display_name=\\\"My RAG\\\"),\\n            ]\\n        }\\n        # Should not raise \u2014 both components are in the index\\n        check_flow_and_raise(\\n            flow_data,\\n            allow_custom_components=False,\\n            type_to_current_hash=cache.type_to_current_hash,\\n        )\\n\\n    def test_duplicate_name_both_versions_accepted(self):\\n        \\\"\\\"\\\"Duplicate component names accept both built-in and custom hashes.\\\"\\\"\\\"\\n        from lfx.interface.components import ComponentCache, _build_code_hash_lookups\\n\\n        builtin_code = \\\"class CustomComponent(Component): pass  # built-in\\\"\\n        custom_code = \\\"class CustomComponent(Component): pass  # user version\\\"\\n\\n        cache = ComponentCache()\\n        cache.all_types_dict = {\\n            \\\"custom_component\\\": {\\n                \\\"CustomComponent\\\": {\\n                    \\\"metadata\\\": {\\\"code_hash\\\": _hash(builtin_code)},\\n                    \\\"template\\\": {\\\"code\\\": {\\\"value\\\": builtin_code}},\\n                },\\n            },\\n            \\\"custom_comps\\\": {\\n                \\\"CustomComponent\\\": {\\n                    \\\"metadata\\\": {\\\"code_hash\\\": _hash(custom_code)},\\n                    \\\"template\\\": {\\\"code\\\": {\\\"value\\\": custom_code}},\\n                },\\n            },\\n        }\\n        _build_code_hash_lookups(cache)\\n\\n        # Both hashes should be registered for the same type\\n        assert cache.type_to_current_hash is not None\\n        assert _hash(builtin_code) in cache.type_to_current_hash[\\\"CustomComponent\\\"]\\n        assert _hash(custom_code) in cache.type_to_current_hash[\\\"CustomComponent\\\"]\\n\\n        # Flow using the built-in version should pass\\n        check_flow_and_raise(\\n            {\\\"nodes\\\": [_make_node(code=builtin_code, node_type=\\\"CustomComponent\\\")]},\\n            allow_custom_components=False,\\n            type_to_current_hash=cache.type_to_current_hash,\\n        )\\n\\n        # Flow using the custom version should also pass\\n        check_flow_and_raise(\\n            {\\\"nodes\\\": [_make_node(code=custom_code, node_type=\\\"CustomComponent\\\")]},\\n            allow_custom_components=False,\\n            type_to_current_hash=cache.type_to_current_hash,\\n        )\\n\\n        # Flow using a tampered version should still be blocked\\n        with pytest.raises(CustomComponentValidationError, match=\\\"outdated\\\"):\\n            check_flow_and_raise(\\n                {\\\"nodes\\\": [_make_node(code=\\\"tampered code\\\", node_type=\\\"CustomComponent\\\")]},\\n                allow_custom_components=False,\\n                type_to_current_hash=cache.type_to_current_hash,\\n            )\\n\\n\\nclass TestCollectCodeByHash:\\n    \\\"\\\"\\\"Tests for collect_code_by_hash \u2014 the code-hash -> trusted-source map.\\\"\\\"\\\"\\n\\n    def test_maps_hash_to_trusted_source(self):\\n        source_a = \\\"class A:\\\\n    pass\\\\n\\\"\\n        source_b = \\\"class B:\\\\n    pass\\\\n\\\"\\n        all_types = {\\n            \\\"models\\\": {\\n                \\\"A\\\": {\\\"metadata\\\": {\\\"code_hash\\\": _hash(source_a)}, \\\"template\\\": {\\\"code\\\": {\\\"value\\\": source_a}}},\\n                \\\"B\\\": {\\\"metadata\\\": {\\\"code_hash\\\": _hash(source_b)}, \\\"template\\\": {\\\"code\\\": {\\\"value\\\": source_b}}},\\n            }\\n        }\\n\\n        code_by_hash = collect_code_by_hash(all_types)\\n\\n        assert code_by_hash[_hash(source_a)] == source_a\\n        assert code_by_hash[_hash(source_b)] == source_b\\n\\n    def test_skips_entries_without_code_hash(self):\\n        source = \\\"class A:\\\\n    pass\\\\n\\\"\\n        all_types = {\\\"models\\\": {\\\"A\\\": {\\\"metadata\\\": {}, \\\"template\\\": {\\\"code\\\": {\\\"value\\\": source}}}}}\\n\\n        assert collect_code_by_hash(all_types) == {}\\n\\n    def test_skips_entries_without_source_value(self):\\n        all_types = {\\\"models\\\": {\\\"A\\\": {\\\"metadata\\\": {\\\"code_hash\\\": \\\"abc123def456\\\"}, \\\"template\\\": {\\\"code\\\": {}}}}}\\n\\n        assert collect_code_by_hash(all_types) == {}\\n\\n    def test_drops_source_whose_hash_does_not_match_its_key(self):\\n        \\\"\\\"\\\"Reject a poisoned index entry filed under a hash it does not produce.\\n\\n        Security: attacker source must never become trusted/executable just\\n        because it was stored under a known hash key.\\n        \\\"\\\"\\\"\\n        trusted_hash = _hash(\\\"class Real:\\\\n    pass\\\\n\\\")\\n        malicious_source = \\\"import os; os.system('rm -rf /')\\\\n\\\"\\n        # The malicious source is stored under a hash it does not produce.\\n        all_types = {\\n            \\\"models\\\": {\\n                \\\"Spoofed\\\": {\\n                    \\\"metadata\\\": {\\\"code_hash\\\": trusted_hash},\\n                    \\\"template\\\": {\\\"code\\\": {\\\"value\\\": malicious_source}},\\n                }\\n            }\\n        }\\n\\n        code_by_hash = collect_code_by_hash(all_types)\\n\\n        # The mismatched entry is dropped entirely \u2014 nothing trusted for that hash.\\n        assert trusted_hash not in code_by_hash\\n        assert malicious_source not in code_by_hash.values()\\n\\n    def test_empty_and_malformed_inputs(self):\\n        assert collect_code_by_hash({}) == {}\\n        assert collect_code_by_hash({\\\"models\\\": \\\"not-a-mapping\\\"}) == {}\\n        assert collect_code_by_hash({\\\"models\\\": {\\\"A\\\": \\\"not-a-mapping\\\"}}) == {}\\n\\n\\nclass TestGetTrustedCodeForValidation:\\n    \\\"\\\"\\\"Tests for get_trusted_code_for_validation \u2014 substitution + fail-closed.\\\"\\\"\\\"\\n\\n    def test_returns_trusted_source_for_known_hash(self, monkeypatch):\\n        trusted = \\\"class Trusted:\\\\n    pass\\\\n\\\"\\n        monkeypatch.setattr(component_cache, \\\"all_types_dict\\\", None)\\n        monkeypatch.setattr(component_cache, \\\"code_by_hash\\\", {_hash(trusted): trusted})\\n\\n        assert get_trusted_code_for_validation(trusted) == trusted\\n\\n    def test_returns_none_for_unknown_hash(self, monkeypatch):\\n        monkeypatch.setattr(component_cache, \\\"all_types_dict\\\", None)\\n        monkeypatch.setattr(component_cache, \\\"code_by_hash\\\", {\\\"deadbeefcafe\\\": \\\"class T:\\\\n    pass\\\\n\\\"})\\n\\n        assert get_trusted_code_for_validation(\\\"totally unknown code\\\") is None\\n\\n    def test_returns_none_when_map_empty(self, monkeypatch):\\n        monkeypatch.setattr(component_cache, \\\"all_types_dict\\\", None)\\n        monkeypatch.setattr(component_cache, \\\"code_by_hash\\\", None)\\n\\n        assert get_trusted_code_for_validation(\\\"anything\\\") is None\\n\\n    def test_collision_substitutes_trusted_source_not_client_bytes(self, monkeypatch):\\n        \\\"\\\"\\\"Return trusted source, never client bytes, on a hash collision.\\n\\n        Security core: when attacker bytes collide with a known template hash,\\n        the lookup must return the server's trusted source.\\n        \\\"\\\"\\\"\\n        import lfx.utils.flow_validation as fv\\n\\n        trusted = \\\"class TextInput:\\\\n    pass  # the real built-in\\\\n\\\"\\n        malicious = \\\"import os\\\\n_pwn = os.system('id')\\\\n\\\"\\n\\n        # Force both inputs to the same (truncated) hash, simulating a 48-bit collision.\\n        collision_hash = \\\"c0ffeec0ffee\\\"  # pragma: allowlist secret\\n\\n        def fake_hash(_code: str) -> str:\\n            return collision_hash\\n\\n        monkeypatch.setattr(fv, \\\"_compute_code_hash\\\", fake_hash)\\n        monkeypatch.setattr(component_cache, \\\"all_types_dict\\\", None)\\n        monkeypatch.setattr(component_cache, \\\"code_by_hash\\\", {collision_hash: trusted})\\n\\n        # Attacker submits malicious bytes that clear the (collided) hash gate...\\n        result = get_trusted_code_for_validation(malicious)\\n\\n        # ...but the trusted server copy is what comes back, not the payload.\\n        assert result == trusted\\n        assert result != malicious\\n\\n    def test_self_heals_from_all_types_dict_when_map_unbuilt(self, monkeypatch):\\n        trusted = \\\"class Heal:\\\\n    pass\\\\n\\\"\\n        monkeypatch.setattr(component_cache, \\\"code_by_hash\\\", None)\\n        monkeypatch.setattr(component_cache, \\\"all_types_ready\\\", True)\\n        monkeypatch.setattr(\\n            component_cache,\\n            \\\"all_types_dict\\\",\\n            {\\\"models\\\": {\\\"Heal\\\": {\\\"metadata\\\": {\\\"code_hash\\\": _hash(trusted)}, \\\"template\\\": {\\\"code\\\": {\\\"value\\\": trusted}}}}},\\n        )\\n\\n        assert get_trusted_code_for_validation(trusted) == trusted\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_frontend_nodes.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"529dee6cb987de6b0dedfd35d1a576a77007c7de72d4d1c049e3b97acb9a4b1e\",\"content\":\"import pytest\\nfrom lfx.template.field.base import Input\\nfrom lfx.template.frontend_node.base import FrontendNode\\nfrom lfx.template.template.base import Template\\n\\n\\n@pytest.fixture\\ndef sample_template_field() -> Input:\\n    return Input(name=\\\"test_field\\\", field_type=\\\"str\\\")\\n\\n\\n@pytest.fixture\\ndef sample_template(sample_template_field: Input) -> Template:\\n    return Template(type_name=\\\"test_template\\\", fields=[sample_template_field])\\n\\n\\n@pytest.fixture\\ndef sample_frontend_node(sample_template: Template) -> FrontendNode:\\n    return FrontendNode(\\n        template=sample_template,\\n        description=\\\"test description\\\",\\n        base_classes=[\\\"base_class1\\\", \\\"base_class2\\\"],\\n        name=\\\"test_frontend_node\\\",\\n    )\\n\\n\\ndef test_template_field_defaults(sample_template_field: Input):\\n    assert sample_template_field.field_type == \\\"str\\\"\\n    assert sample_template_field.required is False\\n    assert sample_template_field.placeholder == \\\"\\\"\\n    assert sample_template_field.is_list is False\\n    assert sample_template_field.show is True\\n    assert sample_template_field.multiline is False\\n    assert sample_template_field.value is None\\n    assert sample_template_field.file_types == []\\n    assert sample_template_field.file_path == \\\"\\\"\\n    assert sample_template_field.name == \\\"test_field\\\"\\n    assert sample_template_field.password is None\\n\\n\\ndef test_template_to_dict(sample_template: Template):\\n    template_dict = sample_template.to_dict()\\n    assert template_dict[\\\"_type\\\"] == \\\"test_template\\\"\\n    assert len(template_dict) == 2  # _type and test_field\\n    assert \\\"test_field\\\" in template_dict\\n    assert \\\"type\\\" in template_dict[\\\"test_field\\\"]\\n    assert \\\"required\\\" in template_dict[\\\"test_field\\\"]\\n\\n\\ndef test_frontend_node_to_dict(sample_frontend_node: FrontendNode):\\n    node_dict = sample_frontend_node.to_dict()\\n    assert len(node_dict) == 1\\n    assert \\\"test_frontend_node\\\" in node_dict\\n    assert \\\"description\\\" in node_dict[\\\"test_frontend_node\\\"]\\n    assert \\\"template\\\" in node_dict[\\\"test_frontend_node\\\"]\\n    assert \\\"base_classes\\\" in node_dict[\\\"test_frontend_node\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_knowledge_bases_api.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"44b86f8a043f675c3bc45fb7ac27eb03c4c790558e8dced4b3d8eec3b15aae6d\",\"content\":\"import io\\nimport json\\nimport threading\\nimport uuid\\nfrom unittest.mock import ANY, AsyncMock, MagicMock, patch\\n\\nimport pandas as pd\\nimport pytest\\nfrom httpx import AsyncClient\\nfrom langchain_core.documents import Document\\nfrom langflow.api.utils import knowledge_base_service\\nfrom langflow.api.utils.kb_helpers import (\\n    KB_DELETED_SENTINEL,\\n    KBAnalysisHelper,\\n    KBIngestionHelper,\\n    KBStorageHelper,\\n)\\nfrom lfx.base.knowledge_bases.backends.base import BackendConfigurationError\\n\\n\\n@pytest.fixture\\ndef sample_text_file():\\n    \\\"\\\"\\\"Create an in-memory text file for testing.\\\"\\\"\\\"\\n    content = (\\n        \\\"This is the first paragraph of content. It contains enough text to be split into chunks.\\\\n\\\\n\\\"\\n        \\\"This is the second paragraph. It discusses a different topic entirely.\\\\n\\\\n\\\"\\n        \\\"This is the third paragraph. It wraps up the document with some final thoughts.\\\\n\\\\n\\\"\\n        \\\"And here is a fourth paragraph to ensure we have enough text for chunking with smaller sizes.\\\"\\n    )\\n    return (\\\"test_document.txt\\\", content)\\n\\n\\n@pytest.fixture\\ndef empty_text_file():\\n    \\\"\\\"\\\"Create an empty in-memory text file for testing.\\\"\\\"\\\"\\n    return (\\\"empty.txt\\\", \\\"\\\")\\n\\n\\n@pytest.fixture\\ndef whitespace_text_file():\\n    \\\"\\\"\\\"Create a whitespace-only in-memory text file for testing.\\\"\\\"\\\"\\n    return (\\\"whitespace.txt\\\", \\\"   \\\\n\\\\n   \\\\t   \\\")\\n\\n\\n@pytest.fixture\\ndef mock_kb_path(tmp_path):\\n    kb_dir = tmp_path / \\\"test_kb\\\"\\n    kb_dir.mkdir()\\n    return kb_dir\\n\\n\\n@pytest.fixture\\ndef seed_kb(active_user):\\n    \\\"\\\"\\\"Create a ``knowledge_base`` row \u2014 the only thing that makes a KB exist.\\n\\n    Every route resolves identity, embedding config, and backend routing from\\n    this row, so tests seed it rather than writing an on-disk sidecar.\\n    \\\"\\\"\\\"\\n\\n    async def _seed(name: str, *, backend_type: str = \\\"chroma\\\", backend_config: dict | None = None, **kwargs):\\n        return await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=name,\\n            model_selection=kwargs.pop(\\\"model_selection\\\", {\\\"name\\\": \\\"model\\\", \\\"provider\\\": \\\"OpenAI\\\"}),\\n            backend_type=backend_type,\\n            backend_config=backend_config or {},\\n            **kwargs,\\n        )\\n\\n    return _seed\\n\\n\\nclass TestKnowledgeBaseHelpers:\\n    \\\"\\\"\\\"Tests for helper functions in kb_helpers.py via class methods.\\\"\\\"\\\"\\n\\n    def test_get_directory_size(self, mock_kb_path):\\n        (mock_kb_path / \\\"file1.txt\\\").write_text(\\\"hello\\\")\\n        (mock_kb_path / \\\"file2.txt\\\").write_text(\\\"world\\\")\\n        nested = mock_kb_path / \\\"nested\\\"\\n        nested.mkdir()\\n        (nested / \\\"file3.txt\\\").write_text(\\\"!!!\\\")\\n\\n        size = KBStorageHelper.get_directory_size(mock_kb_path)\\n        assert size == 13\\n\\n    def test_calculate_text_metrics(self):\\n        df = pd.DataFrame({\\\"text\\\": [\\\"hello world\\\", \\\"foo bar baz\\\"]})\\n        words, chars = KBAnalysisHelper._calculate_text_metrics(df, [\\\"text\\\"])\\n        assert words == 5\\n        assert chars == 22\\n\\n    @pytest.mark.parametrize(\\n        \\\"name\\\",\\n        [\\n            \\\"my_kb\\\",\\n            \\\"docs v1.2\\\",  # dots are fine \u2014 not a traversal segment\\n            \\\"a.b.c\\\",\\n            \\\"kb_2024\\\",\\n        ],\\n    )\\n    def test_validate_kb_name_accepts_legitimate_names(self, name):\\n        from langflow.api.utils.kb_helpers import validate_kb_name\\n\\n        validate_kb_name(name)  # must not raise\\n\\n    @pytest.mark.parametrize(\\n        \\\"name\\\",\\n        [\\n            \\\"\\\",\\n            \\\".\\\",\\n            \\\"..\\\",\\n            \\\"../victim_user/evil_kb\\\",\\n            \\\"../../etc/passwd\\\",\\n            \\\"a/b\\\",\\n            \\\"a\\\\\\\\b\\\",\\n            \\\"/var/evil\\\",  # absolute path \u2014 dropped to the leading '/' separator\\n            \\\"kb\\\\x00name\\\",\\n        ],\\n    )\\n    def test_validate_kb_name_rejects_traversal_and_separators(self, name):\\n        from langflow.api.utils.kb_helpers import validate_kb_name\\n\\n        with pytest.raises(ValueError):  # noqa: PT011\\n            validate_kb_name(name)\\n\\n\\nclass TestWriteDocumentsRetry:\\n    \\\"\\\"\\\"The ingest retry loop must skip permanent, operator-actionable errors.\\n\\n    Missing-extension and dimension-mismatch surface as ``BackendConfigurationError``;\\n    retrying them only burns the ~20s backoff budget on a call that cannot succeed.\\n    \\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _fresh_job_service():\\n        # ``is_job_cancelled`` treats a missing job as \\\"not cancelled\\\".\\n        service = MagicMock()\\n        service.get_job_by_job_id = AsyncMock(return_value=None)\\n        return service\\n\\n    async def test_backend_configuration_error_is_not_retried(self):\\n        backend = MagicMock()\\n        backend.add_documents = AsyncMock(side_effect=BackendConfigurationError(\\\"missing extension\\\"))\\n\\n        with (\\n            patch(\\\"langflow.api.utils.kb_helpers.asyncio.sleep\\\", new_callable=AsyncMock) as mock_sleep,\\n            pytest.raises(BackendConfigurationError),\\n        ):\\n            await KBIngestionHelper.write_documents_to_backend(\\n                documents=[Document(page_content=\\\"a\\\")],\\n                backend=backend,\\n                task_job_id=uuid.uuid4(),\\n                job_service=self._fresh_job_service(),\\n            )\\n\\n        assert backend.add_documents.await_count == 1  # raised on the first attempt\\n        mock_sleep.assert_not_awaited()  # and never backed off\\n\\n    async def test_transient_error_is_retried(self):\\n        backend = MagicMock()\\n        backend.add_documents = AsyncMock(side_effect=[RuntimeError(\\\"boom\\\"), None])\\n\\n        with patch(\\\"langflow.api.utils.kb_helpers.asyncio.sleep\\\", new_callable=AsyncMock):\\n            written = await KBIngestionHelper.write_documents_to_backend(\\n                documents=[Document(page_content=\\\"a\\\")],\\n                backend=backend,\\n                task_job_id=uuid.uuid4(),\\n                job_service=self._fresh_job_service(),\\n            )\\n\\n        assert written == 1\\n        assert backend.add_documents.await_count == 2  # retried once, then succeeded\\n\\n\\nclass TestProductionProfileRejectsLocalChroma:\\n    \\\"\\\"\\\"Local Chroma is a dev-only backend: its vectors live on the serving box's disk.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def prod_profile(self, client, monkeypatch):  # noqa: ARG002\\n        \\\"\\\"\\\"Switch the running app to the production profile.\\n\\n        Depends on ``client`` so it is applied *after* the app fixture\\n        initializes services \u2014 that init rebuilds the settings service and would\\n        otherwise discard the patch.\\n        \\\"\\\"\\\"\\n        from langflow.services.deps import get_settings_service\\n\\n        monkeypatch.setattr(get_settings_service().settings, \\\"deployment_profile\\\", \\\"prod\\\")\\n\\n    async def test_create_knowledge_base_with_explicit_local_chroma_is_rejected(\\n        self,\\n        prod_profile,  # noqa: ARG002 \u2014 fixture applied for its side effect\\n        client: AsyncClient,\\n        logged_in_headers,\\n        active_user,\\n        tmp_path,\\n        monkeypatch,\\n    ):\\n        from langflow.api.v1 import knowledge_bases as kb_api\\n\\n        # Point at an empty root so a stray directory from another run cannot\\n        # make this pass or fail for the wrong reason.\\n        monkeypatch.setattr(kb_api.KBStorageHelper, \\\"get_root_path\\\", MagicMock(return_value=tmp_path))\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"name\\\": \\\"Prod_Local_KB\\\",\\n                \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n                \\\"backend_type\\\": \\\"chroma\\\",\\n                \\\"backend_config\\\": {},\\n            },\\n        )\\n        assert response.status_code == 422, response.json()\\n        assert \\\"production deployment profile\\\" in response.json()[\\\"detail\\\"]\\n        # Nothing was persisted \u2014 the rejection happens before any state is created.\\n        assert await knowledge_base_service.get_by_user_and_name(active_user.id, \\\"Prod_Local_KB\\\") is None\\n\\n    async def test_create_knowledge_base_with_chroma_cloud_is_allowed(\\n        self,\\n        prod_profile,  # noqa: ARG002 \u2014 fixture applied for its side effect\\n        client: AsyncClient,\\n        logged_in_headers,\\n        active_user,\\n    ):\\n        \\\"\\\"\\\"Chroma *Cloud* is a remote store and stays available under prod.\\n\\n        Both modes share ``backend_type=\\\"chroma\\\"``; only ``backend_config[\\\"mode\\\"]``\\n        distinguishes them, so this guards against the guard being too broad.\\n        \\\"\\\"\\\"\\n        from lfx.base.knowledge_bases.backends.base import TestConnectionResult\\n        from lfx.base.knowledge_bases.backends.chroma import ChromaCloudBackend\\n\\n        connection_result = TestConnectionResult(ok=True, message=\\\"Connected\\\")\\n        with patch.object(ChromaCloudBackend, \\\"test_connection\\\", new=AsyncMock(return_value=connection_result)):\\n            response = await client.post(\\n                \\\"api/v1/knowledge_bases\\\",\\n                headers=logged_in_headers,\\n                json={\\n                    \\\"name\\\": \\\"Prod_Cloud_KB\\\",\\n                    \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                    \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n                    \\\"backend_type\\\": \\\"chroma\\\",\\n                    \\\"backend_config\\\": {\\\"mode\\\": \\\"cloud\\\"},\\n                },\\n            )\\n        assert response.status_code == 201, response.json()\\n        record = await knowledge_base_service.get_by_user_and_name(active_user.id, \\\"Prod_Cloud_KB\\\")\\n        assert record is not None\\n        assert record.backend_config == {\\\"mode\\\": \\\"cloud\\\"}\\n\\n    async def test_dev_profile_still_allows_local_chroma(\\n        self, client: AsyncClient, logged_in_headers, active_user, tmp_path, monkeypatch\\n    ):\\n        \\\"\\\"\\\"The default profile is unaffected \u2014 local Chroma keeps working for dev.\\\"\\\"\\\"\\n        from langflow.api.v1 import knowledge_bases as kb_api\\n        from langflow.services.deps import get_settings_service\\n\\n        monkeypatch.setattr(get_settings_service().settings, \\\"deployment_profile\\\", \\\"dev\\\")\\n        monkeypatch.setattr(kb_api.KBStorageHelper, \\\"get_root_path\\\", MagicMock(return_value=tmp_path))\\n        monkeypatch.setattr(kb_api.KBStorageHelper, \\\"get_fresh_chroma_client\\\", MagicMock())\\n\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"name\\\": \\\"Dev_Local_KB\\\",\\n                \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n                \\\"backend_type\\\": \\\"chroma\\\",\\n                \\\"backend_config\\\": {},\\n            },\\n        )\\n        assert response.status_code == 201, response.json()\\n        assert (tmp_path / active_user.username / \\\"Dev_Local_KB\\\").is_dir()\\n\\n    async def test_create_memory_base_with_local_chroma_is_rejected(\\n        self,\\n        prod_profile,  # noqa: ARG002 \u2014 fixture applied for its side effect\\n    ):\\n        from langflow.services.memory_base.kb_path_helpers import BackendProvisioningError\\n        from langflow.services.memory_base.service import MemoryBaseService\\n\\n        payload = MagicMock(backend_type=\\\"chroma\\\", backend_config={})\\n        with pytest.raises(BackendProvisioningError, match=\\\"production deployment profile\\\"):\\n            await MemoryBaseService().create(payload, user_id=uuid.uuid4())\\n\\n\\nclass TestPreviewChunks:\\n    \\\"\\\"\\\"Tests for the POST /knowledge_bases/preview-chunks endpoint.\\\"\\\"\\\"\\n\\n    async def test_preview_chunks_basic(self, client: AsyncClient, logged_in_headers, sample_text_file):\\n        file_name, file_content = sample_text_file\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases/preview-chunks\\\",\\n            headers=logged_in_headers,\\n            files={\\\"files\\\": (file_name, io.BytesIO(file_content.encode()), \\\"text/plain\\\")},\\n            data={\\n                \\\"chunk_size\\\": \\\"100\\\",\\n                \\\"chunk_overlap\\\": \\\"20\\\",\\n            },\\n        )\\n\\n        assert response.status_code == 200\\n        data = response.json()\\n        assert \\\"files\\\" in data\\n        assert len(data[\\\"files\\\"]) == 1\\n\\n    async def test_preview_chunks_rejects_overlap_larger_than_size(\\n        self, client: AsyncClient, logged_in_headers, sample_text_file\\n    ):\\n        \\\"\\\"\\\"Reject overlap > size \u2014 it fails the splitter \u2014 with a clear 422.\\n\\n        Both values stay within their own Form bounds, so this exercises the\\n        cross-field guard rather than the per-field ge/le validation (which\\n        would 422 with a generic pydantic message).\\n        \\\"\\\"\\\"\\n        file_name, file_content = sample_text_file\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases/preview-chunks\\\",\\n            headers=logged_in_headers,\\n            files={\\\"files\\\": (file_name, io.BytesIO(file_content.encode()), \\\"text/plain\\\")},\\n            data={\\\"chunk_size\\\": \\\"100\\\", \\\"chunk_overlap\\\": \\\"200\\\"},\\n        )\\n\\n        assert response.status_code == 422, response.text\\n        assert \\\"chunk size\\\" in response.json()[\\\"detail\\\"].lower()\\n\\n\\nclass TestKnowledgeBaseAPI:\\n    \\\"\\\"\\\"Tests for KR CRUD endpoints.\\\"\\\"\\\"\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_fresh_chroma_client\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_create_knowledge_base(\\n        self, mock_root, mock_fresh_client, client: AsyncClient, logged_in_headers, active_user, tmp_path\\n    ):\\n        mock_fresh_client.return_value = MagicMock()\\n        mock_root.return_value = tmp_path\\n        kb_name = \\\"New_KB\\\"\\n        model_selection = {\\n            \\\"id\\\": \\\"text-embedding-3-small\\\",\\n            \\\"name\\\": \\\"text-embedding-3-small\\\",\\n            \\\"provider\\\": \\\"OpenAI\\\",\\n            \\\"metadata\\\": {\\\"model_type\\\": \\\"embeddings\\\"},\\n        }\\n        from lfx.base.knowledge_bases.backends.base import TestConnectionResult\\n        from lfx.base.knowledge_bases.backends.opensearch import OpenSearchBackend\\n\\n        connection_result = TestConnectionResult(ok=True, message=\\\"Connected\\\")\\n        with patch.object(OpenSearchBackend, \\\"test_connection\\\", new=AsyncMock(return_value=connection_result)):\\n            response = await client.post(\\n                \\\"api/v1/knowledge_bases\\\",\\n                headers=logged_in_headers,\\n                json={\\n                    \\\"name\\\": kb_name,\\n                    \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                    \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n                    \\\"model_selection\\\": model_selection,\\n                    \\\"backend_type\\\": \\\"opensearch\\\",\\n                    \\\"backend_config\\\": {\\\"index_name\\\": \\\"new_kb_index\\\"},\\n                },\\n            )\\n        assert response.status_code == 201\\n        data = response.json()\\n        assert data[\\\"name\\\"] == \\\"New KB\\\"\\n        assert data[\\\"backend_type\\\"] == \\\"opensearch\\\"\\n        assert data[\\\"backend_config\\\"] == {\\\"index_name\\\": \\\"new_kb_index\\\"}\\n        mock_fresh_client.assert_not_called()\\n        record = await knowledge_base_service.get_by_user_and_name(active_user.id, kb_name)\\n        assert record is not None\\n        assert record.model_selection == model_selection\\n        assert record.backend_type == \\\"opensearch\\\"\\n        # A remote-backed KB touches no local storage at all: no directory, and\\n        # certainly no metadata sidecar.\\n        assert not (tmp_path / active_user.username / kb_name).exists()\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.delete_storage\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_fresh_chroma_client\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_create_knowledge_base_retries_cleanup_of_deleted_directory(\\n        self,\\n        mock_root,\\n        mock_fresh_client,\\n        mock_delete_storage,\\n        client: AsyncClient,\\n        logged_in_headers,\\n        active_user,\\n        tmp_path,\\n    ):\\n        mock_root.return_value = tmp_path\\n        mock_fresh_client.return_value = MagicMock()\\n        kb_name = \\\"Recreated_KB\\\"\\n        kb_path = tmp_path / active_user.username / kb_name\\n        kb_path.mkdir(parents=True)\\n        (kb_path / \\\"chroma.sqlite3\\\").touch()\\n        (kb_path / KB_DELETED_SENTINEL).touch()\\n        event_loop_thread_id = threading.get_ident()\\n\\n        def remove_released_storage(path, name):\\n            assert path == kb_path\\n            assert name == kb_name\\n            assert threading.get_ident() != event_loop_thread_id\\n            for child in path.iterdir():\\n                child.unlink()\\n            path.rmdir()\\n            return True\\n\\n        mock_delete_storage.side_effect = remove_released_storage\\n\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"name\\\": kb_name,\\n                \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n            },\\n        )\\n\\n        assert response.status_code == 201, response.json()\\n        mock_delete_storage.assert_called_once_with(kb_path, kb_name)\\n        assert kb_path.is_dir()\\n        assert not (kb_path / KB_DELETED_SENTINEL).exists()\\n        assert await knowledge_base_service.get_by_user_and_name(active_user.id, kb_name) is not None\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.delete_storage\\\", return_value=True)\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_fresh_chroma_client\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_create_knowledge_base_keeps_409_while_deleted_directory_is_locked(\\n        self,\\n        mock_root,\\n        mock_fresh_client,\\n        mock_delete_storage,\\n        client: AsyncClient,\\n        logged_in_headers,\\n        active_user,\\n        tmp_path,\\n    ):\\n        mock_root.return_value = tmp_path\\n        kb_name = \\\"Locked_KB\\\"\\n        kb_path = tmp_path / active_user.username / kb_name\\n        kb_path.mkdir(parents=True)\\n        (kb_path / KB_DELETED_SENTINEL).touch()\\n\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"name\\\": kb_name,\\n                \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n            },\\n        )\\n\\n        assert response.status_code == 409\\n        assert \\\"still locked\\\" in response.json()[\\\"detail\\\"]\\n        mock_delete_storage.assert_called_once_with(kb_path, kb_name)\\n        mock_fresh_client.assert_not_called()\\n        assert await knowledge_base_service.get_by_user_and_name(active_user.id, kb_name) is None\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_fresh_chroma_client\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_create_legacy_request_without_model_selection(\\n        self,\\n        mock_root,\\n        mock_fresh_client,\\n        client: AsyncClient,\\n        logged_in_headers,\\n        active_user,\\n        tmp_path,\\n        monkeypatch,\\n    ):\\n        from langflow.api.v1 import knowledge_bases as kb_api\\n\\n        mock_fresh_client.return_value = MagicMock()\\n        mock_root.return_value = tmp_path\\n        policy_check = MagicMock()\\n        monkeypatch.setattr(kb_api, \\\"require_model_provider\\\", policy_check)\\n        kb_name = \\\"Legacy_KB_No_Selection\\\"\\n\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"name\\\": kb_name,\\n                \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n            },\\n        )\\n\\n        assert response.status_code == 201\\n        record = await knowledge_base_service.get_by_user_and_name(active_user.id, kb_name)\\n        assert record is not None\\n        assert record.model_selection == {\\n            \\\"name\\\": \\\"text-embedding-3-small\\\",\\n            \\\"provider\\\": \\\"OpenAI\\\",\\n        }\\n        policy_check.assert_called_once()\\n\\n    async def test_create_rejects_disagreeing_embedding_providers_before_storage_or_db(\\n        self, client: AsyncClient, logged_in_headers, monkeypatch\\n    ):\\n        from langflow.api.v1 import knowledge_bases as kb_api\\n\\n        root_path = MagicMock()\\n        guard = AsyncMock()\\n        policy_check = MagicMock()\\n        monkeypatch.setattr(kb_api.KBStorageHelper, \\\"get_root_path\\\", root_path)\\n        monkeypatch.setattr(kb_api, \\\"_guard_kb_action\\\", guard)\\n        monkeypatch.setattr(kb_api, \\\"require_model_provider\\\", policy_check)\\n\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"name\\\": \\\"Spoofed Provider KB\\\",\\n                \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n                \\\"model_selection\\\": {\\n                    \\\"name\\\": \\\"text-embedding-3-small\\\",\\n                    \\\"provider\\\": \\\"Anthropic\\\",\\n                },\\n            },\\n        )\\n\\n        assert response.status_code == 404\\n        assert response.json() == {\\\"detail\\\": \\\"Model provider not found\\\"}\\n        root_path.assert_not_called()\\n        guard.assert_not_awaited()\\n        policy_check.assert_not_called()\\n\\n    async def test_create_denied_embedding_provider_is_hidden_before_storage_or_db(\\n        self, client: AsyncClient, logged_in_headers, monkeypatch\\n    ):\\n        from langflow.api.v1 import knowledge_bases as kb_api\\n        from lfx.services.model_provider_policy import ModelProviderPolicyError, ModelProviderPolicyPurpose\\n\\n        root_path = MagicMock()\\n        guard = AsyncMock()\\n        policy_check = MagicMock(\\n            side_effect=ModelProviderPolicyError(\\\"anthropic\\\", ModelProviderPolicyPurpose.CONFIGURE)\\n        )\\n        monkeypatch.setattr(kb_api.KBStorageHelper, \\\"get_root_path\\\", root_path)\\n        monkeypatch.setattr(kb_api, \\\"_guard_kb_action\\\", guard)\\n        monkeypatch.setattr(kb_api, \\\"require_model_provider\\\", policy_check)\\n\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"name\\\": \\\"Denied Provider KB\\\",\\n                \\\"embedding_provider\\\": \\\"Anthropic\\\",\\n                \\\"embedding_model\\\": \\\"claude-embed\\\",\\n                \\\"model_selection\\\": {\\\"name\\\": \\\"claude-embed\\\", \\\"provider\\\": \\\"Anthropic\\\"},\\n            },\\n        )\\n\\n        assert response.status_code == 404\\n        assert response.json() == {\\\"detail\\\": \\\"Model provider not found\\\"}\\n        root_path.assert_not_called()\\n        guard.assert_not_awaited()\\n        policy_check.assert_called_once_with(\\n            user_id=ANY,\\n            provider=\\\"Anthropic\\\",\\n            purpose=ModelProviderPolicyPurpose.CONFIGURE,\\n        )\\n\\n    async def test_create_knowledge_base_rejects_unknown_backend(self, client: AsyncClient, logged_in_headers):\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"name\\\": \\\"Bad_Backend_KB\\\",\\n                \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n                \\\"backend_type\\\": \\\"not-a-backend\\\",\\n            },\\n        )\\n\\n        assert response.status_code == 422\\n        assert \\\"unknown vector-store backend\\\" in response.text.lower()\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_fresh_chroma_client\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_create_knowledge_base_opensearch_without_index_name(\\n        self, mock_root, mock_fresh_client, client: AsyncClient, logged_in_headers, tmp_path\\n    ):\\n        # OpenSearch KBs no longer require an ``index_name`` in\\n        # ``backend_config``: the backend derives a unique index per KB from\\n        # its name and creates it lazily on first write. An empty\\n        # ``backend_config`` must therefore be accepted, not rejected.\\n        from lfx.base.knowledge_bases.backends.base import TestConnectionResult\\n        from lfx.base.knowledge_bases.backends.opensearch import OpenSearchBackend\\n\\n        mock_fresh_client.return_value = MagicMock()\\n        mock_root.return_value = tmp_path\\n        connection_result = TestConnectionResult(ok=True, message=\\\"Connected\\\")\\n        with patch.object(OpenSearchBackend, \\\"test_connection\\\", new=AsyncMock(return_value=connection_result)):\\n            response = await client.post(\\n                \\\"api/v1/knowledge_bases\\\",\\n                headers=logged_in_headers,\\n                json={\\n                    \\\"name\\\": \\\"OpenSearch_No_Index_KB\\\",\\n                    \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                    \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n                    \\\"backend_type\\\": \\\"opensearch\\\",\\n                    \\\"backend_config\\\": {},\\n                },\\n            )\\n\\n        assert response.status_code == 201, response.text\\n        data = response.json()\\n        assert data[\\\"backend_type\\\"] == \\\"opensearch\\\"\\n        # No shared index pinned into the config \u2014 the index is derived per-KB.\\n        assert \\\"index_name\\\" not in data[\\\"backend_config\\\"]\\n        mock_fresh_client.assert_not_called()\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_create_knowledge_base_postgres_persists_backend(\\n        self,\\n        mock_root,\\n        client: AsyncClient,\\n        logged_in_headers,\\n        active_user,\\n        tmp_path,\\n    ):\\n        from lfx.base.knowledge_bases.backends.base import TestConnectionResult\\n        from lfx.base.knowledge_bases.backends.postgres import PostgresBackend\\n\\n        mock_root.return_value = tmp_path\\n        connection_result = TestConnectionResult(ok=True, message=\\\"Connected\\\")\\n        with patch.object(PostgresBackend, \\\"test_connection\\\", new=AsyncMock(return_value=connection_result)):\\n            response = await client.post(\\n                \\\"api/v1/knowledge_bases\\\",\\n                headers=logged_in_headers,\\n                json={\\n                    \\\"name\\\": \\\"Postgres_KB\\\",\\n                    \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                    \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n                    \\\"backend_type\\\": \\\"postgres\\\",\\n                    \\\"backend_config\\\": {},\\n                },\\n            )\\n\\n        assert response.status_code == 201, response.text\\n        assert response.json()[\\\"backend_type\\\"] == \\\"postgres\\\"\\n        assert response.json()[\\\"backend_config\\\"] == {}\\n        record = await knowledge_base_service.get_by_user_and_name(active_user.id, \\\"Postgres_KB\\\")\\n        assert record is not None\\n        assert record.backend_type == \\\"postgres\\\"\\n        assert record.backend_config == {}\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_create_knowledge_base_rejects_unreachable_remote_backend(\\n        self, mock_root, client: AsyncClient, logged_in_headers, active_user, tmp_path\\n    ):\\n        \\\"\\\"\\\"A KB create against an unreachable remote backend is refused with 422.\\n\\n        The availability gate now covers every remote backend, not just pgvector,\\n        mirroring the Memory Base path: an OpenSearch cluster (or Chroma Cloud,\\n        Mongo, Astra) that fails its connectivity probe is rejected up front\\n        instead of persisting a KB that only errors on first ingestion.\\n        \\\"\\\"\\\"\\n        from lfx.base.knowledge_bases.backends.base import TestConnectionResult\\n        from lfx.base.knowledge_bases.backends.opensearch import OpenSearchBackend\\n\\n        mock_root.return_value = tmp_path\\n        connection_result = TestConnectionResult(ok=False, message=\\\"Could not reach the cluster.\\\")\\n        with patch.object(OpenSearchBackend, \\\"test_connection\\\", new=AsyncMock(return_value=connection_result)):\\n            response = await client.post(\\n                \\\"api/v1/knowledge_bases\\\",\\n                headers=logged_in_headers,\\n                json={\\n                    \\\"name\\\": \\\"Unreachable_OS_KB\\\",\\n                    \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                    \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n                    \\\"backend_type\\\": \\\"opensearch\\\",\\n                    \\\"backend_config\\\": {\\\"index_name\\\": \\\"unreachable_idx\\\"},\\n                },\\n            )\\n\\n        assert response.status_code == 422, response.text\\n        assert \\\"could not reach the cluster\\\" in response.text.lower()\\n        # The gate runs before persistence, so nothing is left behind.\\n        record = await knowledge_base_service.get_by_user_and_name(active_user.id, \\\"Unreachable_OS_KB\\\")\\n        assert record is None\\n\\n    async def test_create_knowledge_base_rejects_stubbed_backend(self, client: AsyncClient, logged_in_headers):\\n        \\\"\\\"\\\"Stubbed backends fail at the schema layer with a \\\"not enabled\\\" message.\\n\\n        The ``BackendType`` enum still includes ``mongodb``/``astra`` for DB row\\n        compatibility, but ``validate_backend_type`` rejects them so a user\\n        posting one gets a clear 422 instead of a successful create followed by\\n        ingest-time NotImplementedError. (``postgres`` is now creation-enabled.)\\n        \\\"\\\"\\\"\\n        for stubbed in (\\\"mongodb\\\", \\\"astra\\\"):\\n            response = await client.post(\\n                \\\"api/v1/knowledge_bases\\\",\\n                headers=logged_in_headers,\\n                json={\\n                    \\\"name\\\": f\\\"Stubbed_{stubbed}_KB\\\",\\n                    \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                    \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n                    \\\"backend_type\\\": stubbed,\\n                    # Provide config that *would* have been valid pre-stub\\n                    # so the rejection is unambiguously about the backend\\n                    # being disabled, not about missing required fields.\\n                    \\\"backend_config\\\": {\\n                        \\\"collection_name\\\": \\\"x\\\",\\n                        \\\"database\\\": \\\"x\\\",\\n                        \\\"collection\\\": \\\"x\\\",\\n                    },\\n                },\\n            )\\n\\n            assert response.status_code == 422, (stubbed, response.text)\\n            assert \\\"not enabled\\\" in response.text.lower(), (stubbed, response.text)\\n\\n    async def test_test_connection_chroma_returns_ok(self, client: AsyncClient, logged_in_headers):\\n        \\\"\\\"\\\"Chroma succeeds against a transient temp dir.\\n\\n        The endpoint builds the backend in a tempfile that is cleaned\\n        up before the response is returned, so no on-disk state\\n        outlasts the request.\\n        \\\"\\\"\\\"\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases/test-connection\\\",\\n            headers=logged_in_headers,\\n            json={\\\"backend_type\\\": \\\"chroma\\\", \\\"backend_config\\\": {}},\\n        )\\n        assert response.status_code == 200, response.text\\n        body = response.json()\\n        assert body[\\\"ok\\\"] is True\\n        assert \\\"Chroma\\\" in body[\\\"message\\\"]\\n\\n    async def test_test_connection_rejects_unknown_backend(self, client: AsyncClient, logged_in_headers):\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases/test-connection\\\",\\n            headers=logged_in_headers,\\n            json={\\\"backend_type\\\": \\\"not-a-backend\\\", \\\"backend_config\\\": {}},\\n        )\\n        assert response.status_code == 422\\n        assert \\\"unknown vector-store backend\\\" in response.text.lower()\\n\\n    async def test_test_connection_does_not_require_index_name(self, client: AsyncClient, logged_in_headers):\\n        # ``index_name`` is no longer a required field \u2014 the index is derived\\n        # per-KB and created lazily \u2014 so a config without it must pass request\\n        # validation (no 422) and reach the connectivity check. With no\\n        # OPENSEARCH_URL secret configured in the test env, that check reports\\n        # ok=False, but the request itself is accepted.\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases/test-connection\\\",\\n            headers=logged_in_headers,\\n            json={\\\"backend_type\\\": \\\"opensearch\\\", \\\"backend_config\\\": {}},\\n        )\\n        assert response.status_code == 200, response.text\\n        assert response.json()[\\\"ok\\\"] is False\\n\\n    async def test_test_connection_returns_failure_for_unreachable_opensearch(\\n        self, client: AsyncClient, logged_in_headers\\n    ):\\n        \\\"\\\"\\\"Reachability failures return HTTP 200 with ``ok=False``.\\n\\n        Credential and connectivity failures are an *expected* result,\\n        not an error condition \u2014 the frontend differentiates by the\\n        ``ok`` field rather than the HTTP status code.\\n        \\\"\\\"\\\"\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases/test-connection\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"backend_type\\\": \\\"opensearch\\\",\\n                \\\"backend_config\\\": {\\n                    \\\"url_variable\\\": \\\"OPENSEARCH_URL_TEST_DOES_NOT_EXIST\\\",\\n                    \\\"index_name\\\": \\\"any_idx\\\",\\n                },\\n            },\\n        )\\n        assert response.status_code == 200, response.text\\n        body = response.json()\\n        assert body[\\\"ok\\\"] is False\\n        assert body[\\\"message\\\"]\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_create_kb_path_traversal_single_level(\\n        self, mock_root, client: AsyncClient, logged_in_headers, tmp_path\\n    ):\\n        \\\"\\\"\\\"Single-level traversal '../victim_user/evil_kb' in POST must be blocked with 400/403.\\n\\n        VULNERABILITY: the create endpoint builds kb_path = kb_root_path / kb_user / kb_name\\n        without resolve() or is_relative_to(), so '../victim_user/evil_kb' escapes the user dir.\\n        \\\"\\\"\\\"\\n        mock_root.return_value = tmp_path\\n        (tmp_path / \\\"activeuser\\\").mkdir(parents=True)\\n        victim_dir = tmp_path / \\\"victim_user\\\" / \\\"evil_kb\\\"\\n\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"name\\\": \\\"../victim_user/evil_kb\\\",\\n                \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n            },\\n        )\\n\\n        assert response.status_code in (400, 403), (\\n            f\\\"VULNERABILITY CONFIRMED: create endpoint accepted traversal payload with status {response.status_code}\\\"\\n        )\\n        assert not victim_dir.exists(), (\\n            \\\"VULNERABILITY CONFIRMED: path traversal created a directory outside the user's KB root\\\"\\n        )\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_create_kb_path_traversal_absolute_path(\\n        self, mock_root, client: AsyncClient, logged_in_headers, tmp_path\\n    ):\\n        \\\"\\\"\\\"Absolute path in kb_name must be blocked \u2014 e.g. '/tmp/evil'.\\n\\n        VULNERABILITY: kb_root_path / kb_user / '/tmp/evil' resolves to '/tmp/evil' in Python\\n        because Path drops all previous components when a segment starts with '/'.\\n        \\\"\\\"\\\"\\n        mock_root.return_value = tmp_path\\n        (tmp_path / \\\"activeuser\\\").mkdir(parents=True)\\n        evil_dir = tmp_path / \\\"evil_absolute\\\"\\n\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"name\\\": str(evil_dir),\\n                \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n            },\\n        )\\n\\n        assert response.status_code in (400, 403), (\\n            f\\\"VULNERABILITY CONFIRMED: create endpoint accepted absolute path payload \\\"\\n            f\\\"with status {response.status_code}\\\"\\n        )\\n        assert not evil_dir.exists(), (\\n            \\\"VULNERABILITY CONFIRMED: absolute path in kb_name created a directory outside the KB root\\\"\\n        )\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_create_kb_path_traversal_prefix_ambiguity(\\n        self, mock_root, client: AsyncClient, logged_in_headers, tmp_path\\n    ):\\n        \\\"\\\"\\\"Prefix-ambiguity attack on create: user='activeuser', target dir='activeuser_evil'.\\n\\n        With startswith('/root/activeuser'), the path '/root/activeuser_evil/secret_kb'\\n        incorrectly passes because the string starts with '/root/activeuser'.\\n        is_relative_to() closes this gap and must block the request with 400/403.\\n        \\\"\\\"\\\"\\n        mock_root.return_value = tmp_path\\n\\n        (tmp_path / \\\"activeuser\\\").mkdir(parents=True)\\n        victim_kb = tmp_path / \\\"activeuser_evil\\\" / \\\"secret_kb\\\"\\n        victim_kb.mkdir(parents=True)\\n\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"name\\\": \\\"../activeuser_evil/secret_kb\\\",\\n                \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n            },\\n        )\\n\\n        assert response.status_code in (400, 403), (\\n            \\\"VULNERABILITY CONFIRMED: prefix-ambiguity bypass succeeded on create endpoint \u2014 \\\"\\n            \\\"startswith() may still be in use instead of is_relative_to()\\\"\\n        )\\n        assert not (tmp_path / \\\"activeuser_evil\\\" / \\\"secret_kb_new\\\").exists(), (\\n            \\\"VULNERABILITY CONFIRMED: prefix-ambiguity attack created a directory outside the user's KB root\\\"\\n        )\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.logger.warning\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_create_kb_path_traversal_logs_warning(\\n        self, mock_root, mock_warning, client: AsyncClient, logged_in_headers, tmp_path\\n    ):\\n        \\\"\\\"\\\"A traversal attempt on create must emit a warning log with user= and kb_name= context.\\\"\\\"\\\"\\n        mock_root.return_value = tmp_path\\n\\n        (tmp_path / \\\"activeuser\\\").mkdir(parents=True)\\n        (tmp_path / \\\"victim_user\\\" / \\\"secret_kb\\\").mkdir(parents=True)\\n\\n        await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"name\\\": \\\"../victim_user/secret_kb\\\",\\n                \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n            },\\n        )\\n\\n        mock_warning.assert_called_once()\\n        warning_args = mock_warning.call_args[0]\\n        all_args_str = str(warning_args)\\n        assert \\\"user=\\\" in all_args_str, \\\"Warning log must contain 'user=' in the format string\\\"\\n        assert \\\"kb_name=\\\" in all_args_str, \\\"Warning log must contain 'kb_name=' in the format string\\\"\\n\\n    @pytest.mark.parametrize(\\n        (\\\"backend_type\\\", \\\"backend_config\\\"),\\n        [\\n            (\\\"opensearch\\\", {}),\\n            (\\\"postgres\\\", {}),\\n            (\\\"chroma\\\", {\\\"mode\\\": \\\"cloud\\\"}),\\n        ],\\n    )\\n    async def test_create_kb_path_traversal_blocked_on_remote_backend(\\n        self, client: AsyncClient, logged_in_headers, active_user, backend_type, backend_config\\n    ):\\n        \\\"\\\"\\\"Traversal names must be rejected on remote backends too \u2014 regression for the bypass.\\n\\n        Remote backends resolve no local path, so the containment guard in\\n        ``resolve_local_store_path`` never runs for them. Name validation must\\n        therefore happen before backend routing, otherwise a name like\\n        ``../victim_user/evil_kb`` is accepted and persisted verbatim (no 422\\n        connectivity check is ever reached because the traversal name is caught\\n        first).\\n        \\\"\\\"\\\"\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"name\\\": \\\"../victim_user/evil_kb\\\",\\n                \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n                \\\"backend_type\\\": backend_type,\\n                \\\"backend_config\\\": backend_config,\\n            },\\n        )\\n\\n        assert response.status_code == 403, (\\n            f\\\"VULNERABILITY CONFIRMED: traversal name accepted on {backend_type!r} with status {response.status_code}\\\"\\n        )\\n        # Nothing was persisted under the crafted name.\\n        assert await knowledge_base_service.get_by_user_and_name(active_user.id, \\\"../victim_user/evil_kb\\\") is None\\n\\n    async def test_create_kb_name_too_short(self, client: AsyncClient, logged_in_headers):\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"name\\\": \\\"ab\\\",\\n                \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                \\\"embedding_model\\\": \\\"model\\\",\\n            },\\n        )\\n        assert response.status_code == 400\\n        assert \\\"at least 3 characters\\\" in response.json()[\\\"detail\\\"]\\n\\n    @pytest.mark.parametrize(\\n        \\\"name\\\",\\n        [\\\"Q&A docs\\\", \\\"cat\u00e1logo-produtos\\\", \\\"trailing_\\\", \\\"docs..v2\\\", \\\"127.0.0.1\\\", \\\"a\\\" * 513],\\n    )\\n    async def test_create_kb_rejects_chroma_incompatible_name_before_persistence(\\n        self,\\n        name,\\n        client: AsyncClient,\\n        logged_in_headers,\\n        active_user,\\n        monkeypatch,\\n    ):\\n        from langflow.api.v1 import knowledge_bases as kb_api\\n\\n        root_path = MagicMock()\\n        monkeypatch.setattr(kb_api.KBStorageHelper, \\\"get_root_path\\\", root_path)\\n\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"name\\\": name,\\n                \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                \\\"embedding_model\\\": \\\"model\\\",\\n            },\\n        )\\n\\n        assert response.status_code == 400, response.text\\n        assert \\\"3-512 characters\\\" in response.json()[\\\"detail\\\"]\\n        root_path.assert_not_called()\\n        normalized_name = name.strip().replace(\\\" \\\", \\\"_\\\")\\n        assert await knowledge_base_service.get_by_user_and_name(active_user.id, normalized_name) is None\\n\\n    @pytest.mark.parametrize(\\\"name\\\", [\\\"docs.v2\\\", \\\"a\\\" * 100, \\\"topology+collection\\\"])\\n    async def test_create_kb_accepts_full_chroma_name_contract(\\n        self,\\n        name,\\n        client: AsyncClient,\\n        logged_in_headers,\\n        active_user,\\n        tmp_path,\\n        monkeypatch,\\n    ):\\n        from langflow.api.v1 import knowledge_bases as kb_api\\n\\n        mock_chroma_client = MagicMock()\\n        monkeypatch.setattr(kb_api.KBStorageHelper, \\\"get_root_path\\\", MagicMock(return_value=tmp_path))\\n        monkeypatch.setattr(\\n            kb_api.KBStorageHelper,\\n            \\\"get_fresh_chroma_client\\\",\\n            MagicMock(return_value=mock_chroma_client),\\n        )\\n\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"name\\\": name,\\n                \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                \\\"embedding_model\\\": \\\"model\\\",\\n            },\\n        )\\n\\n        assert response.status_code == 201, response.text\\n        mock_chroma_client.create_collection.assert_called_once()\\n        assert await knowledge_base_service.get_by_user_and_name(active_user.id, name) is not None\\n\\n    async def test_create_kb_rejects_name_too_long_for_local_chroma(\\n        self,\\n        client: AsyncClient,\\n        logged_in_headers,\\n        active_user,\\n        monkeypatch,\\n    ):\\n        from langflow.api.v1 import knowledge_bases as kb_api\\n\\n        root_path = MagicMock()\\n        monkeypatch.setattr(kb_api.KBStorageHelper, \\\"get_root_path\\\", root_path)\\n        name = \\\"a\\\" * 256\\n\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"name\\\": name,\\n                \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                \\\"embedding_model\\\": \\\"model\\\",\\n            },\\n        )\\n\\n        assert response.status_code == 400, response.text\\n        assert \\\"at most 255 characters for local Chroma storage\\\" in response.json()[\\\"detail\\\"]\\n        root_path.assert_not_called()\\n        assert await knowledge_base_service.get_by_user_and_name(active_user.id, name) is None\\n\\n    async def test_create_kb_does_not_apply_chroma_rules_to_postgres(\\n        self,\\n        client: AsyncClient,\\n        logged_in_headers,\\n        active_user,\\n    ):\\n        from lfx.base.knowledge_bases.backends.base import TestConnectionResult\\n        from lfx.base.knowledge_bases.backends.postgres import PostgresBackend\\n\\n        connection_result = TestConnectionResult(ok=True, message=\\\"Connected\\\")\\n        with patch.object(PostgresBackend, \\\"test_connection\\\", new=AsyncMock(return_value=connection_result)):\\n            response = await client.post(\\n                \\\"api/v1/knowledge_bases\\\",\\n                headers=logged_in_headers,\\n                json={\\n                    \\\"name\\\": \\\"Q&A_docs\\\",\\n                    \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                    \\\"embedding_model\\\": \\\"model\\\",\\n                    \\\"backend_type\\\": \\\"postgres\\\",\\n                    \\\"backend_config\\\": {},\\n                },\\n            )\\n\\n        assert response.status_code == 201, response.text\\n        record = await knowledge_base_service.get_by_user_and_name(active_user.id, \\\"Q&A_docs\\\")\\n        assert record is not None\\n        assert record.backend_type == \\\"postgres\\\"\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_create_duplicate_kb(self, mock_root, client: AsyncClient, logged_in_headers, tmp_path):\\n        mock_root.return_value = tmp_path\\n        kb_user_path = tmp_path / \\\"activeuser\\\"\\n        kb_user_path.mkdir(parents=True)\\n        (kb_user_path / \\\"Duplicate_KB\\\").mkdir()\\n\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"name\\\": \\\"Duplicate KB\\\",\\n                \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                \\\"embedding_model\\\": \\\"model\\\",\\n            },\\n        )\\n        assert response.status_code == 409\\n        assert \\\"already exists\\\" in response.json()[\\\"detail\\\"]\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_create_duplicate_kb_rejects_existing_db_row_without_directory(\\n        self,\\n        mock_root,\\n        client: AsyncClient,\\n        logged_in_headers,\\n        active_user,\\n        tmp_path,\\n    ):\\n        mock_root.return_value = tmp_path\\n        await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=\\\"Duplicate_DB_KB\\\",\\n            model_selection={\\\"name\\\": \\\"model\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n        )\\n\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"name\\\": \\\"Duplicate DB KB\\\",\\n                \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                \\\"embedding_model\\\": \\\"model\\\",\\n            },\\n        )\\n\\n        assert response.status_code == 409\\n        assert \\\"already exists\\\" in response.json()[\\\"detail\\\"]\\n        assert not (tmp_path / active_user.username / \\\"Duplicate_DB_KB\\\").exists()\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.knowledge_base_service.backfill_from_disk\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_list_knowledge_bases(\\n        self, mock_root, mock_backfill, client: AsyncClient, logged_in_headers, active_user, tmp_path\\n    ):\\n        from langflow.api.utils import knowledge_base_service\\n\\n        mock_root.return_value = tmp_path\\n        record = await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=\\\"KB1\\\",\\n            model_selection={\\\"name\\\": \\\"model\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n            backend_type=\\\"opensearch\\\",\\n            backend_config={\\\"index_name\\\": \\\"kb1_index\\\"},\\n        )\\n        await knowledge_base_service.update_stats(\\n            record.id,\\n            chunks=10,\\n            words=100,\\n            characters=500,\\n            size_bytes=1024,\\n        )\\n\\n        response = await client.get(\\\"api/v1/knowledge_bases\\\", headers=logged_in_headers)\\n        assert response.status_code == 200\\n        data = response.json()\\n        assert len(data) >= 1\\n        kb = next(kb for kb in data if kb[\\\"id\\\"] == str(record.id))\\n        assert kb[\\\"backend_type\\\"] == \\\"opensearch\\\"\\n        assert kb[\\\"backend_config\\\"] == {\\\"index_name\\\": \\\"kb1_index\\\"}\\n        assert kb[\\\"size\\\"] == 1024\\n        mock_backfill.assert_not_awaited()\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_list_and_detail_reflect_cleared_db_separator(\\n        self,\\n        mock_root,\\n        client: AsyncClient,\\n        logged_in_headers,\\n        active_user,\\n        tmp_path,\\n    ):\\n        mock_root.return_value = tmp_path\\n        record = await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=\\\"Cleared_Separator_KB\\\",\\n            model_selection={\\\"name\\\": \\\"model\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n            separator=\\\"\\\\n\\\",\\n        )\\n        await knowledge_base_service.update_stats(\\n            record.id,\\n            chunks=3,\\n            words=30,\\n            characters=300,\\n            size_bytes=2048,\\n            chunk_size=512,\\n            chunk_overlap=64,\\n            separator=None,\\n        )\\n\\n        list_response = await client.get(\\\"api/v1/knowledge_bases\\\", headers=logged_in_headers)\\n        assert list_response.status_code == 200\\n        listed = next(kb for kb in list_response.json() if kb[\\\"id\\\"] == str(record.id))\\n        assert listed[\\\"chunk_size\\\"] == 512\\n        assert listed[\\\"chunk_overlap\\\"] == 64\\n        assert listed[\\\"separator\\\"] is None\\n\\n        detail_response = await client.get(\\n            \\\"api/v1/knowledge_bases/Cleared_Separator_KB\\\",\\n            headers=logged_in_headers,\\n        )\\n        assert detail_response.status_code == 200\\n        detail = detail_response.json()\\n        assert detail[\\\"chunk_size\\\"] == 512\\n        assert detail[\\\"chunk_overlap\\\"] == 64\\n        assert detail[\\\"separator\\\"] is None\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_list_ignores_kb_directories_with_no_database_row(\\n        self, mock_root, client: AsyncClient, logged_in_headers, tmp_path\\n    ):\\n        \\\"\\\"\\\"A sidecar-only directory is invisible: the ``knowledge_base`` row is the authority.\\n\\n        The list endpoint used to disk-scan when a user had zero rows. That made\\n        the result depend on which replica served the request and re-surfaced\\n        directories whose bytes survived a delete. Adopting a legacy directory is\\n        now an explicit operator action (``langflow reconcile-kb-from-disk``).\\n        \\\"\\\"\\\"\\n        mock_root.return_value = tmp_path\\n        kb_user_path = tmp_path / \\\"activeuser\\\"\\n        kb_user_path.mkdir(parents=True, exist_ok=True)\\n        kb_path = kb_user_path / \\\"Orphan_Dir_KB\\\"\\n        kb_path.mkdir(exist_ok=True)\\n        (kb_path / \\\"embedding_metadata.json\\\").write_text(\\n            json.dumps(\\n                {\\n                    \\\"chunks\\\": 10,\\n                    \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                    \\\"embedding_model\\\": \\\"model\\\",\\n                    \\\"id\\\": str(uuid.uuid4()),\\n                    \\\"backend_type\\\": \\\"opensearch\\\",\\n                    \\\"backend_config\\\": {\\\"index_name\\\": \\\"kb1_index\\\"},\\n                }\\n            )\\n        )\\n\\n        response = await client.get(\\\"api/v1/knowledge_bases\\\", headers=logged_in_headers)\\n        assert response.status_code == 200\\n        assert not any(kb[\\\"dir_name\\\"] == \\\"Orphan_Dir_KB\\\" for kb in response.json())\\n\\n    async def test_remote_backed_kb_is_listable_without_any_local_storage(\\n        self, client: AsyncClient, logged_in_headers, active_user, tmp_path, monkeypatch\\n    ):\\n        \\\"\\\"\\\"The enterprise shape: no local KB directory anywhere, everything still works.\\n\\n        ``knowledge_bases_dir`` points at a path that does not exist, so any code\\n        path that still reached for the filesystem would fail loudly here.\\n        \\\"\\\"\\\"\\n        from langflow.api.v1 import knowledge_bases as kb_api\\n\\n        missing_root = tmp_path / \\\"does\\\" / \\\"not\\\" / \\\"exist\\\"\\n        monkeypatch.setattr(kb_api.KBStorageHelper, \\\"get_root_path\\\", MagicMock(return_value=missing_root))\\n\\n        await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=\\\"Remote_Only_KB\\\",\\n            model_selection={\\\"name\\\": \\\"text-embedding-3-small\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n            backend_type=\\\"opensearch\\\",\\n            backend_config={\\\"index_name\\\": \\\"remote_only\\\"},\\n        )\\n\\n        listing = await client.get(\\\"api/v1/knowledge_bases\\\", headers=logged_in_headers)\\n        assert listing.status_code == 200\\n        assert any(kb[\\\"dir_name\\\"] == \\\"Remote_Only_KB\\\" for kb in listing.json())\\n\\n        detail = await client.get(\\\"api/v1/knowledge_bases/Remote_Only_KB\\\", headers=logged_in_headers)\\n        assert detail.status_code == 200\\n        assert detail.json()[\\\"backend_type\\\"] == \\\"opensearch\\\"\\n        assert not missing_root.exists()\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_get_knowledge_base_detail(\\n        self, mock_root, client: AsyncClient, logged_in_headers, active_user, tmp_path\\n    ):\\n        mock_root.return_value = tmp_path\\n        record = await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=\\\"Detail_KB\\\",\\n            model_selection={\\\"name\\\": \\\"model\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n            backend_type=\\\"postgres\\\",\\n            backend_config={\\\"collection_name\\\": \\\"detail_kb\\\"},\\n            chunks=5,\\n            words=50,\\n            characters=250,\\n            size_bytes=100,\\n        )\\n        assert record is not None\\n\\n        response = await client.get(\\\"api/v1/knowledge_bases/Detail_KB\\\", headers=logged_in_headers)\\n        assert response.status_code == 200\\n        data = response.json()\\n        assert data[\\\"chunks\\\"] == 5\\n        assert data[\\\"name\\\"] == \\\"Detail KB\\\"\\n        assert data[\\\"backend_type\\\"] == \\\"postgres\\\"\\n        assert data[\\\"backend_config\\\"] == {\\\"collection_name\\\": \\\"detail_kb\\\"}\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_get_knowledge_base_detail_404s_for_directory_without_row(\\n        self, mock_root, client: AsyncClient, logged_in_headers, tmp_path\\n    ):\\n        \\\"\\\"\\\"A directory with a sidecar but no row does not exist as far as the API is concerned.\\\"\\\"\\\"\\n        mock_root.return_value = tmp_path\\n        kb_path = tmp_path / \\\"activeuser\\\" / \\\"Sidecar_Only_KB\\\"\\n        kb_path.mkdir(parents=True)\\n        (kb_path / \\\"embedding_metadata.json\\\").write_text(\\n            json.dumps({\\\"embedding_provider\\\": \\\"OpenAI\\\", \\\"embedding_model\\\": \\\"model\\\"})\\n        )\\n\\n        response = await client.get(\\\"api/v1/knowledge_bases/Sidecar_Only_KB\\\", headers=logged_in_headers)\\n        assert response.status_code == 404\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_get_knowledge_base_detail_prefers_db_row_when_dir_missing(\\n        self, mock_root, client: AsyncClient, logged_in_headers, active_user, tmp_path\\n    ):\\n        from langflow.api.utils import knowledge_base_service\\n\\n        mock_root.return_value = tmp_path\\n        record = await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=\\\"DB_Only_KB\\\",\\n            model_selection={\\\"name\\\": \\\"model\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n            backend_type=\\\"opensearch\\\",\\n            backend_config={\\\"index_name\\\": \\\"db_only_index\\\"},\\n        )\\n        await knowledge_base_service.update_stats(\\n            record.id,\\n            chunks=5,\\n            words=50,\\n            characters=250,\\n            size_bytes=100,\\n        )\\n\\n        response = await client.get(\\\"api/v1/knowledge_bases/DB_Only_KB\\\", headers=logged_in_headers)\\n        assert response.status_code == 200\\n        data = response.json()\\n        assert data[\\\"id\\\"] == str(record.id)\\n        assert data[\\\"chunks\\\"] == 5\\n        assert data[\\\"backend_type\\\"] == \\\"opensearch\\\"\\n        assert data[\\\"backend_config\\\"] == {\\\"index_name\\\": \\\"db_only_index\\\"}\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.knowledge_base_service.create_record\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_fresh_chroma_client\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_create_knowledge_base_rolls_back_when_db_persist_fails(\\n        self,\\n        mock_root,\\n        mock_fresh_client,\\n        mock_create_record,\\n        client: AsyncClient,\\n        logged_in_headers,\\n        tmp_path,\\n    ):\\n        mock_root.return_value = tmp_path\\n        mock_fresh_client.return_value = MagicMock()\\n        mock_create_record.side_effect = RuntimeError(\\\"db unavailable\\\")\\n\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\n                \\\"name\\\": \\\"Rollback KB\\\",\\n                \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n            },\\n        )\\n\\n        assert response.status_code == 500\\n        assert not (tmp_path / \\\"activeuser\\\" / \\\"Rollback_KB\\\").exists()\\n\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.delete_storage\\\", return_value=True)\\n    @patch(\\\"langflow.api.v1.knowledge_bases.create_backend\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.knowledge_base_service.delete_by_user_and_name\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.v1.knowledge_bases.knowledge_base_service.get_by_user_and_name\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_delete_knowledge_base(\\n        self,\\n        mock_root,\\n        mock_get_record,\\n        mock_delete_record,\\n        mock_create_backend,\\n        mock_delete,\\n        client: AsyncClient,\\n        logged_in_headers,\\n        tmp_path,\\n    ):\\n        mock_root.return_value = tmp_path\\n        (tmp_path / \\\"activeuser\\\" / \\\"To_Delete\\\").mkdir(parents=True, exist_ok=True)\\n        mock_get_record.return_value = MagicMock(\\n            backend_type=\\\"opensearch\\\",\\n            backend_config={\\\"index_name\\\": \\\"to_delete_index\\\"},\\n        )\\n        backend = MagicMock()\\n        backend.ensure_ready = AsyncMock()\\n        backend.delete_collection = AsyncMock()\\n        backend.teardown = AsyncMock()\\n        mock_create_backend.return_value = backend\\n\\n        response = await client.delete(\\\"api/v1/knowledge_bases/To_Delete\\\", headers=logged_in_headers)\\n        assert response.status_code == 200\\n        mock_create_backend.assert_called_once()\\n        backend.ensure_ready.assert_awaited_once()\\n        backend.delete_collection.assert_awaited_once()\\n        backend.teardown.assert_awaited_once()\\n        mock_delete_record.assert_awaited_once()\\n        # An OpenSearch-backed KB has no local storage to remove, so the\\n        # filesystem is never touched \u2014 not even to check.\\n        mock_delete.assert_not_called()\\n        assert mock_create_backend.call_args.kwargs[\\\"kb_path\\\"] is None\\n\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.delete_storage\\\", return_value=True)\\n    @patch(\\\"langflow.api.v1.knowledge_bases.create_backend\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.knowledge_base_service.delete_by_user_and_name\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.v1.knowledge_bases.knowledge_base_service.get_by_user_and_name\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_delete_knowledge_base_survives_remote_backend_auth_failure(\\n        self,\\n        mock_root,\\n        mock_get_record,\\n        mock_delete_record,  # noqa: ARG002 - patch fixture; presence is the assertion\\n        mock_create_backend,\\n        mock_delete,\\n        client: AsyncClient,\\n        logged_in_headers,\\n        tmp_path,\\n    ):\\n        \\\"\\\"\\\"Remote-backend cleanup failure must not block local delete.\\n\\n        Regression for the Astra delete bug: a missing/stale Astra\\n        token used to raise ``ValueError`` from\\n        ``backend.ensure_ready`` which propagated as HTTP 500. The KB\\n        directory + DB row were never cleaned up and the UI showed\\n        the entry indefinitely. The fix makes remote cleanup\\n        best-effort and surfaces the failure as a ``warning`` field\\n        alongside the successful local delete.\\n        \\\"\\\"\\\"\\n        mock_root.return_value = tmp_path\\n        (tmp_path / \\\"activeuser\\\" / \\\"Stuck_Astra\\\").mkdir(parents=True, exist_ok=True)\\n        mock_get_record.return_value = MagicMock(\\n            backend_type=\\\"astra\\\",\\n            backend_config={\\\"collection_name\\\": \\\"stuck_astra\\\"},\\n        )\\n        backend = MagicMock()\\n        backend.ensure_ready = AsyncMock(\\n            side_effect=ValueError(\\\"Required credential variable 'ASTRA_DB_APPLICATION_TOKEN' is not configured.\\\")\\n        )\\n        backend.delete_collection = AsyncMock()\\n        backend.teardown = AsyncMock()\\n        mock_create_backend.return_value = backend\\n\\n        response = await client.delete(\\\"api/v1/knowledge_bases/Stuck_Astra\\\", headers=logged_in_headers)\\n\\n        # The row delete still runs and succeeds. Astra keeps nothing on this\\n        # box, so there is no local storage step to run.\\n        assert response.status_code == 200\\n        assert not mock_delete.called\\n        # Teardown runs even though ensure_ready threw.\\n        backend.teardown.assert_awaited_once()\\n        # delete_collection is skipped because ensure_ready raised.\\n        backend.delete_collection.assert_not_awaited()\\n        # Response carries a user-facing warning so the UI can tell\\n        # the operator the remote resources need manual cleanup.\\n        data = response.json()\\n        assert \\\"warning\\\" in data\\n        assert \\\"astra\\\" in data[\\\"warning\\\"].lower()\\n        assert \\\"manual\\\" in data[\\\"warning\\\"].lower()\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.create_backend\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.knowledge_base_service.delete_by_user_and_name\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.v1.knowledge_bases.knowledge_base_service.get_by_user_and_name\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_delete_knowledge_base_cleans_up_orphan_db_row(\\n        self,\\n        mock_root,\\n        mock_get_record,\\n        mock_delete_record,\\n        mock_create_backend,\\n        client: AsyncClient,\\n        logged_in_headers,\\n        tmp_path,\\n    ):\\n        \\\"\\\"\\\"A remote-backed KB with no local directory must still be deletable.\\n\\n        Regression for the Astra delete bug: the endpoint used to require the\\n        directory to exist, so a remote-backed KB (which never has one) 404'd on\\n        delete while the list endpoint \u2014 reading the DB row \u2014 kept showing it.\\n        The UI was stuck. Existence is the row's call now, so this is the normal\\n        path rather than a special case.\\n        \\\"\\\"\\\"\\n        mock_root.return_value = tmp_path\\n        (tmp_path / \\\"activeuser\\\").mkdir(parents=True, exist_ok=True)\\n        # A row, and no on-disk directory \u2014 the ordinary shape for a\\n        # remote-backed KB.\\n        mock_get_record.return_value = MagicMock(\\n            backend_type=\\\"astra\\\",\\n            backend_config={\\\"collection_name\\\": \\\"orphan_astra\\\"},\\n        )\\n        backend = MagicMock()\\n        backend.ensure_ready = AsyncMock()\\n        backend.delete_collection = AsyncMock()\\n        backend.teardown = AsyncMock()\\n        mock_create_backend.return_value = backend\\n\\n        response = await client.delete(\\\"api/v1/knowledge_bases/Orphan_KB\\\", headers=logged_in_headers)\\n\\n        assert response.status_code == 200\\n        # Remote collection + DB row both cleaned up.\\n        backend.ensure_ready.assert_awaited_once()\\n        backend.delete_collection.assert_awaited_once()\\n        backend.teardown.assert_awaited_once()\\n        mock_delete_record.assert_awaited_once()\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.knowledge_base_service.get_by_user_and_name\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_delete_knowledge_base_truly_missing_still_404s(\\n        self,\\n        mock_root,\\n        mock_get_record,\\n        client: AsyncClient,\\n        logged_in_headers,\\n        tmp_path,\\n    ):\\n        \\\"\\\"\\\"No directory AND no DB row \u2192 still 404.\\n\\n        The orphan cleanup must not mask genuine not-found cases \u2014\\n        those should keep returning 404 so callers can distinguish a\\n        typo from a dangling row.\\n        \\\"\\\"\\\"\\n        mock_root.return_value = tmp_path\\n        (tmp_path / \\\"activeuser\\\").mkdir(parents=True, exist_ok=True)\\n        mock_get_record.return_value = None\\n\\n        response = await client.delete(\\\"api/v1/knowledge_bases/Nonexistent\\\", headers=logged_in_headers)\\n        assert response.status_code == 404\\n\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.delete_storage\\\", return_value=True)\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_delete_knowledge_base_cancels_inflight_ingestion(\\n        self,\\n        mock_root,\\n        mock_delete,  # noqa: ARG002\\n        client: AsyncClient,\\n        logged_in_headers,\\n        active_user,\\n        tmp_path,\\n    ):\\n        \\\"\\\"\\\"Deleting a KB while ingestion is in flight must cancel the job.\\n\\n        Regression for the \\\"deleted KB reappears after ~5s\\\" bug.\\n        Without cancellation, the background ingestion keeps writing\\n        chunks via the backend's persistent client, which auto-recreates\\n        the KB directory after rmtree. The list endpoint's disk-fallback\\n        path then re-discovers the recreated dir and the KB pops back\\n        into the UI.\\n\\n        Verifies that:\\n        - Any ``QUEUED``/``IN_PROGRESS`` job for the KB transitions to\\n          ``CANCELLED`` with a ``finished_timestamp`` set.\\n        - The KB row itself is removed.\\n        \\\"\\\"\\\"\\n        from langflow.services.database.models.jobs.model import JobStatus, JobType\\n        from langflow.services.deps import get_job_service\\n\\n        mock_root.return_value = tmp_path\\n        kb_name = \\\"Inflight_Ingest_KB\\\"\\n\\n        # A row is all a KB needs to exist; the local-Chroma directory is\\n        # created here only so the storage-cleanup step has something to remove.\\n        record = await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=kb_name,\\n            model_selection={\\\"name\\\": \\\"text-embedding-3-small\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n        )\\n        (tmp_path / active_user.username / kb_name).mkdir(parents=True)\\n\\n        # Seed an in-flight ingestion job for that KB.\\n        job_service = get_job_service()\\n        job_id = uuid.uuid4()\\n        await job_service.create_job(\\n            job_id=job_id,\\n            flow_id=job_id,\\n            job_type=JobType.INGESTION,\\n            asset_id=record.id,\\n            asset_type=\\\"knowledge_base\\\",\\n            user_id=active_user.id,\\n        )\\n        await job_service.update_job_status(job_id, JobStatus.IN_PROGRESS)\\n\\n        response = await client.delete(\\n            f\\\"api/v1/knowledge_bases/{kb_name}\\\",\\n            headers=logged_in_headers,\\n        )\\n\\n        assert response.status_code == 200\\n\\n        cancelled_job = await job_service.get_job_by_job_id(job_id)\\n        assert cancelled_job is not None\\n        assert cancelled_job.status == JobStatus.CANCELLED\\n        assert cancelled_job.finished_timestamp is not None\\n\\n        # The KB row is gone \u2014 the ingestion can no longer rehydrate\\n        # it because its next ``is_job_cancelled`` poll will trip.\\n        refetched = await knowledge_base_service.get_by_user_and_name(active_user.id, kb_name)\\n        assert refetched is None\\n\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.delete_storage\\\", return_value=True)\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_delete_knowledge_base_leaves_unrelated_jobs_alone(\\n        self,\\n        mock_root,\\n        mock_delete,  # noqa: ARG002\\n        client: AsyncClient,\\n        logged_in_headers,\\n        active_user,\\n        tmp_path,\\n    ):\\n        \\\"\\\"\\\"Cancel-on-delete must scope strictly to the deleted KB.\\n\\n        A user with multiple KBs ingesting in parallel should not see\\n        their OTHER ingestions cancelled when one KB is deleted. The\\n        scope is enforced via ``(asset_id, asset_type)`` \u2014 this test\\n        regresses against an over-broad query that would match every\\n        ``IN_PROGRESS`` job.\\n        \\\"\\\"\\\"\\n        from langflow.services.database.models.jobs.model import JobStatus, JobType\\n        from langflow.services.deps import get_job_service\\n\\n        mock_root.return_value = tmp_path\\n        kb_name = \\\"Target_KB\\\"\\n        other_kb_name = \\\"Untouched_KB\\\"\\n\\n        target = await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=kb_name,\\n            model_selection={\\\"name\\\": \\\"text-embedding-3-small\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n        )\\n        other = await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=other_kb_name,\\n            model_selection={\\\"name\\\": \\\"text-embedding-3-small\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n        )\\n        for r in (target, other):\\n            d = tmp_path / active_user.username / r.name\\n            d.mkdir(parents=True)\\n            (d / \\\"embedding_metadata.json\\\").write_text(json.dumps({\\\"id\\\": str(r.id)}))\\n\\n        job_service = get_job_service()\\n        target_job_id = uuid.uuid4()\\n        other_job_id = uuid.uuid4()\\n        for jid, asset_id in ((target_job_id, target.id), (other_job_id, other.id)):\\n            await job_service.create_job(\\n                job_id=jid,\\n                flow_id=jid,\\n                job_type=JobType.INGESTION,\\n                asset_id=asset_id,\\n                asset_type=\\\"knowledge_base\\\",\\n                user_id=active_user.id,\\n            )\\n            await job_service.update_job_status(jid, JobStatus.IN_PROGRESS)\\n\\n        response = await client.delete(\\n            f\\\"api/v1/knowledge_bases/{kb_name}\\\",\\n            headers=logged_in_headers,\\n        )\\n        assert response.status_code == 200\\n\\n        target_job = await job_service.get_job_by_job_id(target_job_id)\\n        other_job = await job_service.get_job_by_job_id(other_job_id)\\n        assert target_job is not None\\n        assert target_job.status == JobStatus.CANCELLED\\n        assert other_job is not None\\n        assert other_job.status == JobStatus.IN_PROGRESS\\n\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.delete_storage\\\", return_value=True)\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_bulk_delete_knowledge_bases(\\n        self, mock_root, mock_delete, client: AsyncClient, logged_in_headers, tmp_path, seed_kb\\n    ):\\n        mock_root.return_value = tmp_path\\n        kb_user_path = tmp_path / \\\"activeuser\\\"\\n        kb_user_path.mkdir(parents=True)\\n        for name in (\\\"KB1\\\", \\\"KB2\\\"):\\n            (kb_user_path / name).mkdir()\\n            await seed_kb(name)\\n\\n        response = await client.request(\\n            \\\"DELETE\\\",\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\\"kb_names\\\": [\\\"KB1\\\", \\\"KB2\\\", \\\"NonExistent\\\"]},\\n        )\\n        assert response.status_code == 200\\n        data = response.json()\\n        assert data[\\\"deleted_count\\\"] == 2\\n        assert \\\"NonExistent\\\" in data[\\\"not_found\\\"]\\n        assert mock_delete.called\\n\\n    @patch(\\\"langflow.api.utils.knowledge_base_service.get_by_user_and_name\\\")\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.delete_storage\\\", return_value=True)\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_bulk_delete_skips_memory_base_kbs(\\n        self,\\n        mock_root,\\n        mock_delete,\\n        mock_get_record,\\n        client: AsyncClient,\\n        logged_in_headers,\\n        tmp_path,\\n    ):\\n        # Memory-Base KBs in a bulk request must be reported back as\\n        # ``memory_base_skipped`` and NOT touched on disk; non-MB KBs in\\n        # the same request still delete normally.\\n        #\\n        # Detection is DB-backed: Memory Bases no longer write the on-disk\\n        # sidecar, so the marker is read from the ``knowledge_base`` row's\\n        # ``source_types`` (via ``get_by_user_and_name``), not ``get_metadata``.\\n        mock_root.return_value = tmp_path\\n        kb_user_path = tmp_path / \\\"activeuser\\\"\\n        kb_user_path.mkdir(parents=True)\\n        (kb_user_path / \\\"PlainKB\\\").mkdir()\\n        (kb_user_path / \\\"MBKB\\\").mkdir()\\n\\n        def fake_record(_user_id, name):\\n            # ``user_id`` a non-UUID so ``_guard_kb_action`` keeps the actor as\\n            # the owner; ``source_types`` carries the Memory-Base marker on MBKB.\\n            return MagicMock(\\n                id=uuid.uuid4(),\\n                user_id=MagicMock(),\\n                source_types=[\\\"memory\\\"] if name == \\\"MBKB\\\" else [],\\n                backend_type=\\\"chroma\\\",\\n                backend_config={},\\n                model_selection={\\\"name\\\": \\\"m\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n            )\\n\\n        mock_get_record.side_effect = fake_record\\n\\n        response = await client.request(\\n            \\\"DELETE\\\",\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\\"kb_names\\\": [\\\"PlainKB\\\", \\\"MBKB\\\"]},\\n        )\\n        assert response.status_code == 200\\n        data = response.json()\\n        assert data[\\\"deleted_count\\\"] == 1\\n        assert data.get(\\\"memory_base_skipped\\\") == \\\"MBKB\\\"\\n        # delete_storage must only have been called for the non-MB KB.\\n        deleted_paths = [call.args[0].name for call in mock_delete.call_args_list]\\n        assert \\\"PlainKB\\\" in deleted_paths\\n        assert \\\"MBKB\\\" not in deleted_paths\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.create_backend\\\")\\n    @patch(\\\"langflow.api.utils.knowledge_base_service.get_by_user_and_name\\\")\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.delete_storage\\\", return_value=True)\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_bulk_delete_skips_memory_base_with_missing_local_dir(\\n        self,\\n        mock_root,\\n        mock_delete,\\n        mock_get_record,\\n        mock_create_backend,\\n        client: AsyncClient,\\n        logged_in_headers,\\n        tmp_path,\\n    ):\\n        # A remote-backed Memory Base with no local directory must still be\\n        # protected: the DB-backed guard runs FIRST, so neither the remote\\n        # collection nor the KB row is ever touched for it.\\n        mock_root.return_value = tmp_path\\n        kb_user_path = tmp_path / \\\"activeuser\\\"\\n        kb_user_path.mkdir(parents=True)  # note: no \\\"MBKB\\\" subdir \u2014 it is remote-backed\\n\\n        def fake_record(_user_id, name):\\n            if name == \\\"MBKB\\\":\\n                return MagicMock(\\n                    id=uuid.uuid4(),\\n                    user_id=MagicMock(),\\n                    source_types=[\\\"memory\\\"],\\n                    backend_type=\\\"opensearch\\\",\\n                    backend_config={\\\"index_name\\\": \\\"mb_index\\\"},\\n                )\\n            return None\\n\\n        mock_get_record.side_effect = fake_record\\n\\n        response = await client.request(\\n            \\\"DELETE\\\",\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\\"kb_names\\\": [\\\"MBKB\\\"]},\\n        )\\n        assert response.status_code == 200\\n        data = response.json()\\n        assert data[\\\"deleted_count\\\"] == 0\\n        assert data.get(\\\"memory_base_skipped\\\") == \\\"MBKB\\\"\\n        # Neither the remote collection nor local storage is touched.\\n        mock_create_backend.assert_not_called()\\n        mock_delete.assert_not_called()\\n\\n    @pytest.mark.parametrize(\\n        (\\\"kb_name\\\", \\\"victim_relpath\\\"),\\n        [\\n            # Single-level traversal into another user's namespace.\\n            (\\\"../victim_user/secret_kb\\\", \\\"victim_user/secret_kb\\\"),\\n            # Multi-level traversal out of the KB root entirely.\\n            (\\\"../../other_root/secret_kb\\\", \\\"other_root/secret_kb\\\"),\\n            # Prefix ambiguity: \\\"activeuser_evil\\\" starts with \\\"activeuser\\\", so a\\n            # startswith() containment check would wrongly accept it. is_relative_to() does not.\\n            (\\\"../activeuser_evil/secret_kb\\\", \\\"activeuser_evil/secret_kb\\\"),\\n            # URL-encoded sequences are NOT decoded by Path \u2014 they stay a literal\\n            # directory name and resolve harmlessly inside the user directory.\\n            (\\\"%2e%2e%2fvictim_user%2fsecret_kb\\\", \\\"victim_user/secret_kb\\\"),\\n        ],\\n    )\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_bulk_delete_traversal_name_without_a_row_is_not_found(\\n        self, mock_root, client: AsyncClient, logged_in_headers, tmp_path, kb_name, victim_relpath\\n    ):\\n        \\\"\\\"\\\"A traversal payload resolves no row, so no path is ever built from it.\\n\\n        Existence is now decided by the ``knowledge_base`` table before any path\\n        is constructed, which makes traversal unreachable rather than merely\\n        rejected: the request 404s having touched no filesystem at all. The\\n        containment guard still exists for the case a row's *name* traverses \u2014\\n        see ``test_bulk_delete_rejects_traversal_when_a_row_carries_the_name``.\\n        \\\"\\\"\\\"\\n        mock_root.return_value = tmp_path\\n        (tmp_path / \\\"activeuser\\\").mkdir(parents=True)\\n        victim_kb = tmp_path / victim_relpath\\n        victim_kb.mkdir(parents=True)\\n\\n        response = await client.request(\\n            \\\"DELETE\\\",\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\\"kb_names\\\": [kb_name]},\\n        )\\n\\n        assert response.status_code == 404, (\\n            f\\\"VULNERABILITY CONFIRMED: server accepted traversal payload with status {response.status_code}\\\"\\n        )\\n        assert victim_kb.exists(), \\\"VULNERABILITY CONFIRMED: path traversal deleted another user's KB\\\"\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_bulk_delete_rejects_traversal_when_a_row_carries_the_name(\\n        self, mock_root, client: AsyncClient, logged_in_headers, tmp_path, seed_kb\\n    ):\\n        \\\"\\\"\\\"The containment guard still fires when a row's own name traverses.\\n\\n        A user can create a KB whose *name* is a traversal string, which gives it\\n        a legitimate row. Path resolution must still refuse to build a path\\n        outside their namespace from it.\\n        \\\"\\\"\\\"\\n        mock_root.return_value = tmp_path\\n        (tmp_path / \\\"activeuser\\\").mkdir(parents=True)\\n        victim_kb = tmp_path / \\\"victim_user\\\" / \\\"secret_kb\\\"\\n        victim_kb.mkdir(parents=True)\\n        await seed_kb(\\\"../victim_user/secret_kb\\\")\\n\\n        response = await client.request(\\n            \\\"DELETE\\\",\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\\"kb_names\\\": [\\\"../victim_user/secret_kb\\\"]},\\n        )\\n\\n        assert response.status_code == 403\\n        assert victim_kb.exists(), \\\"VULNERABILITY CONFIRMED: path traversal deleted another user's KB\\\"\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.logger\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_bulk_delete_path_traversal_logs_warning(\\n        self, mock_root, mock_logger, client: AsyncClient, logged_in_headers, tmp_path, seed_kb\\n    ):\\n        \\\"\\\"\\\"A traversal attempt must emit a warning log with user context.\\\"\\\"\\\"\\n        mock_root.return_value = tmp_path\\n\\n        (tmp_path / \\\"activeuser\\\").mkdir(parents=True)\\n        (tmp_path / \\\"victim_user\\\" / \\\"secret_kb\\\").mkdir(parents=True)\\n        # A row must exist for path resolution \u2014 and therefore the guard \u2014 to run.\\n        await seed_kb(\\\"../victim_user/secret_kb\\\")\\n\\n        await client.request(\\n            \\\"DELETE\\\",\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\\"kb_names\\\": [\\\"../victim_user/secret_kb\\\"]},\\n        )\\n\\n        mock_logger.warning.assert_called_once()\\n        warning_args = mock_logger.warning.call_args[0]\\n        assert \\\"activeuser\\\" in str(warning_args), \\\"Warning log must include the requesting user\\\"\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.get_job_service\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.get_task_service\\\")\\n    async def test_ingest_files(\\n        self,\\n        mock_task,\\n        mock_job,\\n        mock_root,\\n        client: AsyncClient,\\n        logged_in_headers,\\n        tmp_path,\\n        sample_text_file,\\n        seed_kb,\\n    ):\\n        mock_root.return_value = tmp_path\\n        await seed_kb(\\\"Ingest-KB\\\")\\n\\n        file_name, file_content = sample_text_file\\n\\n        mock_task_inst = MagicMock()\\n        mock_task.return_value = mock_task_inst\\n        mock_task_inst.fire_and_forget_task = AsyncMock(return_value=None)\\n\\n        mock_job_inst = MagicMock()\\n        mock_job.return_value = mock_job_inst\\n        mock_job_inst.create_job = AsyncMock(return_value=MagicMock(job_id=uuid.uuid4()))\\n\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases/Ingest-KB/ingest\\\",\\n            headers=logged_in_headers,\\n            files={\\\"files\\\": (file_name, io.BytesIO(file_content.encode()), \\\"text/plain\\\")},\\n            data={\\\"source_name\\\": \\\"test-source\\\"},\\n        )\\n\\n        assert response.status_code == 200\\n        data = response.json()\\n        assert \\\"id\\\" in data\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_ingest_non_existent_kb(self, mock_root, client: AsyncClient, logged_in_headers, tmp_path):\\n        mock_root.return_value = tmp_path\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases/NonExistent/ingest\\\",\\n            headers=logged_in_headers,\\n            files={\\\"files\\\": (\\\"test.txt\\\", io.BytesIO(b\\\"content\\\"), \\\"text/plain\\\")},\\n        )\\n        assert response.status_code == 404\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_ingest_invalid_config(self, mock_root, client: AsyncClient, logged_in_headers, tmp_path, seed_kb):\\n        mock_root.return_value = tmp_path\\n        # A row with no usable embedding selection is a 400, not a crash.\\n        await seed_kb(\\\"Invalid-KB\\\", model_selection={})\\n\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases/Invalid-KB/ingest\\\",\\n            headers=logged_in_headers,\\n            files={\\\"files\\\": (\\\"test.txt\\\", io.BytesIO(b\\\"content\\\"), \\\"text/plain\\\")},\\n        )\\n        assert response.status_code == 400\\n        assert \\\"Invalid embedding configuration\\\" in response.json()[\\\"detail\\\"]\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_ingest_rejects_overlap_larger_than_size(\\n        self, mock_root, client: AsyncClient, logged_in_headers, tmp_path, seed_kb\\n    ):\\n        \\\"\\\"\\\"Ingest must reject overlap > size up front, before any upload work.\\\"\\\"\\\"\\n        mock_root.return_value = tmp_path\\n        await seed_kb(\\\"Overlap-KB\\\")\\n\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases/Overlap-KB/ingest\\\",\\n            headers=logged_in_headers,\\n            files={\\\"files\\\": (\\\"test.txt\\\", io.BytesIO(b\\\"content\\\"), \\\"text/plain\\\")},\\n            data={\\\"chunk_size\\\": \\\"100\\\", \\\"chunk_overlap\\\": \\\"200\\\"},\\n        )\\n        assert response.status_code == 422, response.text\\n        assert \\\"chunk size\\\" in response.json()[\\\"detail\\\"].lower()\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.create_backend\\\")\\n    async def test_get_chunks_pagination_and_search(\\n        self, mock_create_backend, mock_root, client: AsyncClient, logged_in_headers, tmp_path, seed_kb\\n    ):\\n        \\\"\\\"\\\"Chunks endpoint streams through ``backend.iter_documents`` now.\\n\\n        Old Chroma ``_collection.get`` assertions replaced with a mock\\n        backend that yields a fixed set of ``IngestedDocument``s \u2014 this\\n        keeps the test backend-agnostic and exercises the new filter +\\n        paginate-in-Python path that works across Chroma / Mongo /\\n        Astra / Postgres.\\n        \\\"\\\"\\\"\\n        from lfx.base.knowledge_bases.backends.base import IngestedDocument\\n\\n        mock_root.return_value = tmp_path\\n        kb_dir = tmp_path / \\\"activeuser\\\" / \\\"KB1\\\"\\n        kb_dir.mkdir(parents=True, exist_ok=True)\\n        (kb_dir / \\\"chroma.sqlite3\\\").write_text(\\\"dummy\\\")\\n        await seed_kb(kb_dir.name)\\n\\n        # 25 documents: ids \\\"0\\\" through \\\"24\\\". Two of them contain the\\n        # substring \\\"needle\\\"; the rest read as \\\"doc N\\\".\\n        documents = [\\n            IngestedDocument(\\n                content=\\\"needle match\\\" if idx in {3, 7} else f\\\"doc {idx}\\\",\\n                metadata={\\\"_id\\\": str(idx)},\\n            )\\n            for idx in range(25)\\n        ]\\n\\n        async def _iter_documents(*, batch_size: int = 1000, include_embeddings: bool = False):  # noqa: ARG001\\n            yield documents\\n\\n        backend = MagicMock()\\n        backend.iter_documents = _iter_documents\\n        backend.teardown = AsyncMock()\\n        mock_create_backend.return_value = backend\\n\\n        # Search filters client-side and finds both \\\"needle\\\" rows.\\n        response = await client.get(\\\"api/v1/knowledge_bases/KB1/chunks?search=needle\\\", headers=logged_in_headers)\\n        assert response.status_code == 200\\n        data = response.json()\\n        assert [chunk[\\\"content\\\"] for chunk in data[\\\"chunks\\\"]] == [\\\"needle match\\\", \\\"needle match\\\"]\\n        assert data[\\\"total\\\"] == 2\\n\\n        # Pagination: page 2 of 10 returns ids \\\"10\\\" through \\\"19\\\".\\n        response = await client.get(\\\"api/v1/knowledge_bases/KB1/chunks?page=2&limit=10\\\", headers=logged_in_headers)\\n        assert response.status_code == 200\\n        data = response.json()\\n        assert data[\\\"page\\\"] == 2\\n        assert data[\\\"total\\\"] == 25\\n        assert [chunk[\\\"id\\\"] for chunk in data[\\\"chunks\\\"]] == [str(i) for i in range(10, 20)]\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_get_chunks_non_existent_kb_returns_404(\\n        self,\\n        mock_root,\\n        client: AsyncClient,\\n        logged_in_headers,\\n        tmp_path,\\n    ):\\n        mock_root.return_value = tmp_path\\n\\n        response = await client.get(\\\"api/v1/knowledge_bases/MissingKB/chunks\\\", headers=logged_in_headers)\\n\\n        assert response.status_code == 404\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.create_backend\\\")\\n    async def test_get_chunks_metadata_filter(\\n        self, mock_create_backend, mock_root, client: AsyncClient, logged_in_headers, tmp_path, seed_kb\\n    ):\\n        \\\"\\\"\\\"``meta_<key>`` query params filter chunks by user-supplied tags.\\n\\n        Each chunk's user metadata is stored as a JSON string under\\n        ``source_metadata``. The endpoint decodes that JSON, then AND-matches\\n        every ``meta_<key>`` value passed by the client. Repeating the same\\n        key OR-s its values.\\n        \\\"\\\"\\\"\\n        import json as _json\\n\\n        from lfx.base.knowledge_bases.backends.base import IngestedDocument\\n\\n        mock_root.return_value = tmp_path\\n        kb_dir = tmp_path / \\\"activeuser\\\" / \\\"KB1\\\"\\n        kb_dir.mkdir(parents=True, exist_ok=True)\\n        (kb_dir / \\\"chroma.sqlite3\\\").write_text(\\\"dummy\\\")\\n        await seed_kb(kb_dir.name)\\n\\n        documents = [\\n            IngestedDocument(\\n                content=\\\"invoice doc\\\",\\n                metadata={\\\"_id\\\": \\\"1\\\", \\\"source_metadata\\\": _json.dumps({\\\"tag\\\": \\\"invoice\\\", \\\"year\\\": 2026})},\\n            ),\\n            IngestedDocument(\\n                content=\\\"report doc\\\",\\n                metadata={\\\"_id\\\": \\\"2\\\", \\\"source_metadata\\\": _json.dumps({\\\"tag\\\": \\\"report\\\"})},\\n            ),\\n            IngestedDocument(\\n                content=\\\"invoice doc 2\\\",\\n                metadata={\\\"_id\\\": \\\"3\\\", \\\"source_metadata\\\": _json.dumps({\\\"tag\\\": [\\\"invoice\\\", \\\"audit\\\"]})},\\n            ),\\n            IngestedDocument(\\n                content=\\\"legacy chunk\\\",\\n                metadata={\\\"_id\\\": \\\"4\\\"},  # pre-metadata era \u2014 no source_metadata at all\\n            ),\\n        ]\\n\\n        async def _iter_documents(*, batch_size: int = 1000, include_embeddings: bool = False):  # noqa: ARG001\\n            yield documents\\n\\n        backend = MagicMock()\\n        backend.iter_documents = _iter_documents\\n        backend.teardown = AsyncMock()\\n        mock_create_backend.return_value = backend\\n\\n        # Single-key string match returns both invoice chunks (one literal, one array).\\n        response = await client.get(\\n            \\\"api/v1/knowledge_bases/KB1/chunks\\\",\\n            params={\\\"meta_tag\\\": \\\"invoice\\\"},\\n            headers=logged_in_headers,\\n        )\\n        assert response.status_code == 200, response.json()\\n        data = response.json()\\n        assert sorted(chunk[\\\"id\\\"] for chunk in data[\\\"chunks\\\"]) == [\\\"1\\\", \\\"3\\\"]\\n\\n        # AND filter: tag=invoice + year=2026 narrows to id 1.\\n        response = await client.get(\\n            \\\"api/v1/knowledge_bases/KB1/chunks\\\",\\n            params=[(\\\"meta_tag\\\", \\\"invoice\\\"), (\\\"meta_year\\\", \\\"2026\\\")],\\n            headers=logged_in_headers,\\n        )\\n        assert response.status_code == 200, response.json()\\n        data = response.json()\\n        assert [chunk[\\\"id\\\"] for chunk in data[\\\"chunks\\\"]] == [\\\"1\\\"]\\n\\n        # OR within a key: tag in {report, audit} returns the report doc and\\n        # the audit-tagged invoice doc.\\n        response = await client.get(\\n            \\\"api/v1/knowledge_bases/KB1/chunks\\\",\\n            params=[(\\\"meta_tag\\\", \\\"report\\\"), (\\\"meta_tag\\\", \\\"audit\\\")],\\n            headers=logged_in_headers,\\n        )\\n        assert response.status_code == 200, response.json()\\n        data = response.json()\\n        assert sorted(chunk[\\\"id\\\"] for chunk in data[\\\"chunks\\\"]) == [\\\"2\\\", \\\"3\\\"]\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.create_backend\\\")\\n    async def test_get_metadata_keys_returns_distinct_user_keys(\\n        self, mock_create_backend, mock_root, client: AsyncClient, logged_in_headers, tmp_path, seed_kb\\n    ):\\n        \\\"\\\"\\\"``/metadata/keys`` returns distinct user keys + sample values, hides reserved.\\\"\\\"\\\"\\n        import json as _json\\n\\n        from lfx.base.knowledge_bases.backends.base import IngestedDocument\\n\\n        mock_root.return_value = tmp_path\\n        kb_dir = tmp_path / \\\"activeuser\\\" / \\\"KB1\\\"\\n        kb_dir.mkdir(parents=True, exist_ok=True)\\n        (kb_dir / \\\"chroma.sqlite3\\\").write_text(\\\"dummy\\\")\\n        await seed_kb(kb_dir.name)\\n\\n        documents = [\\n            IngestedDocument(\\n                content=\\\"doc\\\",\\n                metadata={\\n                    \\\"_id\\\": \\\"1\\\",\\n                    \\\"source_metadata\\\": _json.dumps(\\n                        {\\n                            # Reserved keys must be excluded from the response.\\n                            \\\"file_name\\\": \\\"report.pdf\\\",\\n                            \\\"source\\\": \\\"file_upload\\\",\\n                            \\\"chunk_index\\\": 0,\\n                            # User keys.\\n                            \\\"year\\\": \\\"2020\\\",\\n                            \\\"dept\\\": \\\"engineering\\\",\\n                            \\\"tags\\\": [\\\"urgent\\\", \\\"review\\\"],\\n                        }\\n                    ),\\n                },\\n            ),\\n            IngestedDocument(\\n                content=\\\"doc 2\\\",\\n                metadata={\\n                    \\\"_id\\\": \\\"2\\\",\\n                    \\\"source_metadata\\\": _json.dumps({\\\"file_name\\\": \\\"doc2.pdf\\\", \\\"year\\\": \\\"2021\\\", \\\"tags\\\": \\\"audit\\\"}),\\n                },\\n            ),\\n            IngestedDocument(\\n                content=\\\"legacy\\\",\\n                metadata={\\\"_id\\\": \\\"3\\\"},  # pre-metadata era \u2014 should be ignored\\n            ),\\n        ]\\n\\n        async def _iter_documents(*, batch_size: int = 1000, include_embeddings: bool = False):  # noqa: ARG001\\n            yield documents\\n\\n        backend = MagicMock()\\n        backend.iter_documents = _iter_documents\\n        backend.teardown = AsyncMock()\\n        mock_create_backend.return_value = backend\\n\\n        response = await client.get(\\n            \\\"api/v1/knowledge_bases/KB1/metadata/keys\\\",\\n            headers=logged_in_headers,\\n        )\\n        assert response.status_code == 200, response.json()\\n        data = response.json()\\n        # Reserved keys hidden; user keys surface with insertion-ordered values.\\n        assert set(data[\\\"keys\\\"].keys()) == {\\\"year\\\", \\\"dept\\\", \\\"tags\\\"}\\n        assert data[\\\"keys\\\"][\\\"year\\\"] == [\\\"2020\\\", \\\"2021\\\"]\\n        assert data[\\\"keys\\\"][\\\"dept\\\"] == [\\\"engineering\\\"]\\n        # Array-valued metadata expands one distinct value per array entry,\\n        # union-ed with the second doc's \\\"audit\\\" string.\\n        assert sorted(data[\\\"keys\\\"][\\\"tags\\\"]) == [\\\"audit\\\", \\\"review\\\", \\\"urgent\\\"]\\n        assert data[\\\"truncated\\\"] is False\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.create_backend\\\")\\n    async def test_get_metadata_keys_caps_distinct_values_per_key(\\n        self, mock_create_backend, mock_root, client: AsyncClient, logged_in_headers, tmp_path, seed_kb\\n    ):\\n        \\\"\\\"\\\"Distinct values per key are capped \u2014 response sets ``truncated=true``.\\\"\\\"\\\"\\n        import json as _json\\n\\n        from langflow.api.v1.knowledge_bases import KB_METADATA_KEYS_VALUES_CAP\\n        from lfx.base.knowledge_bases.backends.base import IngestedDocument\\n\\n        mock_root.return_value = tmp_path\\n        kb_dir = tmp_path / \\\"activeuser\\\" / \\\"KB1\\\"\\n        kb_dir.mkdir(parents=True, exist_ok=True)\\n        (kb_dir / \\\"chroma.sqlite3\\\").write_text(\\\"dummy\\\")\\n        await seed_kb(kb_dir.name)\\n\\n        documents = [\\n            IngestedDocument(\\n                content=f\\\"doc {idx}\\\",\\n                metadata={\\\"_id\\\": str(idx), \\\"source_metadata\\\": _json.dumps({\\\"variant\\\": str(idx)})},\\n            )\\n            for idx in range(KB_METADATA_KEYS_VALUES_CAP + 5)\\n        ]\\n\\n        async def _iter_documents(*, batch_size: int = 1000, include_embeddings: bool = False):  # noqa: ARG001\\n            yield documents\\n\\n        backend = MagicMock()\\n        backend.iter_documents = _iter_documents\\n        backend.teardown = AsyncMock()\\n        mock_create_backend.return_value = backend\\n\\n        response = await client.get(\\n            \\\"api/v1/knowledge_bases/KB1/metadata/keys\\\",\\n            headers=logged_in_headers,\\n        )\\n        assert response.status_code == 200, response.json()\\n        data = response.json()\\n        assert len(data[\\\"keys\\\"][\\\"variant\\\"]) == KB_METADATA_KEYS_VALUES_CAP\\n        assert data[\\\"truncated\\\"] is True\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_get_metadata_keys_empty_kb_returns_empty_response(\\n        self, mock_root, client: AsyncClient, logged_in_headers, tmp_path, seed_kb\\n    ):\\n        \\\"\\\"\\\"Empty local-Chroma KB short-circuits before booting the backend client.\\\"\\\"\\\"\\n        mock_root.return_value = tmp_path\\n        kb_dir = tmp_path / \\\"activeuser\\\" / \\\"KB1\\\"\\n        kb_dir.mkdir(parents=True, exist_ok=True)\\n        # No chroma.sqlite3 / chroma / index files \u2192 short-circuit path.\\n        await seed_kb(\\\"KB1\\\")\\n\\n        response = await client.get(\\n            \\\"api/v1/knowledge_bases/KB1/metadata/keys\\\",\\n            headers=logged_in_headers,\\n        )\\n        assert response.status_code == 200, response.json()\\n        assert response.json() == {\\\"keys\\\": {}, \\\"truncated\\\": False}\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.create_backend\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_metadata_keys_reach_chroma_cloud_without_a_local_directory(\\n        self, mock_root, mock_create_backend, client: AsyncClient, logged_in_headers, tmp_path, seed_kb\\n    ):\\n        \\\"\\\"\\\"A Chroma **Cloud** KB must not be short-circuited by a missing local dir.\\n\\n        Both Chroma modes are stored as ``backend_type=\\\"chroma\\\"`` and the\\n        discriminator is ``backend_config[\\\"mode\\\"]``. A bare ``backend_type ==\\n        CHROMA`` check therefore read a cloud KB as local and returned an empty\\n        key set off a directory that should never exist for it.\\n        \\\"\\\"\\\"\\n        from lfx.base.knowledge_bases.backends.base import IngestedDocument\\n\\n        mock_root.return_value = tmp_path\\n        await seed_kb(\\\"Cloud_KB\\\", backend_type=\\\"chroma\\\", backend_config={\\\"mode\\\": \\\"cloud\\\"})\\n\\n        async def _iter_documents(*, batch_size: int = 1000, include_embeddings: bool = False):  # noqa: ARG001\\n            yield [IngestedDocument(content=\\\"c\\\", metadata={\\\"source_metadata\\\": json.dumps({\\\"tag\\\": \\\"invoice\\\"})})]\\n\\n        backend = MagicMock()\\n        backend.iter_documents = _iter_documents\\n        backend.teardown = AsyncMock()\\n        mock_create_backend.return_value = backend\\n\\n        response = await client.get(\\n            \\\"api/v1/knowledge_bases/Cloud_KB/metadata/keys\\\",\\n            headers=logged_in_headers,\\n        )\\n        assert response.status_code == 200, response.json()\\n        assert response.json()[\\\"keys\\\"] == {\\\"tag\\\": [\\\"invoice\\\"]}\\n        # Cloud KBs resolve no local path at all.\\n        assert mock_create_backend.call_args.kwargs[\\\"kb_path\\\"] is None\\n\\n\\nclass TestPerformIngestionTask:\\n    \\\"\\\"\\\"Tests for the internal KBIngestionHelper.perform_ingestion background task.\\\"\\\"\\\"\\n\\n    @patch(\\\"langflow.api.utils.ingestion_run_service.finalize_run\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.utils.ingestion_run_service.mark_running\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.utils.ingestion_run_service.create_run\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.utils.kb_helpers.create_backend\\\")\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBIngestionHelper.build_embeddings\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.get_directory_size\\\")\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBAnalysisHelper.update_text_metrics\\\")\\n    async def test_perform_ingestion_success(\\n        self,\\n        mock_update,\\n        mock_size,\\n        mock_build,\\n        mock_backend_cls,\\n        mock_create_run,\\n        mock_mark_running,\\n        mock_finalize_run,\\n        mock_kb_path,\\n        sample_text_file,\\n    ):\\n        mock_update.return_value = None\\n        mock_embeddings = MagicMock()\\n        mock_build.return_value = mock_embeddings\\n\\n        mock_backend = MagicMock()\\n        mock_backend.add_documents = AsyncMock()\\n        mock_backend.teardown = AsyncMock()\\n        mock_backend.raw_langchain_store = MagicMock(return_value=MagicMock())\\n        mock_backend_cls.return_value = mock_backend\\n\\n        run_id = uuid.uuid4()\\n        mock_create_run.return_value = run_id\\n        mock_size.return_value = 100\\n\\n        file_name, file_content = sample_text_file\\n        files_data = [(file_name, file_content.encode())]\\n\\n        current_user = MagicMock()\\n        current_user.id = uuid.uuid4()\\n\\n        result = await KBIngestionHelper.perform_ingestion(\\n            kb_name=\\\"test_kb\\\",\\n            kb_path=mock_kb_path,\\n            files_data=files_data,\\n            chunk_size=100,\\n            chunk_overlap=20,\\n            separator=\\\"\\\\n\\\",\\n            source_name=\\\"src\\\",\\n            current_user=current_user,\\n            model_selection={\\\"name\\\": \\\"model\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n            task_job_id=uuid.uuid4(),\\n            job_service=AsyncMock(),\\n        )\\n\\n        assert result[\\\"ingestion_run_id\\\"] == str(run_id)\\n        mock_backend.add_documents.assert_called()\\n        mock_backend.teardown.assert_awaited()\\n        mock_create_run.assert_awaited_once()\\n        mock_mark_running.assert_awaited_once_with(run_id)\\n        mock_finalize_run.assert_awaited_once()\\n\\n        # Finalize should mark the run SUCCEEDED when every item lands.\\n        finalize_kwargs = mock_finalize_run.await_args.kwargs\\n        from lfx.base.knowledge_bases.ingestion_sources.base import IngestionRunStatus\\n\\n        assert finalize_kwargs[\\\"status\\\"] is IngestionRunStatus.SUCCEEDED\\n        assert finalize_kwargs[\\\"summary\\\"].succeeded == 1\\n        assert finalize_kwargs[\\\"summary\\\"].failed == 0\\n\\n        # Every chunk should carry the default ingestion-source-type tag so\\n        # Phase 2 visibility tooling can key off origin.\\n        written_docs = [doc for call in mock_backend.add_documents.call_args_list for doc in call.args[0]]\\n        assert written_docs, \\\"expected at least one chunk document to be written\\\"\\n        assert all(doc.metadata.get(\\\"source_type\\\") == \\\"file_upload\\\" for doc in written_docs)\\n\\n    @patch(\\\"langflow.api.utils.ingestion_run_service.finalize_run\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.utils.ingestion_run_service.mark_running\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.utils.ingestion_run_service.create_run\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.utils.kb_helpers.create_backend\\\")\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBIngestionHelper.build_embeddings\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.get_directory_size\\\")\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBAnalysisHelper.update_text_metrics_via_backend\\\", new_callable=AsyncMock)\\n    async def test_perform_ingestion_skipped_only_is_partial(\\n        self,\\n        mock_update_metrics,  # noqa: ARG002\\n        mock_size,\\n        mock_build,\\n        mock_backend_cls,\\n        mock_create_run,\\n        mock_mark_running,  # noqa: ARG002\\n        mock_finalize_run,\\n        mock_kb_path,\\n        whitespace_text_file,\\n    ):\\n        \\\"\\\"\\\"Files with no extractable text are SKIPPED.\\n\\n        Regression test for the QA-reported bug where a run that\\n        produced 0 successful items but 1 skipped item was finalized\\n        as SUCCEEDED. The expected outcome is PARTIAL so the UI can\\n        signal that nothing was actually ingested.\\n        \\\"\\\"\\\"\\n        mock_embeddings = MagicMock()\\n        mock_build.return_value = mock_embeddings\\n\\n        mock_backend = MagicMock()\\n        mock_backend.add_documents = AsyncMock()\\n        mock_backend.teardown = AsyncMock()\\n        mock_backend.raw_langchain_store = MagicMock(return_value=MagicMock())\\n        mock_backend_cls.return_value = mock_backend\\n\\n        run_id = uuid.uuid4()\\n        mock_create_run.return_value = run_id\\n        mock_size.return_value = 0\\n\\n        file_name, file_content = whitespace_text_file\\n        files_data = [(file_name, file_content.encode())]\\n\\n        current_user = MagicMock()\\n        current_user.id = uuid.uuid4()\\n\\n        await KBIngestionHelper.perform_ingestion(\\n            kb_name=\\\"test_kb\\\",\\n            kb_path=mock_kb_path,\\n            files_data=files_data,\\n            chunk_size=100,\\n            chunk_overlap=20,\\n            separator=\\\"\\\\n\\\",\\n            source_name=\\\"src\\\",\\n            current_user=current_user,\\n            model_selection={\\\"name\\\": \\\"model\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n            task_job_id=uuid.uuid4(),\\n            job_service=AsyncMock(),\\n        )\\n\\n        from lfx.base.knowledge_bases.ingestion_sources.base import IngestionRunStatus\\n\\n        mock_finalize_run.assert_awaited_once()\\n        finalize_kwargs = mock_finalize_run.await_args.kwargs\\n        assert finalize_kwargs[\\\"status\\\"] is IngestionRunStatus.PARTIAL\\n        assert finalize_kwargs[\\\"summary\\\"].succeeded == 0\\n        assert finalize_kwargs[\\\"summary\\\"].failed == 0\\n        assert finalize_kwargs[\\\"summary\\\"].skipped == 1\\n        # No docs should have been written when every item was skipped.\\n        mock_backend.add_documents.assert_not_called()\\n\\n    @patch(\\\"langflow.api.utils.ingestion_run_service.finalize_run\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.utils.ingestion_run_service.mark_running\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.utils.ingestion_run_service.create_run\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.utils.knowledge_base_service.get_by_user_and_name\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.utils.kb_helpers.create_backend\\\")\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBIngestionHelper.build_embeddings\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.get_directory_size\\\")\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBAnalysisHelper.update_text_metrics_via_backend\\\", new_callable=AsyncMock)\\n    async def test_perform_ingestion_routes_through_configured_backend(\\n        self,\\n        mock_update_metrics,\\n        mock_size,\\n        mock_build,\\n        mock_create_backend,\\n        mock_get_kb,\\n        mock_create_run,\\n        mock_mark_running,  # noqa: ARG002\\n        mock_finalize_run,  # noqa: ARG002\\n        mock_kb_path,\\n        sample_text_file,\\n    ):\\n        mock_embeddings = MagicMock()\\n        mock_build.return_value = mock_embeddings\\n\\n        kb_record = MagicMock()\\n        kb_record.id = uuid.uuid4()\\n        kb_record.backend_type = \\\"opensearch\\\"\\n        kb_record.backend_config = {\\\"index_name\\\": \\\"kb_idx\\\", \\\"url_variable\\\": \\\"OPENSEARCH_URL\\\"}\\n        mock_get_kb.return_value = kb_record\\n\\n        mock_backend = MagicMock()\\n        mock_backend.add_documents = AsyncMock()\\n        mock_backend.teardown = AsyncMock()\\n        mock_create_backend.return_value = mock_backend\\n\\n        run_id = uuid.uuid4()\\n        mock_create_run.return_value = run_id\\n        mock_size.return_value = 0\\n\\n        file_name, file_content = sample_text_file\\n        current_user = MagicMock()\\n        current_user.id = uuid.uuid4()\\n\\n        result = await KBIngestionHelper.perform_ingestion(\\n            kb_name=\\\"test_kb\\\",\\n            kb_path=mock_kb_path,\\n            files_data=[(file_name, file_content.encode())],\\n            chunk_size=100,\\n            chunk_overlap=20,\\n            separator=\\\"\\\\n\\\",\\n            source_name=\\\"src\\\",\\n            current_user=current_user,\\n            model_selection={\\\"name\\\": \\\"model\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n            task_job_id=uuid.uuid4(),\\n            job_service=AsyncMock(),\\n        )\\n\\n        assert result[\\\"ingestion_run_id\\\"] == str(run_id)\\n        mock_create_run.assert_awaited_once()\\n        assert mock_create_run.await_args.kwargs[\\\"kb_id\\\"] == kb_record.id\\n        mock_create_backend.assert_called_once()\\n        assert mock_create_backend.call_args.args == (\\\"opensearch\\\",)\\n        backend_kwargs = mock_create_backend.call_args.kwargs\\n        assert backend_kwargs[\\\"backend_config\\\"] == kb_record.backend_config\\n        assert backend_kwargs[\\\"embedding_function\\\"] is mock_embeddings\\n        assert backend_kwargs[\\\"user_id\\\"] == current_user.id\\n        # Metrics are recounted straight from the backend into a scratch dict,\\n        # then written to the row \u2014 there is no sidecar to read them back from.\\n        mock_update_metrics.assert_awaited_once()\\n        assert mock_update_metrics.await_args.args[1] is mock_backend\\n\\n    @patch(\\\"langflow.api.utils.ingestion_run_service.finalize_run\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.utils.ingestion_run_service.mark_running\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.utils.ingestion_run_service.create_run\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.utils.kb_helpers.create_backend\\\")\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBIngestionHelper.build_embeddings\\\", new_callable=AsyncMock)\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBIngestionHelper.cleanup_chroma_chunks_by_job\\\", new_callable=AsyncMock)\\n    async def test_perform_ingestion_rollback(\\n        self,\\n        mock_cleanup,\\n        mock_build,\\n        mock_backend_cls,\\n        mock_create_run,\\n        mock_mark_running,  # noqa: ARG002 \u2014 patched to keep ingestion_run DB calls out of this test\\n        mock_finalize_run,\\n        mock_kb_path,\\n    ):\\n        \\\"\\\"\\\"Write-loop errors that exhaust retries must propagate and trigger rollback.\\\"\\\"\\\"\\n        mock_backend = MagicMock()\\n        mock_backend.add_documents = AsyncMock(side_effect=Exception(\\\"Chroma error\\\"))\\n        mock_backend.teardown = AsyncMock()\\n        mock_backend.raw_langchain_store = MagicMock(return_value=MagicMock())\\n        mock_backend_cls.return_value = mock_backend\\n        mock_create_run.return_value = uuid.uuid4()\\n\\n        files_data = [(\\\"test.txt\\\", b\\\"content\\\")]\\n        job_id = uuid.uuid4()\\n\\n        current_user = MagicMock()\\n        current_user.id = uuid.uuid4()\\n\\n        with pytest.raises(Exception, match=\\\"Chroma error\\\"):\\n            await KBIngestionHelper.perform_ingestion(\\n                kb_name=\\\"test_kb\\\",\\n                kb_path=mock_kb_path,\\n                files_data=files_data,\\n                chunk_size=100,\\n                chunk_overlap=20,\\n                separator=\\\"\\\\n\\\",\\n                source_name=\\\"src\\\",\\n                current_user=current_user,\\n                model_selection={\\\"name\\\": \\\"model\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n                task_job_id=job_id,\\n                job_service=AsyncMock(),\\n            )\\n\\n        mock_build.assert_called_once()\\n        # Rollback now threads optional backend info through so\\n        # non-Chroma backends can clean up; assert by positional tuple.\\n        mock_cleanup.assert_called_once()\\n        call_args = mock_cleanup.call_args\\n        assert call_args.args == (job_id, mock_kb_path, \\\"test_kb\\\")\\n        mock_backend.teardown.assert_awaited()\\n        # The run row must still be finalized even on error so the\\n        # visibility UI doesn't show stuck RUNNING rows.\\n        mock_finalize_run.assert_awaited_once()\\n        finalize_kwargs = mock_finalize_run.await_args.kwargs\\n        from lfx.base.knowledge_bases.ingestion_sources.base import IngestionRunStatus\\n\\n        assert finalize_kwargs[\\\"status\\\"] is IngestionRunStatus.FAILED\\n        assert finalize_kwargs[\\\"error_message\\\"] == \\\"Chroma error\\\"\\n\\n\\nclass TestCancelIngestion:\\n    \\\"\\\"\\\"Tests for the cancel_ingestion endpoint.\\\"\\\"\\\"\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBIngestionHelper.cleanup_chroma_chunks_by_job\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_cancel_ingestion_success(\\n        self, mock_root, mock_cleanup, client: AsyncClient, logged_in_headers, tmp_path, seed_kb\\n    ):\\n        from unittest.mock import patch as mock_patch\\n\\n        from langflow.services.deps import get_service\\n        from langflow.services.schema import ServiceType\\n\\n        mock_root.return_value = tmp_path\\n        kb_path = tmp_path / \\\"activeuser\\\" / \\\"Test_KB\\\"\\n        kb_path.mkdir(parents=True, exist_ok=True)\\n\\n        job_id = uuid.uuid4()\\n        # ``asset_id`` is the KB row's id \u2014 the indexed column behind job.asset_id.\\n        asset_id = (await seed_kb(\\\"Test_KB\\\")).id\\n\\n        mock_job = MagicMock()\\n        mock_job.job_id = job_id\\n        mock_job.status = MagicMock()\\n        mock_job.status.value = \\\"running\\\"\\n\\n        mock_job_service_inst = MagicMock()\\n        mock_job_service_inst.get_latest_jobs_by_asset_ids = AsyncMock(return_value={asset_id: mock_job})\\n        mock_job_service_inst.update_job_status = AsyncMock()\\n\\n        mock_task_service_inst = MagicMock()\\n        mock_task_service_inst.revoke_task = AsyncMock(return_value=True)\\n\\n        mock_cleanup.return_value = AsyncMock()\\n\\n        original_get_service = get_service\\n\\n        def get_service_side_effect(service_type, default=None):\\n            if service_type == ServiceType.JOB_SERVICE:\\n                return mock_job_service_inst\\n            if service_type == ServiceType.TASK_SERVICE:\\n                return mock_task_service_inst\\n            return original_get_service(service_type, default)\\n\\n        with mock_patch(\\\"langflow.services.deps.get_service\\\", side_effect=get_service_side_effect):\\n            response = await client.post(\\n                \\\"api/v1/knowledge_bases/Test_KB/cancel\\\",\\n                headers=logged_in_headers,\\n            )\\n\\n            assert response.status_code == 200\\n            data = response.json()\\n            assert \\\"cancelled successfully\\\" in data[\\\"message\\\"]\\n            mock_task_service_inst.revoke_task.assert_called_once_with(job_id)\\n            mock_job_service_inst.update_job_status.assert_called_once()\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.get_job_service\\\")\\n    async def test_cancel_ingestion_not_found(\\n        self, mock_job_service, mock_root, client: AsyncClient, logged_in_headers, tmp_path, seed_kb\\n    ):\\n        mock_root.return_value = tmp_path\\n        kb_path = tmp_path / \\\"activeuser\\\" / \\\"Test_KB\\\"\\n        kb_path.mkdir(parents=True, exist_ok=True)\\n        await seed_kb(\\\"Test_KB\\\")\\n\\n        mock_job_service_inst = MagicMock()\\n        mock_job_service.return_value = mock_job_service_inst\\n        mock_job_service_inst.get_latest_jobs_by_asset_ids = AsyncMock(return_value={})\\n\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases/Test_KB/cancel\\\",\\n            headers=logged_in_headers,\\n        )\\n\\n        assert response.status_code == 404\\n        assert \\\"no ingestion job found\\\" in response.json()[\\\"detail\\\"].lower()\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_cancel_ingestion_kb_not_found(self, mock_root, client: AsyncClient, logged_in_headers, tmp_path):\\n        mock_root.return_value = tmp_path\\n\\n        response = await client.post(\\n            \\\"api/v1/knowledge_bases/NonExistent_KB/cancel\\\",\\n            headers=logged_in_headers,\\n        )\\n\\n        assert response.status_code == 404\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_langflow_components_compat_shim.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9171a2069248da3d44121328e0299f083bb24f9e05b7efaec4a5c412db223049\",\"content\":\"\\\"\\\"\\\"Tests for the dynamic ``langflow.components.*`` -> ``lfx.components.*`` bridge.\\n\\nSaved flows in the wild import their components via the legacy\\n``langflow.components.<sub>.<leaf>`` paths (the integration test\\n``test_dynamic_import_integration.py`` documents this contract).  The\\nlfx extraction moved every component module into ``lfx.components.*``;\\n``langflow/__init__.py`` installs a meta path finder that bridges the\\ntwo namespaces dynamically so saved flows keep loading without\\nmodification.\\n\\nThis suite locks the contract:\\n\\n    1. Generic prefix bridge: ``langflow.components.<rest>`` resolves to\\n       ``lfx.components.<rest>`` for arbitrary subpackages and submodules,\\n       including new bundles extracted in the future.\\n    2. Renamed-package override: ``langflow.components.knowledge_bases``\\n       (and any submodule under it) resolves to\\n       ``lfx.components.files_and_knowledge`` because the package was\\n       renamed during the move while the langflow-side path stays for\\n       saved-flow compat.\\n    3. Class identity is preserved: a class loaded via the langflow path\\n       is the same object as the one loaded via the lfx path, so\\n       ``isinstance`` checks across the bridge keep working.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport importlib\\nimport sys\\n\\nimport langflow  # noqa: F401  -- triggers the meta finder install\\n\\n\\ndef test_dotted_submodule_import_resolves() -> None:\\n    \\\"\\\"\\\"``from langflow.components.processing.converter import X`` works.\\n\\n    Regression: the deletion of the physical ``langflow/components/processing/converter.py``\\n    shim broke this import path before the dynamic bridge landed.\\n    \\\"\\\"\\\"\\n    from langflow.components.processing.converter import convert_to_dataframe\\n\\n    # The bridge is a name alias, not a copy; ``__module__`` reflects the\\n    # underlying lfx location so debuggers / stack traces point at the\\n    # canonical source file.\\n    assert convert_to_dataframe.__module__ == \\\"lfx.components.processing.converter\\\"\\n\\n\\ndef test_helpers_subpackage_imports() -> None:\\n    \\\"\\\"\\\"``from langflow.components.helpers import X`` works for any helper class.\\\"\\\"\\\"\\n    from langflow.components.helpers import CalculatorComponent\\n\\n    assert CalculatorComponent.__module__.startswith(\\\"lfx.components.\\\")\\n\\n\\ndef test_knowledge_bases_override_resolves_to_files_and_knowledge() -> None:\\n    \\\"\\\"\\\"``langflow.components.knowledge_bases[.<rest>]`` -> ``lfx.components.files_and_knowledge[.<rest>]``.\\n\\n    The lfx package was renamed during the move; the langflow-side path\\n    stays as ``knowledge_bases`` so saved flows that imported via that\\n    name continue to resolve.\\n    \\\"\\\"\\\"\\n    from langflow.components.knowledge_bases.retrieval import KnowledgeBaseComponent\\n\\n    assert KnowledgeBaseComponent.__module__ == \\\"lfx.components.files_and_knowledge.retrieval\\\"\\n\\n\\ndef test_class_identity_preserved_across_bridge() -> None:\\n    \\\"\\\"\\\"Same class is returned via ``langflow.components.X`` and ``lfx.components.X``.\\n\\n    Critical for ``isinstance`` checks against types resolved through\\n    either path -- e.g. a saved flow imports the legacy langflow path\\n    while runtime code imports the lfx path; both must compare equal.\\n    \\\"\\\"\\\"\\n    import langflow.components.processing.converter as langflow_module\\n    import lfx.components.processing.converter as lfx_module\\n\\n    assert langflow_module is lfx_module\\n    assert langflow_module.convert_to_dataframe is lfx_module.convert_to_dataframe\\n\\n\\ndef test_top_level_components_is_aliased_to_lfx_components() -> None:\\n    \\\"\\\"\\\"``import langflow.components`` resolves to the lfx package.\\n\\n    Catches the case where the meta finder isn't installed yet when\\n    ``langflow.components`` is first imported -- happens on cold imports\\n    in test runs that don't go through ``langflow.__init__`` first.\\n    \\\"\\\"\\\"\\n    import langflow.components\\n    import lfx.components\\n\\n    assert langflow.components is lfx.components\\n\\n\\ndef test_arbitrary_extracted_bundle_resolves_via_dynamic_bridge() -> None:\\n    \\\"\\\"\\\"A bundle that exists in lfx but had no physical ``langflow/components`` shim resolves.\\n\\n    Regression-future: the previous shim layout required a parallel\\n    physical file per subpackage; forgetting to add one silently broke\\n    pre-existing flows.  The dynamic bridge means a new lfx component\\n    module is reachable via the legacy langflow path immediately.\\n    \\\"\\\"\\\"\\n    # Pick any subpackage under lfx.components that didn't have a\\n    # physical shim under langflow/components/ before the deletion.\\n    target = \\\"lfx.components.helpers.calculator_core\\\"\\n    importlib.import_module(target)\\n    bridge = importlib.import_module(\\\"langflow.components.helpers.calculator_core\\\")\\n    assert bridge is sys.modules[target]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_langflow_logging_compatibility.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cebb7664d56fa1d27f89e2ba2964e1e699965ec0905e603c756aba86f460cd5f\",\"content\":\"\\\"\\\"\\\"Test langflow.logging backwards compatibility and integration.\\n\\nThis test ensures that langflow.logging works correctly and that there are no\\nconflicts with the new lfx.logging backwards compatibility module.\\n\\\"\\\"\\\"\\n\\nimport pytest\\n\\n\\ndef test_langflow_logging_imports():\\n    \\\"\\\"\\\"Test that langflow.logging can be imported and works correctly.\\\"\\\"\\\"\\n    try:\\n        from langflow.logging import configure, logger\\n\\n        assert configure is not None\\n        assert logger is not None\\n        assert callable(configure)\\n    except ImportError as e:\\n        pytest.fail(f\\\"langflow.logging should be importable: {e}\\\")\\n\\n\\ndef test_langflow_logging_functionality():\\n    \\\"\\\"\\\"Test that langflow.logging functions work correctly.\\\"\\\"\\\"\\n    from langflow.logging import configure, logger\\n\\n    # Should be able to configure\\n    try:\\n        configure(log_level=\\\"INFO\\\")\\n    except Exception as e:\\n        pytest.fail(f\\\"configure should work: {e}\\\")\\n\\n    # Should be able to log\\n    try:\\n        logger.info(\\\"Test message from langflow.logging\\\")\\n    except Exception as e:\\n        pytest.fail(f\\\"logger should work: {e}\\\")\\n\\n\\ndef test_langflow_logging_has_expected_exports():\\n    \\\"\\\"\\\"Test that langflow.logging has the expected exports.\\\"\\\"\\\"\\n    import langflow.logging\\n\\n    assert hasattr(langflow.logging, \\\"configure\\\")\\n    assert hasattr(langflow.logging, \\\"logger\\\")\\n    assert hasattr(langflow.logging, \\\"disable_logging\\\")\\n    assert hasattr(langflow.logging, \\\"enable_logging\\\")\\n\\n    # Check __all__\\n    assert hasattr(langflow.logging, \\\"__all__\\\")\\n    expected_exports = {\\\"configure\\\", \\\"logger\\\", \\\"disable_logging\\\", \\\"enable_logging\\\"}\\n    assert set(langflow.logging.__all__) == expected_exports\\n\\n\\ndef test_langflow_logging_specific_functions():\\n    \\\"\\\"\\\"Test langflow.logging specific functions (disable_logging, enable_logging).\\\"\\\"\\\"\\n    from langflow.logging import disable_logging, enable_logging\\n\\n    assert callable(disable_logging)\\n    assert callable(enable_logging)\\n\\n    # Note: These functions have implementation issues (trying to call methods\\n    # that don't exist on structlog), but they should at least be importable\\n    # and callable. The actual functionality is a separate issue from the\\n    # backwards compatibility we're testing.\\n\\n\\ndef test_no_conflict_with_lfx_logging():\\n    \\\"\\\"\\\"Test that langflow.logging and lfx.logging don't conflict.\\\"\\\"\\\"\\n    # Import both\\n    from langflow.logging import configure as lf_configure\\n    from langflow.logging import logger as lf_logger\\n    from lfx.logging import configure as lfx_configure\\n    from lfx.logging import logger as lfx_logger\\n\\n    # They should be the same underlying objects since langflow.logging imports from lfx.log.logger\\n    # and lfx.logging re-exports from lfx.log.logger\\n    # Note: Due to import order and module initialization, object identity may vary,\\n    # but functionality should be equivalent\\n    assert callable(lf_configure)\\n    assert callable(lfx_configure)\\n    assert hasattr(lf_logger, \\\"info\\\")\\n    assert hasattr(lfx_logger, \\\"info\\\")\\n\\n    # Test that both work without conflicts\\n    lf_configure(log_level=\\\"INFO\\\")\\n    lfx_configure(log_level=\\\"INFO\\\")\\n    lf_logger.info(\\\"Test from langflow.logging\\\")\\n    lfx_logger.info(\\\"Test from lfx.logging\\\")\\n\\n\\ndef test_langflow_logging_imports_from_lfx():\\n    \\\"\\\"\\\"Test that langflow.logging correctly imports from lfx.\\\"\\\"\\\"\\n    from langflow.logging import configure, logger\\n    from lfx.log.logger import configure as lfx_configure\\n    from lfx.log.logger import logger as lfx_logger\\n\\n    # langflow.logging should import equivalent objects from lfx.log.logger\\n    # Due to module initialization order, object identity may vary\\n    assert callable(configure)\\n    assert callable(lfx_configure)\\n    assert hasattr(logger, \\\"info\\\")\\n    assert hasattr(lfx_logger, \\\"info\\\")\\n\\n    # Test functionality equivalence\\n    configure(log_level=\\\"DEBUG\\\")\\n    logger.debug(\\\"Test from langflow.logging\\\")\\n    lfx_configure(log_level=\\\"DEBUG\\\")\\n    lfx_logger.debug(\\\"Test from lfx.log.logger\\\")\\n\\n\\ndef test_backwards_compatibility_scenario():\\n    \\\"\\\"\\\"Test the complete backwards compatibility scenario.\\\"\\\"\\\"\\n    # This tests the scenario where:\\n    # 1. langflow.logging exists and imports from lfx.log.logger\\n    # 2. lfx.logging now exists (new) and re-exports from lfx.log.logger\\n    # 3. Both should work without conflicts\\n\\n    # Import from all paths\\n    from langflow.logging import configure as lf_configure\\n    from langflow.logging import logger as lf_logger\\n    from lfx.log.logger import configure as orig_configure\\n    from lfx.log.logger import logger as orig_logger\\n    from lfx.logging import configure as lfx_configure\\n    from lfx.logging import logger as lfx_logger\\n\\n    # All should be callable/have expected methods\\n    assert callable(lf_configure)\\n    assert callable(lfx_configure)\\n    assert callable(orig_configure)\\n    assert hasattr(lf_logger, \\\"error\\\")\\n    assert hasattr(lfx_logger, \\\"info\\\")\\n    assert hasattr(orig_logger, \\\"debug\\\")\\n\\n    # All should work without conflicts\\n    lf_configure(log_level=\\\"ERROR\\\")\\n    lf_logger.error(\\\"Message from langflow.logging\\\")\\n\\n    lfx_configure(log_level=\\\"INFO\\\")\\n    lfx_logger.info(\\\"Message from lfx.logging\\\")\\n\\n    orig_configure(log_level=\\\"DEBUG\\\")\\n    orig_logger.debug(\\\"Message from lfx.log.logger\\\")\\n\\n\\ndef test_importing_langflow_logging_in_langflow():\\n    \\\"\\\"\\\"Test that langflow.logging can be imported and used in langflow context without errors.\\n\\n    This is similar to test_importing_langflow_logging_in_lfx but tests the langflow side\\n    using create_class to validate component creation with langflow.logging imports.\\n    \\\"\\\"\\\"\\n    from textwrap import dedent\\n\\n    from lfx.custom.validate import create_class\\n\\n    # Test that langflow.logging can be used in component code created via create_class\\n    code = dedent(\\\"\\\"\\\"\\nfrom langflow.logging import logger, configure\\nfrom langflow.logging.logger import logger\\nfrom langflow.custom import Component\\n\\nclass TestLangflowLoggingComponent(Component):\\n    def some_method(self):\\n        # Test that both logger and configure work in langflow context\\n        configure(log_level=\\\"INFO\\\")\\n        logger.info(\\\"Test message from langflow component\\\")\\n\\n        # Test different log levels\\n        logger.debug(\\\"Debug message\\\")\\n        logger.warning(\\\"Warning message\\\")\\n        logger.error(\\\"Error message\\\")\\n\\n        return \\\"langflow_logging_success\\\"\\n    \\\"\\\"\\\")\\n\\n    result = create_class(code, \\\"TestLangflowLoggingComponent\\\")\\n    assert result.__name__ == \\\"TestLangflowLoggingComponent\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_legacy_flow_agent_scoping_migration.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fd0c13ff12238d25a53c1411392f179e108b10f3737b2a9c2defdb222bb5bfee\",\"content\":\"\\\"\\\"\\\"Tests for the ``b2c72e1e1439`` data migration.\\n\\nThe migration rewrites the embedded ``get_memory_data`` in already-seeded Flow rows so\\nlegacy Agent snapshots read chat history through the user-scoped\\n``aget_agent_chat_history(..., user_id=_safe_graph_user_id(self))`` path instead of the\\nunscoped ``MemoryComponent(**self.get_base_args()).retrieve_messages()`` path (CWE-200).\\n\\nThese tests use an in-memory SQLite database and the migration module's own functions \u2014\\nthey deliberately avoid the app ``client``/``session`` fixtures so nothing rewrites the\\npackaged starter-project/agentic JSON on disk.\\n\\\"\\\"\\\"\\n\\nimport hashlib\\nimport importlib.util\\nimport types\\nfrom pathlib import Path\\n\\nimport langflow\\nimport pytest\\nimport sqlalchemy as sa\\n\\nMIGRATION_ID = \\\"b2c72e1e1439\\\"\\n\\n\\n@pytest.fixture(scope=\\\"module\\\")\\ndef migration():\\n    \\\"\\\"\\\"Load the migration module by path (it is not an importable package).\\\"\\\"\\\"\\n    versions = Path(langflow.__file__).parent / \\\"alembic\\\" / \\\"versions\\\"\\n    matches = list(versions.glob(f\\\"{MIGRATION_ID}_*.py\\\"))\\n    assert len(matches) == 1, f\\\"expected exactly one migration file, found {matches}\\\"\\n    spec = importlib.util.spec_from_file_location(f\\\"mig_{MIGRATION_ID}\\\", matches[0])\\n    module = importlib.util.module_from_spec(spec)\\n    spec.loader.exec_module(module)\\n    return module\\n\\n\\n# A compact but faithful pre-fix Agent snapshot: the real old memory import plus the exact\\n# old ``get_memory_data`` body, defined independently of the migration's own constants.\\ndef _stale_agent_code(*, import_line: str) -> str:\\n    return (\\n        f\\\"{import_line}\\\\n\\\"\\n        \\\"\\\\n\\\"\\n        \\\"class AgentComponent:\\\\n\\\"\\n        \\\"    memory_inputs = [c for c in MemoryComponent().inputs]\\\\n\\\"\\n        \\\"\\\\n\\\"\\n        \\\"    async def get_memory_data(self):\\\\n\\\"\\n        \\\"        # TODO: This is a temporary fix to avoid message duplication. We should develop a function for this.\\\\n\\\"\\n        \\\"        messages = (\\\\n\\\"\\n        \\\"            await MemoryComponent(**self.get_base_args())\\\\n\\\"\\n        \\\"            .set(\\\\n\\\"\\n        \\\"                session_id=self.graph.session_id,\\\\n\\\"\\n        \\\"                context_id=self.context_id,\\\\n\\\"\\n        '                order=\\\"Ascending\\\",\\\\n'\\n        \\\"                n_messages=self.n_messages,\\\\n\\\"\\n        \\\"            )\\\\n\\\"\\n        \\\"            .retrieve_messages()\\\\n\\\"\\n        \\\"        )\\\\n\\\"\\n        \\\"        return [\\\\n\\\"\\n        '            message for message in messages if getattr(message, \\\"id\\\", None) != getattr(self.input_value, \\\"id\\\", None)\\\\n'  # noqa: E501\\n        \\\"        ]\\\\n\\\"\\n    )\\n\\n\\n_MODELS_IMPORT = \\\"from lfx.components.models_and_agents.memory import MemoryComponent\\\"\\n_HELPERS_IMPORT = \\\"from lfx.components.helpers.memory import MemoryComponent\\\"\\n\\n\\ndef _agent_flow_data(code: str, *, code_hash: str = \\\"0\\\" * 12) -> dict:\\n    return {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"id\\\": \\\"Agent-abc\\\",\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"Agent\\\",\\n                    \\\"node\\\": {\\\"template\\\": {\\\"code\\\": {\\\"value\\\": code}}, \\\"metadata\\\": {\\\"code_hash\\\": code_hash}},\\n                },\\n            }\\n        ],\\n        \\\"edges\\\": [],\\n    }\\n\\n\\n@pytest.mark.parametrize(\\\"import_line\\\", [_MODELS_IMPORT, _HELPERS_IMPORT])\\ndef test_rewrite_agent_code_scopes_recognized_imports(migration, import_line):\\n    new_code = migration._rewrite_agent_code(_stale_agent_code(import_line=import_line))\\n    assert new_code is not None\\n    # Vulnerable call is gone; scoped call + helper are present and imported.\\n    assert \\\"MemoryComponent(**self.get_base_args())\\\" not in new_code\\n    assert \\\"aget_agent_chat_history(\\\" in new_code\\n    assert \\\"user_id=_safe_graph_user_id(self)\\\" in new_code\\n    assert f\\\"{import_line}, _safe_graph_user_id, aget_agent_chat_history\\\" in new_code\\n    # MemoryComponent() (no-arg, for memory_inputs) is preserved.\\n    assert \\\"MemoryComponent().inputs\\\" in new_code\\n\\n\\ndef test_rewrite_agent_code_skips_unrecognized_import(migration):\\n    code = _stale_agent_code(import_line=\\\"from lfx.components.somewhere.memory import MemoryComponent\\\")\\n    # Old method present, but import path is unknown: must skip rather than emit a module\\n    # that references undefined helper names.\\n    assert migration._rewrite_agent_code(code) is None\\n\\n\\ndef test_rewrite_agent_code_skips_already_fixed(migration):\\n    assert migration._rewrite_agent_code(\\\"class AgentComponent:\\\\n    pass\\\\n\\\") is None\\n    assert migration._rewrite_agent_code(None) is None\\n\\n\\ndef _make_flow_table():\\n    engine = sa.create_engine(\\\"sqlite://\\\")\\n    meta = sa.MetaData()\\n    flow = sa.Table(\\n        \\\"flow\\\",\\n        meta,\\n        sa.Column(\\\"id\\\", sa.String, primary_key=True),\\n        sa.Column(\\\"data\\\", sa.JSON),\\n    )\\n    meta.create_all(engine)\\n    return engine, flow\\n\\n\\ndef _load(engine, flow, id_):\\n    with engine.begin() as conn:\\n        row = conn.execute(sa.select(flow.c.data).where(flow.c.id == id_)).first()\\n    return row[0]\\n\\n\\ndef _run_upgrade(migration, engine):\\n    with engine.begin() as conn:\\n        migration.op = types.SimpleNamespace(get_bind=lambda: conn)\\n        migration.upgrade()\\n\\n\\ndef test_upgrade_rewrites_seeded_rows_and_is_idempotent(migration):\\n    engine, flow = _make_flow_table()\\n    stale = _agent_flow_data(_stale_agent_code(import_line=_MODELS_IMPORT), code_hash=\\\"deadbeef0000\\\")\\n    helpers_stale = _agent_flow_data(_stale_agent_code(import_line=_HELPERS_IMPORT), code_hash=\\\"deadbeef1111\\\")\\n    unrecognized = _agent_flow_data(\\n        _stale_agent_code(import_line=\\\"from lfx.components.somewhere.memory import MemoryComponent\\\"),\\n        code_hash=\\\"deadbeef2222\\\",\\n    )\\n    non_agent = {\\n        \\\"nodes\\\": [{\\\"id\\\": \\\"ChatInput-1\\\", \\\"data\\\": {\\\"type\\\": \\\"ChatInput\\\", \\\"node\\\": {\\\"template\\\": {}, \\\"metadata\\\": {}}}}],\\n        \\\"edges\\\": [],\\n    }\\n\\n    with engine.begin() as conn:\\n        conn.execute(\\n            flow.insert(),\\n            [\\n                {\\\"id\\\": \\\"stale\\\", \\\"data\\\": stale},\\n                {\\\"id\\\": \\\"helpers\\\", \\\"data\\\": helpers_stale},\\n                {\\\"id\\\": \\\"unrec\\\", \\\"data\\\": unrecognized},\\n                {\\\"id\\\": \\\"plain\\\", \\\"data\\\": non_agent},\\n            ],\\n        )\\n\\n    _run_upgrade(migration, engine)\\n\\n    for id_ in (\\\"stale\\\", \\\"helpers\\\"):\\n        node = _load(engine, flow, id_)[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"]\\n        code = node[\\\"template\\\"][\\\"code\\\"][\\\"value\\\"]\\n        assert \\\"MemoryComponent(**self.get_base_args())\\\" not in code\\n        assert \\\"user_id=_safe_graph_user_id(self)\\\" in code\\n        # code_hash restamped and self-consistent with the rewritten code.\\n        assert node[\\\"metadata\\\"][\\\"code_hash\\\"] == hashlib.sha256(code.encode()).hexdigest()[:12]\\n        assert node[\\\"metadata\\\"][\\\"code_hash\\\"] not in (\\\"deadbeef0000\\\", \\\"deadbeef1111\\\")\\n\\n    # Unrecognized-import row left byte-for-byte intact (still vulnerable, but never broken).\\n    unrec_node = _load(engine, flow, \\\"unrec\\\")[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"]\\n    original_unrec_code = unrecognized[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"]\\n    assert unrec_node[\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] == original_unrec_code\\n    assert unrec_node[\\\"metadata\\\"][\\\"code_hash\\\"] == \\\"deadbeef2222\\\"\\n\\n    # Non-Agent flow untouched.\\n    assert _load(engine, flow, \\\"plain\\\") == non_agent\\n\\n    # Idempotent: a second run changes nothing.\\n    before = {id_: _load(engine, flow, id_) for id_ in (\\\"stale\\\", \\\"helpers\\\", \\\"unrec\\\", \\\"plain\\\")}\\n    _run_upgrade(migration, engine)\\n    after = {id_: _load(engine, flow, id_) for id_ in (\\\"stale\\\", \\\"helpers\\\", \\\"unrec\\\", \\\"plain\\\")}\\n    assert before == after\\n\\n\\ndef test_upgrade_converges_packaged_flow_to_committed_fix(migration):\\n    \\\"\\\"\\\"A row seeded with the pre-fix LangflowAssistant snapshot converges to the shipped fix.\\\"\\\"\\\"\\n    import json\\n\\n    flows_dir = Path(langflow.__file__).parent / \\\"agentic\\\" / \\\"flows\\\"\\n    fixed = json.loads((flows_dir / \\\"LangflowAssistant.json\\\").read_text())\\n    fixed_data = fixed[\\\"data\\\"]\\n\\n    # Reconstruct the pre-fix row by reversing the shipped rewrite on every Agent node.\\n    stale_data = json.loads(json.dumps(fixed_data))\\n    reversed_any = False\\n    for node in stale_data[\\\"nodes\\\"]:\\n        nd = node.get(\\\"data\\\", {})\\n        if nd.get(\\\"type\\\") != \\\"Agent\\\":\\n            continue\\n        code = nd[\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"]\\n        old_code = code.replace(migration._NEW_METHOD, migration._OLD_METHOD, 1)\\n        for old_imp, new_imp in migration._OLD_TO_NEW_IMPORT.items():\\n            old_code = old_code.replace(new_imp, old_imp, 1)\\n        nd[\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] = old_code\\n        nd[\\\"node\\\"][\\\"metadata\\\"][\\\"code_hash\\\"] = hashlib.sha256(old_code.encode()).hexdigest()[:12]\\n        reversed_any = True\\n    assert reversed_any, \\\"LangflowAssistant.json has no Agent node \u2014 test needs updating\\\"\\n\\n    engine, flow = _make_flow_table()\\n    with engine.begin() as conn:\\n        conn.execute(flow.insert(), [{\\\"id\\\": \\\"seeded\\\", \\\"data\\\": stale_data}])\\n\\n    _run_upgrade(migration, engine)\\n\\n    result = _load(engine, flow, \\\"seeded\\\")\\n\\n    def agent_snaps(data):\\n        return {\\n            n[\\\"id\\\"]: (n[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"], n[\\\"data\\\"][\\\"node\\\"][\\\"metadata\\\"][\\\"code_hash\\\"])\\n            for n in data[\\\"nodes\\\"]\\n            if n.get(\\\"data\\\", {}).get(\\\"type\\\") == \\\"Agent\\\"\\n        }\\n\\n    assert agent_snaps(result) == agent_snaps(fixed_data)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_message_flow_context_scoping.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"21c35417143d19ec6505b465f4fd63e03c9dbeaccb90a76e58f616ce6cd29a65\",\"content\":\"\\\"\\\"\\\"Regression tests: ambient flow-scope defaults ``aget_messages`` by ``flow_id`` (issue #13059).\\n\\nLangflow executes the *frozen* component ``code`` embedded in each saved flow, not the installed\\nlibrary version (``lfx.interface.initialize.loading.instantiate_class`` -> ``eval_custom_component_code``).\\nA flow saved before PR #13087 therefore carries the old ``retrieve_messages`` that calls\\n``aget_messages`` WITHOUT ``flow_id`` and leaks chat history across flows on a colliding\\n``session_id`` \u2014 even when running on a patched server.\\n\\nDefense-in-depth: the engine binds the executing graph's ``flow_id`` to a ContextVar so\\n``aget_messages`` can default the scope. This closes the leak for old frozen flows without:\\n- touching frozen code (impossible),\\n- changing callers that pass ``flow_id`` explicitly (the default only applies when it is ``None``),\\n- changing callers outside a graph run (the ContextVar is unset -> identical to today).\\n\\\"\\\"\\\"\\n\\nfrom typing import cast\\nfrom uuid import uuid4\\n\\nfrom langflow.memory import aadd_messages, aget_messages\\nfrom langflow.schema.message import Message\\nfrom lfx.components.input_output import ChatOutput\\nfrom lfx.components.models_and_agents.memory import MemoryComponent\\nfrom lfx.graph.graph.base import Graph\\nfrom lfx.memory.flow_context import reset_current_flow_id, set_current_flow_id\\nfrom lfx.schema.data import Data\\n\\n\\nasync def _store(session_id: str, flow_id, text: str) -> None:\\n    msg = Message(text=text, sender=\\\"User\\\", sender_name=\\\"User\\\", session_id=session_id)\\n    await aadd_messages([msg], flow_id=flow_id)\\n\\n\\nasync def test_aget_messages_defaults_flow_id_from_context(client):  # noqa: ARG001\\n    \\\"\\\"\\\"The reproduction: two flows share a session_id; the ambient scope isolates them.\\n\\n    Simulates old frozen code calling ``aget_messages(session_id=...)`` with no flow_id while\\n    Flow B's graph is executing. The ambient flow scope must prevent Flow A's row from leaking.\\n    \\\"\\\"\\\"\\n    flow_a, flow_b = uuid4(), uuid4()\\n    session_id = \\\"shared-session-13059\\\"\\n    await _store(session_id, flow_a, \\\"secret from A\\\")\\n    await _store(session_id, flow_b, \\\"hello from B\\\")\\n\\n    token = set_current_flow_id(flow_b)\\n    try:\\n        scoped = await aget_messages(session_id=session_id)\\n    finally:\\n        reset_current_flow_id(token)\\n\\n    assert [m.text for m in scoped] == [\\\"hello from B\\\"]\\n\\n\\nasync def test_explicit_flow_id_overrides_context(client):  # noqa: ARG001\\n    \\\"\\\"\\\"An explicitly-passed flow_id must win over the ambient context (no silent override).\\\"\\\"\\\"\\n    flow_a, flow_b = uuid4(), uuid4()\\n    session_id = \\\"shared-session-13059-explicit\\\"\\n    await _store(session_id, flow_a, \\\"secret from A\\\")\\n    await _store(session_id, flow_b, \\\"hello from B\\\")\\n\\n    token = set_current_flow_id(flow_b)\\n    try:\\n        a_msgs = await aget_messages(session_id=session_id, flow_id=flow_a)\\n    finally:\\n        reset_current_flow_id(token)\\n\\n    assert [m.text for m in a_msgs] == [\\\"secret from A\\\"]\\n\\n\\nasync def test_no_context_preserves_legacy_unscoped(client):  # noqa: ARG001\\n    \\\"\\\"\\\"With no ambient scope and no explicit flow_id, behavior is unchanged (both rows).\\\"\\\"\\\"\\n    flow_a, flow_b = uuid4(), uuid4()\\n    session_id = \\\"shared-session-13059-legacy\\\"\\n    await _store(session_id, flow_a, \\\"secret from A\\\")\\n    await _store(session_id, flow_b, \\\"hello from B\\\")\\n\\n    unscoped = await aget_messages(session_id=session_id)\\n\\n    assert len(unscoped) == 2\\n\\n\\nasync def test_context_accepts_string_flow_id(client):  # noqa: ARG001\\n    \\\"\\\"\\\"``graph.flow_id`` is commonly a ``str``; the default path must coerce it, not crash.\\n\\n    ``MessageTable.flow_id`` is UUID-typed; on SQLite comparing it to a raw string makes the\\n    ``Uuid`` bind processor call ``value.hex`` and raise. The default must coerce str -> UUID.\\n    \\\"\\\"\\\"\\n    flow_a, flow_b = uuid4(), uuid4()\\n    session_id = \\\"shared-session-13059-str\\\"\\n    await _store(session_id, flow_a, \\\"secret from A\\\")\\n    await _store(session_id, flow_b, \\\"hello from B\\\")\\n\\n    token = set_current_flow_id(str(flow_b))\\n    try:\\n        scoped = await aget_messages(session_id=session_id)\\n    finally:\\n        reset_current_flow_id(token)\\n\\n    assert [m.text for m in scoped] == [\\\"hello from B\\\"]\\n\\n\\nasync def test_invalid_context_flow_id_degrades_to_unscoped(client):  # noqa: ARG001\\n    \\\"\\\"\\\"A non-UUID ambient flow_id (synthetic/test graphs) must degrade, never crash retrieval.\\\"\\\"\\\"\\n    flow_a, flow_b = uuid4(), uuid4()\\n    session_id = \\\"shared-session-13059-badctx\\\"\\n    await _store(session_id, flow_a, \\\"secret from A\\\")\\n    await _store(session_id, flow_b, \\\"hello from B\\\")\\n\\n    token = set_current_flow_id(\\\"not-a-uuid\\\")\\n    try:\\n        result = await aget_messages(session_id=session_id)\\n    finally:\\n        reset_current_flow_id(token)\\n\\n    assert len(result) == 2\\n\\n\\nclass _OldStyleMemory(MemoryComponent):\\n    \\\"\\\"\\\"Simulates a flow saved before PR #13087: its frozen ``retrieve_messages`` omits ``flow_id``.\\n\\n    We cannot recreate frozen bytes in a unit test, so we reproduce the one behavior that matters:\\n    the internal-memory retrieve calls ``aget_messages`` with no ``flow_id``. The engine's ambient\\n    flow scope must still isolate it.\\n    \\\"\\\"\\\"\\n\\n    name = \\\"OldStyleMemory\\\"\\n\\n    async def retrieve_messages(self) -> Data:\\n        from langflow.memory import aget_messages as backend_aget_messages\\n\\n        stored = await backend_aget_messages(session_id=self.session_id, order=\\\"DESC\\\")\\n        return cast(\\\"Data\\\", list(reversed(stored)))\\n\\n\\nasync def test_graph_without_flow_id_shadows_outer_scope(client):  # noqa: ARG001\\n    \\\"\\\"\\\"A graph with no ``flow_id`` must run unscoped, not inherit an outer flow's ambient scope.\\n\\n    If an outer flow is executing (ambient scope bound) and a nested graph without ``flow_id``\\n    runs a legacy memory component, the documented fallback is legacy *unscoped* retrieval \u2014\\n    inheriting the outer flow's scope would silently attribute the messages to the wrong flow.\\n    \\\"\\\"\\\"\\n    flow_a = uuid4()\\n    session_id = \\\"shared-session-13059-shadow\\\"\\n    await _store(session_id, flow_a, \\\"SECRET_FROM_A\\\")\\n    await _store(session_id, uuid4(), \\\"hello from B\\\")\\n\\n    probe = _OldStyleMemory(_id=\\\"old_memory_shadow\\\")\\n    probe.set(session_id=session_id, n_messages=100, order=\\\"Ascending\\\")\\n    chat_output = ChatOutput(_id=\\\"chat_output_shadow\\\")\\n    chat_output.set(input_value=probe.retrieve_messages_as_text)\\n\\n    graph = Graph(probe, chat_output)  # no flow_id\\n    outer_token = set_current_flow_id(flow_a)  # simulate an outer flow still bound\\n    try:\\n        async for _ in graph.async_start():\\n            pass\\n    finally:\\n        reset_current_flow_id(outer_token)\\n\\n    rendered = chat_output.get_output_by_method(chat_output.message_response).value\\n    text = rendered.text if hasattr(rendered, \\\"text\\\") else str(rendered)\\n    assert \\\"SECRET_FROM_A\\\" in text, \\\"unscoped legacy retrieval must include Flow A's message\\\"\\n    assert \\\"hello from B\\\" in text, \\\"outer flow scope leaked into the flow_id-less graph run\\\"\\n\\n\\nasync def test_graph_execution_binds_flow_scope_end_to_end(client):  # noqa: ARG001\\n    \\\"\\\"\\\"End-to-end: running Flow B's graph must not surface Flow A's message via unscoped frozen code.\\n\\n    This is the real reproduction path \u2014 ``get_instance_results`` binds ``graph.flow_id`` so the\\n    old-style component's unscoped ``aget_messages`` call is defaulted to Flow B's scope.\\n    \\\"\\\"\\\"\\n    flow_a, flow_b = uuid4(), uuid4()\\n    session_id = \\\"shared-session-13059-e2e\\\"\\n    await _store(session_id, flow_a, \\\"SECRET_FROM_A\\\")\\n    await _store(session_id, flow_b, \\\"hello from B\\\")\\n\\n    probe = _OldStyleMemory(_id=\\\"old_memory\\\")\\n    probe.set(session_id=session_id, n_messages=100, order=\\\"Ascending\\\")\\n    chat_output = ChatOutput(_id=\\\"chat_output\\\")\\n    chat_output.set(input_value=probe.retrieve_messages_as_text)\\n\\n    graph = Graph(probe, chat_output, flow_id=str(flow_b))\\n    async for _ in graph.async_start():\\n        pass\\n\\n    rendered = chat_output.get_output_by_method(chat_output.message_response).value\\n    text = rendered.text if hasattr(rendered, \\\"text\\\") else str(rendered)\\n    assert \\\"SECRET_FROM_A\\\" not in text, \\\"Flow A's message leaked into Flow B's graph run\\\"\\n    assert \\\"hello from B\\\" in text\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_setup_superuser_flow.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b1e5380891701c0882e63ac2689281ac3e3bd6a28869e657d57523f234a1d6b0\",\"content\":\"from datetime import datetime, timezone\\nfrom unittest.mock import AsyncMock\\n\\nimport filelock\\nimport pytest\\nfrom langflow.services.auth.utils import verify_password\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.deps import get_auth_service, get_settings_service, session_scope\\nfrom langflow.services.utils import SetupSuperuserResult, setup_superuser, teardown_superuser\\nfrom lfx.services.settings.constants import (\\n    DEFAULT_SUPERUSER,\\n    DEFAULT_SUPERUSER_PASSWORD,\\n    LEGACY_DEFAULT_SUPERUSER_PASSWORD,\\n)\\nfrom pydantic import SecretStr\\nfrom sqlmodel import select\\n\\n_MOCK_AUTO_LOGIN_LOCK_TIMEOUT_MSG = \\\"mock lock timeout\\\"\\n\\n\\n@pytest.fixture\\nasync def initialized_services(monkeypatch, tmp_path):\\n    \\\"\\\"\\\"Lightweight fixture: initializes DB + services WITHOUT starting the full app.\\n\\n    Unlike the `client` fixture, this does NOT create a FastAPI app or use\\n    LifespanManager. This avoids the heavy lifespan startup/shutdown (MCP servers,\\n    background tasks, streamable HTTP) that causes hangs on CI Linux.\\n    \\\"\\\"\\\"\\n    from langflow.services.utils import initialize_services, teardown_services\\n    from lfx.services.manager import get_service_manager\\n\\n    db_path = tmp_path / \\\"test.db\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_DATABASE_URL\\\", f\\\"sqlite:///{db_path}\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_AUTO_LOGIN\\\", \\\"false\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_SUPERUSER\\\", DEFAULT_SUPERUSER)\\n    monkeypatch.setenv(\\\"LANGFLOW_SUPERUSER_PASSWORD\\\", \\\"test-superuser-password\\\")\\n\\n    get_service_manager().factories.clear()\\n    get_service_manager().services.clear()\\n\\n    await initialize_services()\\n\\n    yield\\n\\n    await teardown_services()\\n\\n\\nasync def test_server_startup_imports_environment_for_existing_users(initialized_services, monkeypatch):  # noqa: ARG001\\n    \\\"\\\"\\\"Startup must import newly configured variables for SSO and password users.\\\"\\\"\\\"\\n    from langflow.preload import _STATE, initialize_environment_variables\\n    from langflow.services.database.models.auth import SSOUserProfile\\n    from langflow.services.deps import get_variable_service\\n    from langflow.services.utils import initialize_services\\n\\n    async with session_scope() as session:\\n        # Cross the startup sweep's page boundary, including an existing SSO account.\\n        users = [\\n            User(username=f\\\"existing-user-{index}\\\", password=\\\"unused\\\")  # noqa: S106  # pragma: allowlist secret\\n            for index in range(101)\\n        ]\\n        session.add_all(users)\\n        await session.flush()\\n        user_ids = [user.id for user in users]\\n        session.add(SSOUserProfile(user_id=user_ids[0], sso_provider=\\\"external\\\", sso_user_id=\\\"existing-subject\\\"))\\n\\n    settings = get_settings_service().settings\\n    monkeypatch.setattr(settings, \\\"store_environment_variables\\\", True)\\n    monkeypatch.setattr(settings, \\\"variables_to_get_from_environment\\\", [\\\"NEW_SERVICE_URL\\\"])\\n    for env_value in [\\\"https://service.example.com\\\", \\\"https://rotated.example.com\\\"]:\\n        monkeypatch.setenv(\\\"NEW_SERVICE_URL\\\", env_value)\\n        await initialize_services(skip_superuser_setup=True)\\n        monkeypatch.setattr(_STATE, \\\"environment_variables_initialized\\\", False)\\n        await initialize_environment_variables()\\n\\n        async with session_scope() as session:\\n            for user_id in user_ids:\\n                value = await get_variable_service().get_variable(user_id, \\\"NEW_SERVICE_URL\\\", \\\"\\\", session)\\n                assert value.get_secret_value() == env_value\\n\\n\\nasync def test_cli_service_initialization_does_not_sweep_users(initialized_services, monkeypatch):  # noqa: ARG001\\n    \\\"\\\"\\\"Shared service initialization used by migration commands must not run the sweep.\\\"\\\"\\\"\\n    from langflow.services.deps import get_variable_service\\n    from langflow.services.utils import initialize_services\\n\\n    sweep = AsyncMock()\\n    monkeypatch.setattr(get_variable_service(), \\\"initialize_all_user_variables\\\", sweep)\\n    await initialize_services(skip_superuser_setup=True)\\n    sweep.assert_not_awaited()\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.timeout(30)\\nasync def test_initialize_services_creates_default_superuser_when_auto_login_true(initialized_services):  # noqa: ARG001\\n    \\\"\\\"\\\"Test that setup_superuser creates the default superuser when AUTO_LOGIN=True.\\\"\\\"\\\"\\n    settings = get_settings_service()\\n    settings.auth_settings.AUTO_LOGIN = True\\n\\n    async with session_scope() as session:\\n        result = await setup_superuser(settings, session)\\n        assert result in (\\n            SetupSuperuserResult.AUTO_LOGIN_INITIALIZED,\\n            SetupSuperuserResult.AUTO_LOGIN_ALREADY_SATISFIED,\\n        )\\n\\n    async with session_scope() as session:\\n        stmt = select(User).where(User.username == DEFAULT_SUPERUSER)\\n        user = (await session.exec(stmt)).first()\\n        assert user is not None\\n        assert user.is_superuser is True\\n        assert verify_password(\\\"test-superuser-password\\\", user.password) is True\\n        assert verify_password(LEGACY_DEFAULT_SUPERUSER_PASSWORD.get_secret_value(), user.password) is False\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.timeout(30)\\nasync def test_setup_superuser_auto_login_rotates_legacy_default_password(initialized_services):  # noqa: ARG001\\n    \\\"\\\"\\\"AUTO_LOGIN startup rotates old langflow/langflow hashes left by previous releases.\\\"\\\"\\\"\\n    settings = get_settings_service()\\n    settings.auth_settings.AUTO_LOGIN = True\\n    settings.auth_settings.SUPERUSER = DEFAULT_SUPERUSER\\n    settings.auth_settings.SUPERUSER_PASSWORD = DEFAULT_SUPERUSER_PASSWORD\\n    legacy_password = LEGACY_DEFAULT_SUPERUSER_PASSWORD.get_secret_value()\\n\\n    async with session_scope() as session:\\n        stmt = select(User).where(User.username == DEFAULT_SUPERUSER)\\n        user = (await session.exec(stmt)).first()\\n        if user is None:\\n            user = User(\\n                username=DEFAULT_SUPERUSER,\\n                password=get_auth_service().get_password_hash(legacy_password),\\n                is_superuser=True,\\n                is_active=True,\\n            )\\n            session.add(user)\\n            await session.flush()\\n        else:\\n            user.password = get_auth_service().get_password_hash(legacy_password)\\n        user.is_superuser = True\\n        await session.commit()\\n\\n    async with session_scope() as session:\\n        result = await setup_superuser(settings, session)\\n        assert result == SetupSuperuserResult.AUTO_LOGIN_ALREADY_SATISFIED\\n\\n    async with session_scope() as session:\\n        user = (await session.exec(select(User).where(User.username == DEFAULT_SUPERUSER))).first()\\n        assert user is not None\\n        assert verify_password(legacy_password, user.password) is False\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.timeout(30)\\nasync def test_setup_superuser_rotates_legacy_default_password_when_auto_login_false(\\n    initialized_services,  # noqa: ARG001\\n):\\n    \\\"\\\"\\\"Authenticated startup rotates old langflow/langflow hashes to the configured password.\\\"\\\"\\\"\\n    settings = get_settings_service()\\n    settings.auth_settings.AUTO_LOGIN = False\\n    settings.auth_settings.SUPERUSER = DEFAULT_SUPERUSER\\n    settings.auth_settings.SUPERUSER_PASSWORD = SecretStr(\\\"rotated-production-password\\\")\\n    legacy_password = LEGACY_DEFAULT_SUPERUSER_PASSWORD.get_secret_value()\\n\\n    async with session_scope() as session:\\n        stmt = select(User).where(User.username == DEFAULT_SUPERUSER)\\n        user = (await session.exec(stmt)).first()\\n        if user is None:\\n            user = User(\\n                username=DEFAULT_SUPERUSER,\\n                password=get_auth_service().get_password_hash(legacy_password),\\n                is_superuser=True,\\n                is_active=True,\\n            )\\n            session.add(user)\\n            await session.flush()\\n        user.password = get_auth_service().get_password_hash(legacy_password)\\n        user.is_superuser = True\\n        user.is_active = True\\n        user.last_login_at = datetime.now(timezone.utc)\\n        await session.commit()\\n\\n    async with session_scope() as session:\\n        result = await setup_superuser(settings, session)\\n        assert result == SetupSuperuserResult.SUPERUSER_UNCHANGED\\n\\n    async with session_scope() as session:\\n        user = (await session.exec(select(User).where(User.username == DEFAULT_SUPERUSER))).first()\\n        assert user is not None\\n        assert verify_password(\\\"rotated-production-password\\\", user.password) is True\\n        assert verify_password(legacy_password, user.password) is False\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.timeout(30)\\nasync def test_setup_superuser_auto_login_fails_when_username_is_not_superuser(initialized_services):  # noqa: ARG001\\n    \\\"\\\"\\\"AUTO_LOGIN setup must not accept an existing non-superuser bootstrap username.\\\"\\\"\\\"\\n    settings = get_settings_service()\\n    settings.auth_settings.AUTO_LOGIN = True\\n    settings.auth_settings.SUPERUSER = \\\"regular-user\\\"\\n    settings.auth_settings.SUPERUSER_PASSWORD = DEFAULT_SUPERUSER_PASSWORD\\n\\n    async with session_scope() as session:\\n        user = User(\\n            username=\\\"regular-user\\\",\\n            password=get_auth_service().get_password_hash(\\\"regular-password\\\"),\\n            is_superuser=False,\\n            is_active=True,\\n        )\\n        session.add(user)\\n        await session.commit()\\n\\n    async with session_scope() as session:\\n        with pytest.raises(RuntimeError, match=\\\"not a superuser\\\"):\\n            await setup_superuser(settings, session)\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.timeout(30)\\nasync def test_teardown_superuser_removes_default_if_never_logged(initialized_services):  # noqa: ARG001\\n    \\\"\\\"\\\"AUTO_LOGIN=False removes the default superuser when they have never signed in.\\\"\\\"\\\"\\n    settings = get_settings_service()\\n    settings.auth_settings.AUTO_LOGIN = False\\n\\n    # The initialized_services fixture already called initialize_services(),\\n    # which created the default superuser. Ensure it exists and has never logged in.\\n    async with session_scope() as session:\\n        stmt = select(User).where(User.username == DEFAULT_SUPERUSER)\\n        user = (await session.exec(stmt)).first()\\n        if not user:\\n            user = User(\\n                username=DEFAULT_SUPERUSER,\\n                password=get_auth_service().get_password_hash(\\\"test-superuser-password\\\"),\\n                is_superuser=True,\\n                is_active=True,\\n            )\\n            session.add(user)\\n            await session.commit()\\n            await session.refresh(user)\\n        user.last_login_at = None\\n        user.is_superuser = True\\n        await session.commit()\\n\\n    async with session_scope() as session:\\n        await teardown_superuser(settings, session)\\n\\n    async with session_scope() as session:\\n        stmt = select(User).where(User.username == DEFAULT_SUPERUSER)\\n        assert (await session.exec(stmt)).first() is None\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.timeout(30)\\nasync def test_teardown_superuser_preserves_logged_in_default(initialized_services):  # noqa: ARG001\\n    \\\"\\\"\\\"Test that teardown preserves default superuser if they have logged in.\\\"\\\"\\\"\\n    from datetime import datetime, timezone\\n\\n    settings = get_settings_service()\\n    settings.auth_settings.AUTO_LOGIN = False\\n\\n    # The initialized_services fixture already created the default superuser.\\n    async with session_scope() as session:\\n        stmt = select(User).where(User.username == DEFAULT_SUPERUSER)\\n        user = (await session.exec(stmt)).first()\\n        if not user:\\n            user = User(\\n                username=DEFAULT_SUPERUSER,\\n                password=get_auth_service().get_password_hash(\\\"test-superuser-password\\\"),\\n                is_superuser=True,\\n                is_active=True,\\n            )\\n            session.add(user)\\n            await session.commit()\\n            await session.refresh(user)\\n\\n        # Mark user as having logged in\\n        user.last_login_at = datetime.now(timezone.utc)\\n        user.is_superuser = True\\n        await session.commit()\\n\\n    # Run teardown and verify user is preserved\\n    async with session_scope() as session:\\n        await teardown_superuser(settings, session)\\n\\n    async with session_scope() as session:\\n        stmt = select(User).where(User.username == DEFAULT_SUPERUSER)\\n        user = (await session.exec(stmt)).first()\\n        assert user is not None\\n        assert user.is_superuser is True\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.timeout(30)\\nasync def test_setup_superuser_with_no_configured_credentials_fails_closed(initialized_services):  # noqa: ARG001\\n    \\\"\\\"\\\"AUTO_LOGIN=False must not create a superuser from predictable fallback credentials.\\\"\\\"\\\"\\n    settings = get_settings_service()\\n    settings.auth_settings.AUTO_LOGIN = False\\n    settings.auth_settings.SUPERUSER = \\\"\\\"\\n    # Reset password to empty\\n    settings.auth_settings.SUPERUSER_PASSWORD = \\\"\\\"\\n\\n    async with session_scope() as session:\\n        with pytest.raises(ValueError, match=\\\"Username and password must be set\\\"):\\n            await setup_superuser(settings, session)\\n\\n\\n@pytest.mark.parametrize(\\\"username\\\", [DEFAULT_SUPERUSER, \\\"custom_admin\\\"])\\n@pytest.mark.asyncio\\n@pytest.mark.timeout(30)\\nasync def test_setup_superuser_rejects_legacy_default_password_when_auto_login_false(\\n    initialized_services,  # noqa: ARG001\\n    username,\\n):\\n    \\\"\\\"\\\"Authenticated startup must not create a superuser with the legacy default password.\\\"\\\"\\\"\\n    settings = get_settings_service()\\n    settings.auth_settings.AUTO_LOGIN = False\\n    settings.auth_settings.SUPERUSER = username\\n    settings.auth_settings.SUPERUSER_PASSWORD = LEGACY_DEFAULT_SUPERUSER_PASSWORD\\n\\n    async with session_scope() as session:\\n        with pytest.raises(ValueError, match=\\\"legacy default password\\\"):\\n            await setup_superuser(settings, session)\\n\\n    async with session_scope() as session:\\n        user = (await session.exec(select(User).where(User.username == username))).first()\\n        assert user is None\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.timeout(30)\\nasync def test_setup_superuser_auto_login_ignores_configured_legacy_default_password(\\n    initialized_services,  # noqa: ARG001\\n):\\n    \\\"\\\"\\\"AUTO_LOGIN startup must not persist langflow/langflow even when env config provides it.\\\"\\\"\\\"\\n    settings = get_settings_service()\\n    settings.auth_settings.AUTO_LOGIN = True\\n    settings.auth_settings.SUPERUSER = DEFAULT_SUPERUSER\\n    settings.auth_settings.SUPERUSER_PASSWORD = LEGACY_DEFAULT_SUPERUSER_PASSWORD\\n    legacy_password = LEGACY_DEFAULT_SUPERUSER_PASSWORD.get_secret_value()\\n\\n    async with session_scope() as session:\\n        user = (await session.exec(select(User).where(User.username == DEFAULT_SUPERUSER))).first()\\n        assert user is not None\\n        user.password = get_auth_service().get_password_hash(legacy_password)\\n        user.is_superuser = True\\n        user.is_active = True\\n        await session.commit()\\n\\n    async with session_scope() as session:\\n        assert await setup_superuser(settings, session) == SetupSuperuserResult.AUTO_LOGIN_ALREADY_SATISFIED\\n\\n    async with session_scope() as session:\\n        user = (await session.exec(select(User).where(User.username == DEFAULT_SUPERUSER))).first()\\n        assert user is not None\\n        assert user.is_superuser is True\\n        assert verify_password(legacy_password, user.password) is False\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.timeout(30)\\nasync def test_setup_superuser_with_custom_credentials(initialized_services):  # noqa: ARG001\\n    \\\"\\\"\\\"Test setup_superuser behavior with custom superuser credentials.\\\"\\\"\\\"\\n    settings = get_settings_service()\\n    settings.auth_settings.AUTO_LOGIN = False\\n    settings.auth_settings.SUPERUSER = \\\"custom_admin\\\"\\n    settings.auth_settings.SUPERUSER_PASSWORD = SecretStr(\\\"custom_password\\\")\\n\\n    # Clean DB state to avoid interference from previous tests\\n    async with session_scope() as session:\\n        # Ensure default can be removed by teardown (last_login_at must be None)\\n        stmt = select(User).where(User.username == DEFAULT_SUPERUSER)\\n        default_user = (await session.exec(stmt)).first()\\n        if default_user:\\n            default_user.last_login_at = None\\n            await session.commit()\\n            await teardown_superuser(settings, session)\\n\\n        # Remove any pre-existing custom_admin user\\n        stmt = select(User).where(User.username == \\\"custom_admin\\\")\\n        existing_custom = (await session.exec(stmt)).first()\\n        if existing_custom:\\n            await session.delete(existing_custom)\\n            await session.commit()\\n\\n    async with session_scope() as session:\\n        assert await setup_superuser(settings, session) == SetupSuperuserResult.SUPERUSER_CREATED\\n\\n        # Verify custom superuser was created\\n        stmt = select(User).where(User.username == \\\"custom_admin\\\")\\n        user = (await session.exec(stmt)).first()\\n        assert user is not None\\n        assert user.is_superuser is True\\n        # Password should be hashed (not equal to the raw) and verify correctly\\n        assert user.password != \\\"custom_password\\\"  # noqa: S105\\n        assert verify_password(\\\"custom_password\\\", user.password) is True\\n\\n        # Verify default superuser was not created\\n        stmt = select(User).where(User.username == DEFAULT_SUPERUSER)\\n        default_user = (await session.exec(stmt)).first()\\n        assert default_user is None\\n\\n        # Settings credentials should be scrubbed after setup\\n        assert settings.auth_settings.SUPERUSER_PASSWORD.get_secret_value() == \\\"\\\"\\n\\n    # Cleanup: remove custom_admin to not leak state across tests\\n    async with session_scope() as session:\\n        stmt = select(User).where(User.username == \\\"custom_admin\\\")\\n        created_custom = (await session.exec(stmt)).first()\\n        if created_custom:\\n            await session.delete(created_custom)\\n            await session.commit()\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.timeout(30)\\nasync def test_setup_superuser_auto_login_lock_timeout_raises_when_no_superuser(initialized_services, monkeypatch):  # noqa: ARG001\\n    \\\"\\\"\\\"If the AUTO_LOGIN lock times out and no default superuser exists, startup must fail loudly.\\\"\\\"\\\"\\n    settings = get_settings_service()\\n    settings.auth_settings.AUTO_LOGIN = True\\n\\n    # The fixture initializes services with AUTO_LOGIN=false, which creates the default\\n    # superuser via the credentials-fallback path. Remove it so we exercise the\\n    # \\\"lock timed out and no superuser exists\\\" branch.\\n    async with session_scope() as session:\\n        stmt = select(User).where(User.username == DEFAULT_SUPERUSER)\\n        user = (await session.exec(stmt)).first()\\n        if user is not None:\\n            await session.delete(user)\\n            await session.commit()\\n\\n    class _FailingLock:\\n        def __init__(self, *args, **kwargs):\\n            pass\\n\\n        def __enter__(self):\\n            msg = _MOCK_AUTO_LOGIN_LOCK_TIMEOUT_MSG\\n            raise TimeoutError(msg)\\n\\n        def __exit__(self, *args):\\n            return False\\n\\n    monkeypatch.setattr(filelock, \\\"FileLock\\\", _FailingLock)\\n\\n    async with session_scope() as session:\\n        with pytest.raises(\\n            RuntimeError,\\n            match=\\\"AUTO_LOGIN is enabled but the default superuser was not initialized\\\",\\n        ):\\n            await setup_superuser(settings, session)\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.timeout(30)\\nasync def test_setup_superuser_auto_login_lock_timeout_ok_when_superuser_exists(initialized_services, monkeypatch):  # noqa: ARG001\\n    \\\"\\\"\\\"If the lock times out but the default superuser already exists, setup continues without error.\\\"\\\"\\\"\\n    settings = get_settings_service()\\n    settings.auth_settings.AUTO_LOGIN = True\\n\\n    async with session_scope() as session:\\n        await get_auth_service().create_super_user(\\n            DEFAULT_SUPERUSER,\\n            \\\"test-superuser-password\\\",\\n            db=session,\\n        )\\n\\n    class _FailingLock:\\n        def __init__(self, *args, **kwargs):\\n            pass\\n\\n        def __enter__(self):\\n            msg = _MOCK_AUTO_LOGIN_LOCK_TIMEOUT_MSG\\n            raise TimeoutError(msg)\\n\\n        def __exit__(self, *args):\\n            return False\\n\\n    monkeypatch.setattr(filelock, \\\"FileLock\\\", _FailingLock)\\n\\n    async with session_scope() as session:\\n        assert (\\n            await setup_superuser(settings, session) == SetupSuperuserResult.AUTO_LOGIN_LOCK_TIMEOUT_SUPERUSER_PRESENT\\n        )\\n\\n    async with session_scope() as session:\\n        stmt = select(User).where(User.username == DEFAULT_SUPERUSER)\\n        user = (await session.exec(stmt)).first()\\n        assert user is not None\\n        assert user.is_superuser is True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_flow_secrets.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c1c17d5d3200b7adb37f5c7ca213379d84157aaa000a2064b6ca67e41adcf634\",\"content\":\"\\\"\\\"\\\"Tests for load_from_db reference handling in the flow secret scrubbers.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom langflow.utils.flow_secrets import strip_secret_field_values, strip_secret_field_values_in_place\\n\\n\\ndef _flow_data(template: dict) -> dict:\\n    return {\\\"nodes\\\": [{\\\"data\\\": {\\\"node\\\": {\\\"template\\\": template}}}], \\\"edges\\\": []}\\n\\n\\ndef _template(flow_data: dict) -> dict:\\n    return flow_data[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n\\n\\ndef test_default_scrub_still_nulls_variable_references() -> None:\\n    \\\"\\\"\\\"Anonymous consumers (public flow endpoint) must not see variable names.\\\"\\\"\\\"\\n    flow_data = _flow_data(\\n        {\\\"api_key\\\": {\\\"name\\\": \\\"api_key\\\", \\\"password\\\": True, \\\"load_from_db\\\": True, \\\"value\\\": \\\"OPENAI_API_KEY\\\"}}\\n    )\\n\\n    stripped = strip_secret_field_values(flow_data)\\n\\n    assert _template(stripped)[\\\"api_key\\\"][\\\"value\\\"] is None\\n    assert _template(flow_data)[\\\"api_key\\\"][\\\"value\\\"] == \\\"OPENAI_API_KEY\\\"\\n\\n\\ndef test_preserving_scrub_keeps_and_collects_variable_references() -> None:\\n    flow_data = _flow_data(\\n        {\\n            \\\"api_key\\\": {\\\"name\\\": \\\"api_key\\\", \\\"password\\\": True, \\\"load_from_db\\\": True, \\\"value\\\": \\\"OPENAI_API_KEY\\\"},\\n            \\\"password\\\": {\\\"name\\\": \\\"password\\\", \\\"password\\\": True, \\\"value\\\": \\\"raw-password\\\"},\\n            \\\"endpoint\\\": {\\\"name\\\": \\\"endpoint\\\", \\\"load_from_db\\\": True, \\\"value\\\": \\\"MY_INTERNAL_API_URL\\\"},\\n        }\\n    )\\n    variable_references: set[str] = set()\\n\\n    strip_secret_field_values_in_place(flow_data, variable_references=variable_references)\\n\\n    template = _template(flow_data)\\n    assert template[\\\"api_key\\\"][\\\"value\\\"] == \\\"OPENAI_API_KEY\\\"\\n    assert template[\\\"password\\\"][\\\"value\\\"] is None\\n    assert template[\\\"endpoint\\\"][\\\"value\\\"] == \\\"MY_INTERNAL_API_URL\\\"\\n    assert variable_references == {\\\"OPENAI_API_KEY\\\", \\\"MY_INTERNAL_API_URL\\\"}\\n\\n\\ndef test_preserving_scrub_nulls_values_that_do_not_look_like_references() -> None:\\n    \\\"\\\"\\\"A mislabelled load_from_db field must not smuggle a raw secret through.\\\"\\\"\\\"\\n    invalid_values = [\\n        \\\"\\\",\\n        \\\"   \\\",\\n        \\\"a\\\" * 257,\\n        \\\"line\\\\nbreak\\\",\\n        \\\"tab\\\\tseparated\\\",\\n        1234,\\n        {\\\"nested\\\": \\\"dict\\\"},\\n        # URL built at runtime so secret-scanners do not flag a literal credential.\\n        \\\"postgres://user:{}@db.internal/prod\\\".format(\\\"testpw\\\"),\\n    ]\\n    template = {\\n        f\\\"field_{index}\\\": {\\\"name\\\": f\\\"field_{index}\\\", \\\"password\\\": True, \\\"load_from_db\\\": True, \\\"value\\\": value}\\n        for index, value in enumerate(invalid_values)\\n    }\\n    flow_data = _flow_data(template)\\n    variable_references: set[str] = set()\\n\\n    strip_secret_field_values_in_place(flow_data, variable_references=variable_references)\\n\\n    for field in _template(flow_data).values():\\n        assert field[\\\"value\\\"] is None\\n    assert variable_references == set()\\n\\n\\ndef test_preserving_scrub_collects_references_from_nested_group_nodes() -> None:\\n    nested_template = {\\\"api_key\\\": {\\\"name\\\": \\\"api_key\\\", \\\"password\\\": True, \\\"load_from_db\\\": True, \\\"value\\\": \\\"NESTED_KEY\\\"}}\\n    flow_data = {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"data\\\": {\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {},\\n                        \\\"flow\\\": {\\\"data\\\": _flow_data(nested_template)},\\n                    }\\n                }\\n            }\\n        ],\\n        \\\"edges\\\": [],\\n    }\\n    variable_references: set[str] = set()\\n\\n    strip_secret_field_values_in_place(flow_data, variable_references=variable_references)\\n\\n    nested = flow_data[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"flow\\\"][\\\"data\\\"]\\n    assert _template(nested)[\\\"api_key\\\"][\\\"value\\\"] == \\\"NESTED_KEY\\\"\\n    assert variable_references == {\\\"NESTED_KEY\\\"}\\n\\n\\ndef test_preserving_scrub_handles_table_reference_columns() -> None:\\n    flow_data = _flow_data(\\n        {\\n            \\\"headers\\\": {\\n                \\\"name\\\": \\\"headers\\\",\\n                \\\"type\\\": \\\"table\\\",\\n                \\\"table_schema\\\": [\\n                    {\\\"name\\\": \\\"api_key\\\", \\\"load_from_db\\\": True},\\n                    {\\\"name\\\": \\\"note\\\"},\\n                ],\\n                \\\"value\\\": [\\n                    {\\n                        \\\"api_key\\\": \\\"TENANT_TOKEN\\\",  # pragma: allowlist secret\\n                        \\\"note\\\": \\\"kept\\\",\\n                        \\\"client_secret\\\": \\\"raw-secret\\\",  # pragma: allowlist secret\\n                    },\\n                    {\\\"api_key\\\": \\\"bad\\\\nreference\\\", \\\"note\\\": \\\"kept\\\"},  # pragma: allowlist secret\\n                ],\\n            }\\n        }\\n    )\\n    variable_references: set[str] = set()\\n\\n    strip_secret_field_values_in_place(flow_data, variable_references=variable_references)\\n\\n    rows = _template(flow_data)[\\\"headers\\\"][\\\"value\\\"]\\n    assert rows[0][\\\"api_key\\\"] == \\\"TENANT_TOKEN\\\"  # pragma: allowlist secret\\n    assert rows[0][\\\"note\\\"] == \\\"kept\\\"\\n    assert rows[0][\\\"client_secret\\\"] is None\\n    assert rows[1][\\\"api_key\\\"] is None\\n    assert variable_references == {\\\"TENANT_TOKEN\\\"}\\n\\n\\ndef test_preserving_scrub_nulls_table_cells_marked_as_literals() -> None:\\n    \\\"\\\"\\\"A cell the row excludes from load_from_db holds the secret, not its name.\\\"\\\"\\\"\\n    flow_data = _flow_data(\\n        {\\n            \\\"headers\\\": {\\n                \\\"name\\\": \\\"headers\\\",\\n                \\\"type\\\": \\\"table\\\",\\n                \\\"table_schema\\\": [{\\\"name\\\": \\\"value\\\", \\\"load_from_db\\\": True}],\\n                \\\"value\\\": [\\n                    {\\n                        \\\"key\\\": \\\"Authorization\\\",\\n                        \\\"value\\\": \\\"Bearer raw-token\\\",  # pragma: allowlist secret\\n                        \\\"__load_from_db_fields\\\": {\\\"value\\\": False},\\n                    },\\n                    {\\n                        \\\"key\\\": \\\"X-Tenant-Key\\\",\\n                        \\\"value\\\": \\\"TENANT_TOKEN\\\",  # pragma: allowlist secret\\n                        \\\"__load_from_db_fields\\\": {\\\"value\\\": True},\\n                    },\\n                    # A row that records no choice keeps the schema default, so\\n                    # the runtime resolves it and the value is a variable name.\\n                    {\\\"key\\\": \\\"X-Legacy-Key\\\", \\\"value\\\": \\\"LEGACY_TOKEN\\\"},  # pragma: allowlist secret\\n                    # The list form names the columns that do load from the\\n                    # database, so an absent column is a literal.\\n                    {\\n                        \\\"key\\\": \\\"X-Other-Key\\\",\\n                        \\\"value\\\": \\\"another-raw-token\\\",  # pragma: allowlist secret\\n                        \\\"__load_from_db_fields\\\": [\\\"unrelated\\\"],\\n                    },\\n                ],\\n            }\\n        }\\n    )\\n    variable_references: set[str] = set()\\n\\n    strip_secret_field_values_in_place(flow_data, variable_references=variable_references)\\n\\n    rows = _template(flow_data)[\\\"headers\\\"][\\\"value\\\"]\\n    assert rows[0][\\\"value\\\"] is None\\n    assert rows[1][\\\"value\\\"] == \\\"TENANT_TOKEN\\\"  # pragma: allowlist secret\\n    assert rows[2][\\\"value\\\"] == \\\"LEGACY_TOKEN\\\"  # pragma: allowlist secret\\n    assert rows[3][\\\"value\\\"] is None\\n    assert variable_references == {\\\"TENANT_TOKEN\\\", \\\"LEGACY_TOKEN\\\"}\\n\\n\\ndef test_preserving_scrub_keeps_per_cell_metadata_for_secret_named_columns() -> None:\\n    \\\"\\\"\\\"Scrubbing must not flip a reference cell into a literal at the target.\\\"\\\"\\\"\\n    flow_data = _flow_data(\\n        {\\n            \\\"connections\\\": {\\n                \\\"name\\\": \\\"connections\\\",\\n                \\\"type\\\": \\\"table\\\",\\n                \\\"table_schema\\\": [{\\\"name\\\": \\\"password\\\", \\\"load_from_db\\\": True}],\\n                \\\"value\\\": [\\n                    {\\n                        \\\"host\\\": \\\"db.internal\\\",\\n                        \\\"pass\\\" + \\\"word\\\": \\\"DB_CONN_VAR\\\",\\n                        \\\"__load_from_db_fields\\\": {\\\"password\\\": True},\\n                    }\\n                ],\\n            }\\n        }\\n    )\\n    variable_references: set[str] = set()\\n\\n    strip_secret_field_values_in_place(flow_data, variable_references=variable_references)\\n\\n    row = _template(flow_data)[\\\"connections\\\"][\\\"value\\\"][0]\\n    assert row[\\\"password\\\"] == \\\"DB_CONN_VAR\\\"  # noqa: S105  # pragma: allowlist secret\\n    assert row[\\\"__load_from_db_fields\\\"] == {\\\"password\\\": True}\\n    assert variable_references == {\\\"DB_CONN_VAR\\\"}\\n\\n\\ndef test_preserving_scrub_nulls_values_shaped_like_issued_credentials() -> None:\\n    \\\"\\\"\\\"Well-known credential shapes are never global-variable names.\\\"\\\"\\\"\\n    credential_values = [\\n        \\\"sk-live-abc123XYZ\\\",  # pragma: allowlist secret\\n        \\\"ghp_aBcD1234efGH\\\",  # pragma: allowlist secret\\n        \\\"ASIAZZZZZZZZZZZZZZZZ\\\",  # pragma: allowlist secret\\n        \\\"glpat-abcdefghijkl\\\",  # pragma: allowlist secret\\n        \\\"xoxb-1234-5678-abcd\\\",  # pragma: allowlist secret\\n        \\\"hf_abcdefghijklmnop\\\",  # pragma: allowlist secret\\n    ]\\n    template = {\\n        f\\\"field_{index}\\\": {\\\"name\\\": f\\\"field_{index}\\\", \\\"password\\\": True, \\\"load_from_db\\\": True, \\\"value\\\": value}\\n        for index, value in enumerate(credential_values)\\n    }\\n    flow_data = _flow_data(template)\\n    variable_references: set[str] = set()\\n\\n    strip_secret_field_values_in_place(flow_data, variable_references=variable_references)\\n\\n    for field in _template(flow_data).values():\\n        assert field[\\\"value\\\"] is None\\n    assert variable_references == set()\\n\\n\\ndef test_preserving_scrub_keeps_names_that_merely_resemble_credential_prefixes() -> None:\\n    \\\"\\\"\\\"Upper snake case names must survive the issued-credential shape check.\\\"\\\"\\\"\\n    reference_names = [\\n        \\\"HF_TOKEN\\\",  # pragma: allowlist secret\\n        \\\"ASIA_REGION_KEY\\\",  # pragma: allowlist secret\\n        \\\"AKIA_ROTATION_SCHEDULE\\\",  # pragma: allowlist secret\\n        \\\"SK_BILLING_ACCOUNT\\\",  # pragma: allowlist secret\\n        \\\"GHP_DEPLOY_TOKEN\\\",  # pragma: allowlist secret\\n    ]\\n    template = {\\n        f\\\"field_{index}\\\": {\\\"name\\\": f\\\"field_{index}\\\", \\\"password\\\": True, \\\"load_from_db\\\": True, \\\"value\\\": value}\\n        for index, value in enumerate(reference_names)\\n    }\\n    flow_data = _flow_data(template)\\n    variable_references: set[str] = set()\\n\\n    strip_secret_field_values_in_place(flow_data, variable_references=variable_references)\\n\\n    assert variable_references == set(reference_names)\\n\\n\\ndef test_default_scrub_still_nulls_table_reference_columns() -> None:\\n    flow_data = _flow_data(\\n        {\\n            \\\"headers\\\": {\\n                \\\"name\\\": \\\"headers\\\",\\n                \\\"type\\\": \\\"table\\\",\\n                \\\"table_schema\\\": [{\\\"name\\\": \\\"api_key\\\", \\\"load_from_db\\\": True}],\\n                \\\"value\\\": [{\\\"api_key\\\": \\\"TENANT_TOKEN\\\", \\\"note\\\": \\\"kept\\\"}],  # pragma: allowlist secret\\n            }\\n        }\\n    )\\n\\n    strip_secret_field_values_in_place(flow_data)\\n\\n    rows = _template(flow_data)[\\\"headers\\\"][\\\"value\\\"]\\n    assert rows[0][\\\"api_key\\\"] is None\\n    assert rows[0][\\\"note\\\"] == \\\"kept\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/confluent/src/lfx_confluent/components/confluent/tableflow_reader.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"32a2ea34cc411e313cbc9d69f7aee77c033bc63565807633be86232cd3f8baa6\",\"content\":\"\\\"\\\"\\\"Read Confluent Tableflow tables (Kafka topics materialized as Apache Iceberg) into a DataFrame.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nfrom typing import Any\\n\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import DropdownInput, IntInput, MessageTextInput, Output, SecretStrInput, StrInput\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import DataFrame\\nfrom lfx_confluent.components.confluent._common import (\\n    DEFAULT_CLOUD,\\n    DEFAULT_REGION,\\n    ensure_url_allowed,\\n    require_token,\\n    tableflow_catalog_url,\\n)\\n\\nSTORAGE_CONFLUENT_MANAGED = \\\"confluent_managed\\\"\\nSTORAGE_BYOS = \\\"byos\\\"\\nSTORAGE_OPTIONS = [STORAGE_CONFLUENT_MANAGED, STORAGE_BYOS]\\n\\nDELEGATION_VENDED = \\\"vended-credentials\\\"\\nDELEGATION_REMOTE_SIGNING = \\\"remote-signing\\\"\\nDELEGATION_NONE = \\\"none\\\"\\nDELEGATION_OPTIONS = [DELEGATION_VENDED, DELEGATION_REMOTE_SIGNING, DELEGATION_NONE]\\n\\nDEFAULT_LIMIT = 1000\\nMAX_LIMIT = 100_000\\nBYOS_FIELDS = (\\\"s3_access_key_id\\\", \\\"s3_secret_access_key\\\", \\\"s3_region\\\")\\n\\n\\nclass ConfluentTableflowReaderComponent(Component):\\n    \\\"\\\"\\\"Query a Tableflow-materialized Iceberg table through the Tableflow REST catalog.\\n\\n    Tableflow turns a Kafka topic into an Apache Iceberg table and serves it\\n    through a standards-based Iceberg REST catalog.  This component reads that\\n    table with ``pyiceberg`` (no JVM), applying an optional row filter, column\\n    projection, and a hard row limit, and returns the result as a DataFrame.\\n    Tableflow tables are read-only from external engines: to change the data,\\n    publish to the source topic.\\n    \\\"\\\"\\\"\\n\\n    display_name = \\\"Confluent Tableflow Reader\\\"\\n    description = (\\n        \\\"Read a Kafka topic that Tableflow has materialized as an Apache Iceberg table (via the \\\"\\n        \\\"Tableflow Iceberg REST catalog) into a DataFrame, with a row filter, projection, and limit.\\\"\\n    )\\n    documentation: str = \\\"https://docs.langflow.org/bundles-confluent\\\"\\n    icon = \\\"Confluent\\\"\\n    name = \\\"ConfluentTableflowReader\\\"\\n    metadata = {\\\"keywords\\\": [\\\"confluent\\\", \\\"tableflow\\\", \\\"iceberg\\\", \\\"kafka\\\", \\\"lakehouse\\\", \\\"streamhouse\\\", \\\"ibm\\\"]}\\n\\n    inputs = [\\n        StrInput(\\n            name=\\\"region\\\",\\n            display_name=\\\"Cloud Region\\\",\\n            info=\\\"Confluent Cloud region of the Kafka cluster (for example us-east-1).\\\",\\n            value=DEFAULT_REGION,\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"organization_id\\\",\\n            display_name=\\\"Organization ID\\\",\\n            info=\\\"Confluent Cloud organization ID.\\\",\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"environment_id\\\",\\n            display_name=\\\"Environment ID\\\",\\n            info=\\\"Confluent Cloud environment ID (for example env-abc123).\\\",\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"kafka_cluster_id\\\",\\n            display_name=\\\"Kafka Cluster ID\\\",\\n            info=(\\n                \\\"Kafka cluster ID (for example lkc-abc123). Tableflow exposes it as the Iceberg warehouse \\\"\\n                \\\"and namespace.\\\"\\n            ),\\n            required=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"Tableflow API Key\\\",\\n            info=\\\"Tableflow API key (Iceberg REST catalog credential).\\\",\\n            required=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_secret\\\",\\n            display_name=\\\"Tableflow API Secret\\\",\\n            info=\\\"Secret paired with the Tableflow API key.\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"table_name\\\",\\n            display_name=\\\"Table (Topic)\\\",\\n            info=\\\"Tableflow table name -- the Kafka topic name. Leave empty and use the Tables output to list them.\\\",\\n            tool_mode=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"row_filter\\\",\\n            display_name=\\\"Row Filter\\\",\\n            info=\\\"Optional Iceberg row filter expression, for example status == 'shipped' AND amount > 10.\\\",\\n            tool_mode=True,\\n        ),\\n        StrInput(\\n            name=\\\"selected_fields\\\",\\n            display_name=\\\"Columns\\\",\\n            info=\\\"Optional comma-separated list of columns to return. Empty returns every column.\\\",\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"limit\\\",\\n            display_name=\\\"Row Limit\\\",\\n            info=f\\\"Maximum rows to return (capped at {MAX_LIMIT}).\\\",\\n            value=DEFAULT_LIMIT,\\n            range_spec={\\\"min\\\": 1, \\\"max\\\": MAX_LIMIT, \\\"step\\\": 1},\\n            tool_mode=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"storage_mode\\\",\\n            display_name=\\\"Storage\\\",\\n            options=STORAGE_OPTIONS,\\n            value=STORAGE_CONFLUENT_MANAGED,\\n            info=(\\n                \\\"confluent_managed: Confluent-provisioned storage (credentials vended by the catalog). \\\"\\n                \\\"byos: your own S3 bucket (provide the S3 fields).\\\"\\n            ),\\n            real_time_refresh=True,\\n            advanced=True,\\n        ),\\n        SecretStrInput(name=\\\"s3_access_key_id\\\", display_name=\\\"S3 Access Key ID\\\", advanced=True, show=False),\\n        SecretStrInput(name=\\\"s3_secret_access_key\\\", display_name=\\\"S3 Secret Access Key\\\", advanced=True, show=False),\\n        StrInput(name=\\\"s3_region\\\", display_name=\\\"S3 Region\\\", advanced=True, show=False),\\n        DropdownInput(\\n            name=\\\"access_delegation\\\",\\n            display_name=\\\"Access Delegation\\\",\\n            options=DELEGATION_OPTIONS,\\n            value=DELEGATION_VENDED,\\n            info=(\\n                \\\"Iceberg REST access-delegation mode requested from the catalog. Leave the default unless \\\"\\n                \\\"Confluent documents otherwise for your setup.\\\"\\n            ),\\n            advanced=True,\\n        ),\\n        StrInput(\\n            name=\\\"namespace\\\",\\n            display_name=\\\"Namespace Override\\\",\\n            info=\\\"Iceberg namespace holding the table. Defaults to the Kafka cluster ID.\\\",\\n            advanced=True,\\n        ),\\n        StrInput(\\n            name=\\\"snapshot_id\\\",\\n            display_name=\\\"Snapshot ID\\\",\\n            info=\\\"Optional Iceberg snapshot ID to read a specific point in time.\\\",\\n            advanced=True,\\n        ),\\n        StrInput(\\n            name=\\\"catalog_uri_override\\\",\\n            display_name=\\\"Catalog URI Override\\\",\\n            info=\\\"Full Iceberg REST catalog URI. Leave empty to build it from the region and IDs.\\\",\\n            advanced=True,\\n        ),\\n        StrInput(\\n            name=\\\"cloud\\\",\\n            display_name=\\\"Cloud Provider\\\",\\n            info=\\\"Cloud provider segment of the catalog host (aws, gcp, azure).\\\",\\n            value=DEFAULT_CLOUD,\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Result Table\\\", name=\\\"result_table\\\", method=\\\"read_table\\\"),\\n        Output(display_name=\\\"Tables\\\", name=\\\"tables\\\", method=\\\"list_tables\\\"),\\n    ]\\n\\n    # ------------------------------------------------------------ build cfg\\n    def update_build_config(self, build_config: dict, field_value: Any, field_name: str | None = None) -> dict:\\n        if field_name == \\\"storage_mode\\\":\\n            byos = field_value == STORAGE_BYOS\\n            for key in BYOS_FIELDS:\\n                if key in build_config:\\n                    build_config[key][\\\"show\\\"] = byos\\n                    build_config[key][\\\"advanced\\\"] = not byos\\n        return build_config\\n\\n    # ------------------------------------------------------------- helpers\\n    def catalog_uri(self) -> str:\\n        override = (getattr(self, \\\"catalog_uri_override\\\", \\\"\\\") or \\\"\\\").strip()\\n        if override:\\n            return ensure_url_allowed(override)\\n        uri = tableflow_catalog_url(\\n            self.region,\\n            self.organization_id,\\n            self.environment_id,\\n            cloud=getattr(self, \\\"cloud\\\", DEFAULT_CLOUD) or DEFAULT_CLOUD,\\n        )\\n        return ensure_url_allowed(uri)\\n\\n    def catalog_properties(self) -> dict[str, str]:\\n        \\\"\\\"\\\"Build the pyiceberg REST catalog properties for Tableflow.\\\"\\\"\\\"\\n        key = (self.api_key or \\\"\\\").strip()\\n        secret = (self.api_secret or \\\"\\\").strip()\\n        if not key or not secret:\\n            msg = \\\"Both the Tableflow API key and the API secret are required.\\\"\\n            raise ValueError(msg)\\n        cluster = require_token(self.kafka_cluster_id, \\\"Kafka cluster ID\\\")\\n        props: dict[str, str] = {\\n            \\\"type\\\": \\\"rest\\\",\\n            \\\"uri\\\": self.catalog_uri(),\\n            \\\"credential\\\": f\\\"{key}:{secret}\\\",\\n            \\\"warehouse\\\": cluster,\\n        }\\n        delegation = getattr(self, \\\"access_delegation\\\", DELEGATION_VENDED) or DELEGATION_VENDED\\n        if delegation != DELEGATION_NONE:\\n            props[\\\"header.X-Iceberg-Access-Delegation\\\"] = delegation\\n        if (getattr(self, \\\"storage_mode\\\", STORAGE_CONFLUENT_MANAGED) or STORAGE_CONFLUENT_MANAGED) == STORAGE_BYOS:\\n            access_key = (getattr(self, \\\"s3_access_key_id\\\", \\\"\\\") or \\\"\\\").strip()\\n            secret_key = (getattr(self, \\\"s3_secret_access_key\\\", \\\"\\\") or \\\"\\\").strip()\\n            s3_region = (getattr(self, \\\"s3_region\\\", \\\"\\\") or \\\"\\\").strip()\\n            if not access_key or not secret_key:\\n                msg = \\\"S3 access key ID and secret access key are required for bring-your-own-storage.\\\"\\n                raise ValueError(msg)\\n            props[\\\"s3.access-key-id\\\"] = access_key\\n            props[\\\"s3.secret-access-key\\\"] = secret_key\\n            if s3_region:\\n                props[\\\"s3.region\\\"] = s3_region\\n        return props\\n\\n    def _namespace(self) -> str:\\n        override = (getattr(self, \\\"namespace\\\", \\\"\\\") or \\\"\\\").strip()\\n        return override or require_token(self.kafka_cluster_id, \\\"Kafka cluster ID\\\")\\n\\n    def _selected_fields(self) -> tuple[str, ...]:\\n        raw = (getattr(self, \\\"selected_fields\\\", \\\"\\\") or \\\"\\\").strip()\\n        if not raw:\\n            return (\\\"*\\\",)\\n        fields = tuple(f.strip() for f in raw.split(\\\",\\\") if f.strip())\\n        return fields or (\\\"*\\\",)\\n\\n    def _limit(self) -> int:\\n        # Only a missing / blank limit falls back to the default: an explicit 0 from a tool\\n        # or API caller means \\\"as few as possible\\\", not \\\"give me DEFAULT_LIMIT rows\\\".\\n        raw = getattr(self, \\\"limit\\\", None)\\n        limit = DEFAULT_LIMIT if raw is None or raw == \\\"\\\" else int(raw)\\n        return max(1, min(limit, MAX_LIMIT))\\n\\n    @staticmethod\\n    def _load_catalog(properties: dict[str, str]):\\n        try:\\n            from pyiceberg.catalog import load_catalog\\n        except ImportError as exc:  # pragma: no cover - exercised on platforms without pyiceberg\\n            msg = \\\"pyiceberg is not installed. Install the lfx-confluent bundle with its dependencies.\\\"\\n            raise ImportError(msg) from exc\\n        return load_catalog(\\\"tableflow\\\", **properties)\\n\\n    # --------------------------------------------------------------- reads\\n    def _read_sync(self, properties: dict[str, str], namespace: str, table: str) -> Any:\\n        catalog = self._load_catalog(properties)\\n        # Tuple identifier, not \\\"<namespace>.<table>\\\": PyIceberg splits a string identifier\\n        # on \\\".\\\", and a Tableflow table is named after its Kafka topic, which routinely\\n        # contains dots (\\\"orders.v1\\\").\\n        iceberg_table = catalog.load_table((*namespace.split(\\\".\\\"), table))\\n        scan_kwargs: dict[str, Any] = {\\\"selected_fields\\\": self._selected_fields(), \\\"limit\\\": self._limit()}\\n        row_filter = (getattr(self, \\\"row_filter\\\", \\\"\\\") or \\\"\\\").strip()\\n        if row_filter:\\n            scan_kwargs[\\\"row_filter\\\"] = row_filter\\n        snapshot_id = (getattr(self, \\\"snapshot_id\\\", \\\"\\\") or \\\"\\\").strip()\\n        if snapshot_id:\\n            try:\\n                scan_kwargs[\\\"snapshot_id\\\"] = int(snapshot_id)\\n            except ValueError as exc:\\n                msg = f\\\"Snapshot ID must be an integer, got {snapshot_id!r}.\\\"\\n                raise ValueError(msg) from exc\\n        return iceberg_table.scan(**scan_kwargs).to_pandas()\\n\\n    def _list_sync(self, properties: dict[str, str], namespace: str) -> list[dict[str, str]]:\\n        catalog = self._load_catalog(properties)\\n        identifiers = catalog.list_tables(namespace)\\n        rows: list[dict[str, str]] = []\\n        for identifier in identifiers:\\n            parts = tuple(identifier) if isinstance(identifier, tuple | list) else (namespace, str(identifier))\\n            rows.append({\\\"namespace\\\": \\\".\\\".join(parts[:-1]), \\\"table\\\": parts[-1]})\\n        return rows\\n\\n    async def read_table(self) -> DataFrame:\\n        table = (getattr(self, \\\"table_name\\\", \\\"\\\") or \\\"\\\").strip()\\n        if not table:\\n            msg = \\\"Table (Topic) is required to read rows. Use the Tables output to list available tables.\\\"\\n            raise ValueError(msg)\\n        properties = self.catalog_properties()\\n        namespace = self._namespace()\\n        try:\\n            pandas_frame = await asyncio.to_thread(self._read_sync, properties, namespace, table)\\n        except ImportError:\\n            raise\\n        except ValueError:\\n            raise\\n        except Exception as exc:\\n            msg = f\\\"Tableflow read failed for {namespace}.{table}: {exc}\\\"\\n            raise ValueError(msg) from exc\\n        frame = DataFrame(pandas_frame)\\n        self.status = f\\\"Read {len(frame)} row(s) from {namespace}.{table}\\\"\\n        return frame\\n\\n    async def list_tables(self) -> Data:\\n        properties = self.catalog_properties()\\n        namespace = self._namespace()\\n        try:\\n            rows = await asyncio.to_thread(self._list_sync, properties, namespace)\\n        except ImportError:\\n            raise\\n        except ValueError:\\n            raise\\n        except Exception as exc:\\n            msg = f\\\"Tableflow catalog listing failed for namespace {namespace}: {exc}\\\"\\n            raise ValueError(msg) from exc\\n        self.status = f\\\"{len(rows)} table(s) in {namespace}\\\"\\n        return Data(data={\\\"namespace\\\": namespace, \\\"tables\\\": rows})\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/confluent/tests/test_tableflow_reader.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0e3feae734ce88a9c3d37ab1162977da8b68fd5b519ee04eb8f2322cf8225572\",\"content\":\"\\\"\\\"\\\"Unit tests for ``ConfluentTableflowReaderComponent`` (``lfx-confluent``).\\n\\n``pyiceberg.catalog.load_catalog`` is patched with a fake catalog so the\\ntests cover REST-catalog property construction (credential, warehouse,\\naccess delegation, BYOS storage keys), scan arguments (limit, filter,\\nprojection, snapshot), table listing, and error handling without network.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom unittest.mock import patch\\n\\nimport pandas as pd\\nimport pytest\\nfrom lfx.utils.ssrf_protection import SSRFProtectionError\\nfrom lfx_confluent import ConfluentTableflowReaderComponent\\nfrom lfx_confluent.components.confluent.tableflow_reader import BYOS_FIELDS\\n\\nLOAD_CATALOG_TARGET = \\\"pyiceberg.catalog.load_catalog\\\"\\n\\n\\nclass _FakeScan:\\n    def __init__(self, kwargs):\\n        self.kwargs = kwargs\\n\\n    def to_pandas(self):\\n        return pd.DataFrame([{\\\"id\\\": 1, \\\"status\\\": \\\"shipped\\\"}, {\\\"id\\\": 2, \\\"status\\\": \\\"shipped\\\"}])\\n\\n\\nclass _FakeTable:\\n    def __init__(self):\\n        self.scan_kwargs = None\\n\\n    def scan(self, **kwargs):\\n        self.scan_kwargs = kwargs\\n        return _FakeScan(kwargs)\\n\\n\\nclass _FakeCatalog:\\n    last: _FakeCatalog | None = None\\n\\n    def __init__(self, name, **properties):\\n        self.name = name\\n        self.properties = properties\\n        self.loaded = None\\n        self.table = _FakeTable()\\n        _FakeCatalog.last = self\\n\\n    def load_table(self, identifier):\\n        self.loaded = identifier\\n        return self.table\\n\\n    def list_tables(self, namespace):\\n        return [(namespace, \\\"orders\\\"), (namespace, \\\"payments\\\")]\\n\\n\\ndef _fake_load_catalog(name, **properties):\\n    return _FakeCatalog(name, **properties)\\n\\n\\n@pytest.fixture\\ndef component() -> ConfluentTableflowReaderComponent:\\n    c = ConfluentTableflowReaderComponent()\\n    c.region = \\\"us-east-1\\\"\\n    c.organization_id = \\\"org-1\\\"\\n    c.environment_id = \\\"env-abc\\\"\\n    c.kafka_cluster_id = \\\"lkc-xyz\\\"\\n    c.api_key = \\\"tf-key\\\"  # pragma: allowlist secret\\n    c.api_secret = \\\"tf-secret\\\"  # noqa: S105  # pragma: allowlist secret\\n    c.table_name = \\\"orders\\\"\\n    c.row_filter = \\\"\\\"\\n    c.selected_fields = \\\"\\\"\\n    c.limit = 1000\\n    c.storage_mode = \\\"confluent_managed\\\"\\n    c.s3_access_key_id = \\\"\\\"\\n    c.s3_secret_access_key = \\\"\\\"\\n    c.s3_region = \\\"\\\"\\n    c.access_delegation = \\\"vended-credentials\\\"\\n    c.namespace = \\\"\\\"\\n    c.snapshot_id = \\\"\\\"\\n    c.catalog_uri_override = \\\"\\\"\\n    c.cloud = \\\"aws\\\"\\n    return c\\n\\n\\ndef test_component_metadata():\\n    assert ConfluentTableflowReaderComponent.__name__ == \\\"ConfluentTableflowReaderComponent\\\"\\n    assert ConfluentTableflowReaderComponent.name == \\\"ConfluentTableflowReader\\\"\\n\\n\\ndef test_catalog_properties_for_managed_storage(component):\\n    props = component.catalog_properties()\\n    assert props == {\\n        \\\"type\\\": \\\"rest\\\",\\n        \\\"uri\\\": \\\"https://tableflow.us-east-1.aws.confluent.cloud/iceberg/catalog/organizations/org-1/environments/env-abc\\\",\\n        \\\"credential\\\": \\\"tf-key:tf-secret\\\",  # pragma: allowlist secret\\n        \\\"warehouse\\\": \\\"lkc-xyz\\\",\\n        \\\"header.X-Iceberg-Access-Delegation\\\": \\\"vended-credentials\\\",\\n    }\\n\\n\\ndef test_catalog_properties_for_byos_adds_s3_keys(component):\\n    component.storage_mode = \\\"byos\\\"\\n    component.access_delegation = \\\"none\\\"\\n    component.s3_access_key_id = \\\"AKIA\\\"  # pragma: allowlist secret\\n    component.s3_secret_access_key = \\\"S3SECRET\\\"  # noqa: S105  # pragma: allowlist secret\\n    component.s3_region = \\\"us-east-1\\\"\\n    props = component.catalog_properties()\\n    assert props[\\\"s3.access-key-id\\\"] == \\\"AKIA\\\"\\n    assert props[\\\"s3.secret-access-key\\\"] == \\\"S3SECRET\\\"  # pragma: allowlist secret\\n    assert props[\\\"s3.region\\\"] == \\\"us-east-1\\\"\\n    assert \\\"header.X-Iceberg-Access-Delegation\\\" not in props\\n\\n\\ndef test_catalog_properties_byos_requires_s3_credentials(component):\\n    component.storage_mode = \\\"byos\\\"\\n    with pytest.raises(ValueError, match=\\\"S3 access key ID\\\"):\\n        component.catalog_properties()\\n\\n\\ndef test_catalog_uri_override_is_ssrf_checked(component):\\n    component.catalog_uri_override = \\\"https://tableflow.example.com/iceberg/catalog/x\\\"\\n    assert component.catalog_uri() == \\\"https://tableflow.example.com/iceberg/catalog/x\\\"\\n    component.catalog_uri_override = \\\"http://10.0.0.5/iceberg\\\"\\n    with pytest.raises(SSRFProtectionError):\\n        component.catalog_uri()\\n\\n\\ndef test_update_build_config_toggles_byos_fields(component):\\n    build_config = {k: {\\\"show\\\": False, \\\"advanced\\\": True} for k in BYOS_FIELDS}\\n    out = component.update_build_config(dict(build_config), \\\"byos\\\", field_name=\\\"storage_mode\\\")\\n    assert all(out[k][\\\"show\\\"] for k in BYOS_FIELDS)\\n    out = component.update_build_config(dict(build_config), \\\"confluent_managed\\\", field_name=\\\"storage_mode\\\")\\n    assert not any(out[k][\\\"show\\\"] for k in BYOS_FIELDS)\\n\\n\\nasync def test_read_table_scans_with_filter_projection_limit_and_snapshot(component):\\n    component.row_filter = \\\"status == 'shipped'\\\"\\n    component.selected_fields = \\\"id, status\\\"\\n    component.limit = 50\\n    component.snapshot_id = \\\"12345\\\"\\n    with patch(LOAD_CATALOG_TARGET, side_effect=_fake_load_catalog):\\n        frame = await component.read_table()\\n    catalog = _FakeCatalog.last\\n    assert catalog.name == \\\"tableflow\\\"\\n    assert catalog.loaded == (\\\"lkc-xyz\\\", \\\"orders\\\")\\n    assert catalog.table.scan_kwargs == {\\n        \\\"selected_fields\\\": (\\\"id\\\", \\\"status\\\"),\\n        \\\"limit\\\": 50,\\n        \\\"row_filter\\\": \\\"status == 'shipped'\\\",\\n        \\\"snapshot_id\\\": 12345,\\n    }\\n    assert frame.to_dict(orient=\\\"records\\\") == [{\\\"id\\\": 1, \\\"status\\\": \\\"shipped\\\"}, {\\\"id\\\": 2, \\\"status\\\": \\\"shipped\\\"}]\\n\\n\\nasync def test_read_table_uses_namespace_override_and_default_projection(component):\\n    component.namespace = \\\"custom_ns\\\"\\n    with patch(LOAD_CATALOG_TARGET, side_effect=_fake_load_catalog):\\n        await component.read_table()\\n    assert _FakeCatalog.last.loaded == (\\\"custom_ns\\\", \\\"orders\\\")\\n    assert _FakeCatalog.last.table.scan_kwargs[\\\"selected_fields\\\"] == (\\\"*\\\",)\\n\\n\\nasync def test_read_table_keeps_dots_in_the_table_name(component):\\n    \\\"\\\"\\\"A Tableflow table is named after its Kafka topic, and topics routinely contain dots.\\n\\n    A string identifier would be split by PyIceberg into extra namespace levels.\\n    \\\"\\\"\\\"\\n    component.table_name = \\\"orders.v1\\\"\\n    with patch(LOAD_CATALOG_TARGET, side_effect=_fake_load_catalog):\\n        await component.read_table()\\n    assert _FakeCatalog.last.loaded == (\\\"lkc-xyz\\\", \\\"orders.v1\\\")\\n\\n\\nasync def test_read_table_requires_table_name(component):\\n    component.table_name = \\\"\\\"\\n    with pytest.raises(ValueError, match=\\\"Table \\\\\\\\(Topic\\\\\\\\) is required\\\"):\\n        await component.read_table()\\n\\n\\nasync def test_read_table_rejects_non_integer_snapshot(component):\\n    component.snapshot_id = \\\"abc\\\"\\n    with patch(LOAD_CATALOG_TARGET, side_effect=_fake_load_catalog), pytest.raises(ValueError, match=\\\"Snapshot ID\\\"):\\n        await component.read_table()\\n\\n\\nasync def test_read_table_wraps_catalog_errors(component):\\n    def _boom(_name, **_properties):\\n        msg = \\\"catalog unreachable\\\"\\n        raise RuntimeError(msg)\\n\\n    with patch(LOAD_CATALOG_TARGET, side_effect=_boom), pytest.raises(ValueError, match=\\\"Tableflow read failed\\\"):\\n        await component.read_table()\\n\\n\\nasync def test_list_tables_returns_namespace_and_tables(component):\\n    with patch(LOAD_CATALOG_TARGET, side_effect=_fake_load_catalog):\\n        data = await component.list_tables()\\n    assert data.data[\\\"namespace\\\"] == \\\"lkc-xyz\\\"\\n    assert data.data[\\\"tables\\\"] == [\\n        {\\\"namespace\\\": \\\"lkc-xyz\\\", \\\"table\\\": \\\"orders\\\"},\\n        {\\\"namespace\\\": \\\"lkc-xyz\\\", \\\"table\\\": \\\"payments\\\"},\\n    ]\\n\\n\\ndef test_limit_is_clamped(component):\\n    component.limit = 10_000_000\\n    assert component._limit() == 100_000\\n    component.limit = 0\\n    assert component._limit() == 1  # an explicit zero clamps to the minimum, not the default\\n    component.limit = None\\n    assert component._limit() == 1000  # only a missing value falls back to the default\\n\\n\\ndef test_selected_fields_parsing(component):\\n    component.selected_fields = \\\" a , b ,,\\\"\\n    assert component._selected_fields() == (\\\"a\\\", \\\"b\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/src/lfx_datastax/components/cassandra/cassandra_graph.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cf0fd99378cd92f4cb570b2f1bae29d55cf33b0ab586b8c826518411fd20a01c\",\"content\":\"\\\"\\\"\\\"Cassandra graph-vector-store component.\\\"\\\"\\\"\\n\\nfrom uuid import UUID\\n\\nfrom langchain_community.graph_vectorstores import CassandraGraphVectorStore\\n\\nfrom lfx.base.vectorstores.model import LCVectorStoreComponent, check_cached_vector_store\\nfrom lfx.helpers.data import docs_to_data\\nfrom lfx.inputs.inputs import DictInput, FloatInput\\nfrom lfx.io import (\\n    DropdownInput,\\n    HandleInput,\\n    IntInput,\\n    MessageTextInput,\\n    SecretStrInput,\\n)\\nfrom lfx.schema.data import Data\\n\\n\\nclass CassandraGraphVectorStoreComponent(LCVectorStoreComponent):\\n    display_name = \\\"Cassandra Graph\\\"\\n    description = \\\"Cassandra Graph Vector Store\\\"\\n    name = \\\"CassandraGraph\\\"\\n    icon = \\\"Cassandra\\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\\"database_ref\\\",\\n            display_name=\\\"Contact Points / Astra Database ID\\\",\\n            info=\\\"Contact points for the database (or Astra DB database ID)\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"username\\\", display_name=\\\"Username\\\", info=\\\"Username for the database (leave empty for Astra DB).\\\"\\n        ),\\n        SecretStrInput(\\n            name=\\\"token\\\",\\n            display_name=\\\"Password / Astra DB Token\\\",\\n            info=\\\"User password for the database (or Astra DB token).\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"keyspace\\\",\\n            display_name=\\\"Keyspace\\\",\\n            info=\\\"Table Keyspace (or Astra DB namespace).\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"table_name\\\",\\n            display_name=\\\"Table Name\\\",\\n            info=\\\"The name of the table (or Astra DB collection) where vectors will be stored.\\\",\\n            required=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"setup_mode\\\",\\n            display_name=\\\"Setup Mode\\\",\\n            info=\\\"Configuration mode for setting up the Cassandra table, with options like 'Sync' or 'Off'.\\\",\\n            options=[\\\"Sync\\\", \\\"Off\\\"],\\n            value=\\\"Sync\\\",\\n            advanced=True,\\n        ),\\n        DictInput(\\n            name=\\\"cluster_kwargs\\\",\\n            display_name=\\\"Cluster arguments\\\",\\n            info=\\\"Optional dictionary of additional keyword arguments for the Cassandra cluster.\\\",\\n            advanced=True,\\n            list=True,\\n        ),\\n        *LCVectorStoreComponent.inputs,\\n        HandleInput(name=\\\"embedding\\\", display_name=\\\"Embedding\\\", input_types=[\\\"Embeddings\\\"]),\\n        IntInput(\\n            name=\\\"number_of_results\\\",\\n            display_name=\\\"Number of Results\\\",\\n            info=\\\"Number of results to return.\\\",\\n            value=4,\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"search_type\\\",\\n            display_name=\\\"Search Type\\\",\\n            info=\\\"Search type to use\\\",\\n            options=[\\n                \\\"Traversal\\\",\\n                \\\"MMR traversal\\\",\\n                \\\"Similarity\\\",\\n                \\\"Similarity with score threshold\\\",\\n                \\\"MMR (Max Marginal Relevance)\\\",\\n            ],\\n            value=\\\"Traversal\\\",\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"depth\\\",\\n            display_name=\\\"Depth of traversal\\\",\\n            info=\\\"The maximum depth of edges to traverse. (when using 'Traversal' or 'MMR traversal')\\\",\\n            value=1,\\n            advanced=True,\\n        ),\\n        FloatInput(\\n            name=\\\"search_score_threshold\\\",\\n            display_name=\\\"Search Score Threshold\\\",\\n            info=\\\"Minimum similarity score threshold for search results. \\\"\\n            \\\"(when using 'Similarity with score threshold')\\\",\\n            value=0,\\n            advanced=True,\\n        ),\\n        DictInput(\\n            name=\\\"search_filter\\\",\\n            display_name=\\\"Search Metadata Filter\\\",\\n            info=\\\"Optional dictionary of filters to apply to the search query.\\\",\\n            advanced=True,\\n            list=True,\\n        ),\\n    ]\\n\\n    @check_cached_vector_store\\n    def build_vector_store(self) -> CassandraGraphVectorStore:\\n        try:\\n            import cassio\\n            from langchain_community.utilities.cassandra import SetupMode\\n        except ImportError as e:\\n            msg = \\\"Could not import cassio integration package. Please install it with `pip install cassio`.\\\"\\n            raise ImportError(msg) from e\\n\\n        database_ref = self.database_ref\\n\\n        try:\\n            UUID(self.database_ref)\\n            is_astra = True\\n        except ValueError:\\n            is_astra = False\\n            if \\\",\\\" in self.database_ref:\\n                # use a copy because we can't change the type of the parameter\\n                database_ref = self.database_ref.split(\\\",\\\")\\n\\n        if is_astra:\\n            cassio.init(\\n                database_id=database_ref,\\n                token=self.token,\\n                cluster_kwargs=self.cluster_kwargs,\\n            )\\n        else:\\n            cassio.init(\\n                contact_points=database_ref,\\n                username=self.username,\\n                password=self.token,\\n                cluster_kwargs=self.cluster_kwargs,\\n            )\\n\\n        self.ingest_data = self._prepare_ingest_data()\\n\\n        documents = []\\n\\n        for _input in self.ingest_data or []:\\n            if isinstance(_input, Data):\\n                documents.append(_input.to_lc_document())\\n            else:\\n                documents.append(_input)\\n\\n        setup_mode = SetupMode.OFF if self.setup_mode == \\\"Off\\\" else SetupMode.SYNC\\n\\n        if documents:\\n            self.log(f\\\"Adding {len(documents)} documents to the Vector Store.\\\")\\n            store = CassandraGraphVectorStore.from_documents(\\n                documents=documents,\\n                embedding=self.embedding,\\n                node_table=self.table_name,\\n                keyspace=self.keyspace,\\n            )\\n        else:\\n            self.log(\\\"No documents to add to the Vector Store.\\\")\\n            store = CassandraGraphVectorStore(\\n                embedding=self.embedding,\\n                node_table=self.table_name,\\n                keyspace=self.keyspace,\\n                setup_mode=setup_mode,\\n            )\\n        return store\\n\\n    def _map_search_type(self) -> str:\\n        if self.search_type == \\\"Similarity\\\":\\n            return \\\"similarity\\\"\\n        if self.search_type == \\\"Similarity with score threshold\\\":\\n            return \\\"similarity_score_threshold\\\"\\n        if self.search_type == \\\"MMR (Max Marginal Relevance)\\\":\\n            return \\\"mmr\\\"\\n        if self.search_type == \\\"MMR Traversal\\\":\\n            return \\\"mmr_traversal\\\"\\n        return \\\"traversal\\\"\\n\\n    def search_documents(self) -> list[Data]:\\n        vector_store = self.build_vector_store()\\n\\n        self.log(f\\\"Search input: {self.search_query}\\\")\\n        self.log(f\\\"Search type: {self.search_type}\\\")\\n        self.log(f\\\"Number of results: {self.number_of_results}\\\")\\n\\n        if self.search_query and isinstance(self.search_query, str) and self.search_query.strip():\\n            try:\\n                search_type = self._map_search_type()\\n                search_args = self._build_search_args()\\n\\n                self.log(f\\\"Search args: {search_args}\\\")\\n\\n                docs = vector_store.search(query=self.search_query, search_type=search_type, **search_args)\\n            except KeyError as e:\\n                if \\\"content\\\" in str(e):\\n                    msg = (\\n                        \\\"You should ingest data through Langflow (or LangChain) to query it in Langflow. \\\"\\n                        \\\"Your collection does not contain a field name 'content'.\\\"\\n                    )\\n                    raise ValueError(msg) from e\\n                raise\\n\\n            self.log(f\\\"Retrieved documents: {len(docs)}\\\")\\n\\n            data = docs_to_data(docs)\\n            self.status = data\\n            return data\\n        return []\\n\\n    def _build_search_args(self):\\n        args = {\\n            \\\"k\\\": self.number_of_results,\\n            \\\"score_threshold\\\": self.search_score_threshold,\\n            \\\"depth\\\": self.depth,\\n        }\\n\\n        if self.search_filter:\\n            clean_filter = {k: v for k, v in self.search_filter.items() if k and v}\\n            if len(clean_filter) > 0:\\n                args[\\\"filter\\\"] = clean_filter\\n        return args\\n\\n    def get_retriever_kwargs(self):\\n        search_args = self._build_search_args()\\n        return {\\n            \\\"search_type\\\": self._map_search_type(),\\n            \\\"search_kwargs\\\": search_args,\\n        }\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/src/lfx_datastax/components/datastax/astradb_graph.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d5cab50b3cb2e4d403824c3efab5a2de801dbd9733ab3e002f6024cb1222274a\",\"content\":\"import orjson\\n\\nfrom lfx_datastax.base.astradb_base import AstraDBBaseComponent\\nfrom lfx.base.vectorstores.model import (\\n    LCVectorStoreComponent,\\n    check_cached_vector_store,\\n)\\nfrom lfx.helpers.data import docs_to_data\\nfrom lfx.inputs.inputs import (\\n    DictInput,\\n    DropdownInput,\\n    FloatInput,\\n    IntInput,\\n    StrInput,\\n)\\nfrom lfx.schema.data import Data\\n\\n\\nclass AstraDBGraphVectorStoreComponent(AstraDBBaseComponent, LCVectorStoreComponent):\\n    display_name: str = \\\"Astra DB Graph\\\"\\n    description: str = \\\"Implementation of Graph Vector Store using Astra DB\\\"\\n    name = \\\"AstraDBGraph\\\"\\n    documentation: str = \\\"https://docs.langflow.org/bundles-datastax\\\"\\n    icon: str = \\\"AstraDB\\\"\\n    legacy: bool = True\\n    replacement = [\\\"datastax.GraphRAG\\\"]\\n\\n    inputs = [\\n        *AstraDBBaseComponent.inputs,\\n        *LCVectorStoreComponent.inputs,\\n        StrInput(\\n            name=\\\"metadata_incoming_links_key\\\",\\n            display_name=\\\"Metadata incoming links key\\\",\\n            info=\\\"Metadata key used for incoming links.\\\",\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"number_of_results\\\",\\n            display_name=\\\"Number of Results\\\",\\n            info=\\\"Number of results to return.\\\",\\n            advanced=True,\\n            value=4,\\n        ),\\n        DropdownInput(\\n            name=\\\"search_type\\\",\\n            display_name=\\\"Search Type\\\",\\n            info=\\\"Search type to use\\\",\\n            options=[\\n                \\\"Similarity\\\",\\n                \\\"Similarity with score threshold\\\",\\n                \\\"MMR (Max Marginal Relevance)\\\",\\n                \\\"Graph Traversal\\\",\\n                \\\"MMR (Max Marginal Relevance) Graph Traversal\\\",\\n            ],\\n            value=\\\"MMR (Max Marginal Relevance) Graph Traversal\\\",\\n            advanced=True,\\n        ),\\n        FloatInput(\\n            name=\\\"search_score_threshold\\\",\\n            display_name=\\\"Search Score Threshold\\\",\\n            info=\\\"Minimum similarity score threshold for search results. \\\"\\n            \\\"(when using 'Similarity with score threshold')\\\",\\n            value=0,\\n            advanced=True,\\n        ),\\n        DictInput(\\n            name=\\\"search_filter\\\",\\n            display_name=\\\"Search Metadata Filter\\\",\\n            info=\\\"Optional dictionary of filters to apply to the search query.\\\",\\n            advanced=True,\\n            is_list=True,\\n        ),\\n    ]\\n\\n    @check_cached_vector_store\\n    def build_vector_store(self):\\n        try:\\n            from langchain_astradb import AstraDBGraphVectorStore\\n            from langchain_astradb.utils.astradb import SetupMode\\n        except ImportError as e:\\n            msg = (\\n                \\\"Could not import langchain Astra DB integration package. \\\"\\n                \\\"Please install it with `pip install langchain-astradb`.\\\"\\n            )\\n            raise ImportError(msg) from e\\n\\n        try:\\n            if not self.setup_mode:\\n                self.setup_mode = self._inputs[\\\"setup_mode\\\"].options[0]\\n\\n            setup_mode_value = SetupMode[self.setup_mode.upper()]\\n        except KeyError as e:\\n            msg = f\\\"Invalid setup mode: {self.setup_mode}\\\"\\n            raise ValueError(msg) from e\\n\\n        try:\\n            self.log(f\\\"Initializing Graph Vector Store {self.collection_name}\\\")\\n\\n            vector_store = AstraDBGraphVectorStore(\\n                embedding=self.embedding_model,\\n                collection_name=self.collection_name,\\n                metadata_incoming_links_key=self.metadata_incoming_links_key or \\\"incoming_links\\\",\\n                token=self.token,\\n                api_endpoint=self.get_api_endpoint(),\\n                namespace=self.get_keyspace(),\\n                environment=self.environment,\\n                metric=self.metric or None,\\n                batch_size=self.batch_size or None,\\n                bulk_insert_batch_concurrency=self.bulk_insert_batch_concurrency or None,\\n                bulk_insert_overwrite_concurrency=self.bulk_insert_overwrite_concurrency or None,\\n                bulk_delete_concurrency=self.bulk_delete_concurrency or None,\\n                setup_mode=setup_mode_value,\\n                pre_delete_collection=self.pre_delete_collection,\\n                metadata_indexing_include=[s for s in self.metadata_indexing_include if s] or None,\\n                metadata_indexing_exclude=[s for s in self.metadata_indexing_exclude if s] or None,\\n                collection_indexing_policy=orjson.loads(self.collection_indexing_policy.encode(\\\"utf-8\\\"))\\n                if self.collection_indexing_policy\\n                else None,\\n            )\\n        except Exception as e:\\n            msg = f\\\"Error initializing AstraDBGraphVectorStore: {e}\\\"\\n            raise ValueError(msg) from e\\n\\n        self.log(f\\\"Vector Store initialized: {vector_store.astra_env.collection_name}\\\")\\n        self._add_documents_to_vector_store(vector_store)\\n\\n        return vector_store\\n\\n    def _add_documents_to_vector_store(self, vector_store) -> None:\\n        self.ingest_data = self._prepare_ingest_data()\\n\\n        documents = []\\n        for _input in self.ingest_data or []:\\n            if isinstance(_input, Data):\\n                documents.append(_input.to_lc_document())\\n            else:\\n                msg = \\\"Vector Store Inputs must be Data objects.\\\"\\n                raise TypeError(msg)\\n\\n        if documents:\\n            self.log(f\\\"Adding {len(documents)} documents to the Vector Store.\\\")\\n            try:\\n                vector_store.add_documents(documents)\\n            except Exception as e:\\n                msg = f\\\"Error adding documents to AstraDBGraphVectorStore: {e}\\\"\\n                raise ValueError(msg) from e\\n        else:\\n            self.log(\\\"No documents to add to the Vector Store.\\\")\\n\\n    def _map_search_type(self) -> str:\\n        match self.search_type:\\n            case \\\"Similarity\\\":\\n                return \\\"similarity\\\"\\n            case \\\"Similarity with score threshold\\\":\\n                return \\\"similarity_score_threshold\\\"\\n            case \\\"MMR (Max Marginal Relevance)\\\":\\n                return \\\"mmr\\\"\\n            case \\\"Graph Traversal\\\":\\n                return \\\"traversal\\\"\\n            case \\\"MMR (Max Marginal Relevance) Graph Traversal\\\":\\n                return \\\"mmr_traversal\\\"\\n            case _:\\n                return \\\"similarity\\\"\\n\\n    def _build_search_args(self):\\n        args = {\\n            \\\"k\\\": self.number_of_results,\\n            \\\"score_threshold\\\": self.search_score_threshold,\\n        }\\n\\n        if self.search_filter:\\n            clean_filter = {k: v for k, v in self.search_filter.items() if k and v}\\n            if len(clean_filter) > 0:\\n                args[\\\"filter\\\"] = clean_filter\\n        return args\\n\\n    def search_documents(self, vector_store=None) -> list[Data]:\\n        if not vector_store:\\n            vector_store = self.build_vector_store()\\n\\n        self.log(\\\"Searching for documents in AstraDBGraphVectorStore.\\\")\\n        self.log(f\\\"Search query: {self.search_query}\\\")\\n        self.log(f\\\"Search type: {self.search_type}\\\")\\n        self.log(f\\\"Number of results: {self.number_of_results}\\\")\\n\\n        if self.search_query and isinstance(self.search_query, str) and self.search_query.strip():\\n            try:\\n                search_type = self._map_search_type()\\n                search_args = self._build_search_args()\\n\\n                docs = vector_store.search(query=self.search_query, search_type=search_type, **search_args)\\n\\n                # Drop links from the metadata. At this point the links don't add any value for building the\\n                # context and haven't been restored to json which causes the conversion to fail.\\n                self.log(\\\"Removing links from metadata.\\\")\\n                for doc in docs:\\n                    if \\\"links\\\" in doc.metadata:\\n                        doc.metadata.pop(\\\"links\\\")\\n\\n            except Exception as e:\\n                msg = f\\\"Error performing search in AstraDBGraphVectorStore: {e}\\\"\\n                raise ValueError(msg) from e\\n\\n            self.log(f\\\"Retrieved documents: {len(docs)}\\\")\\n\\n            data = docs_to_data(docs)\\n\\n            self.log(f\\\"Converted documents to data: {len(data)}\\\")\\n\\n            self.status = data\\n            return data\\n        self.log(\\\"No search input provided. Skipping search.\\\")\\n        return []\\n\\n    def get_retriever_kwargs(self):\\n        search_args = self._build_search_args()\\n        return {\\n            \\\"search_type\\\": self._map_search_type(),\\n            \\\"search_kwargs\\\": search_args,\\n        }\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/src/lfx_datastax/components/datastax/graph_rag.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"56df35fd350f3f9f4921c169e45f5e247aad187b949a79c31b1c74251c11f5c6\",\"content\":\"import inspect\\nfrom abc import ABC\\n\\nimport graph_retriever.strategies as strategies_module\\nfrom langchain_graph_retriever import GraphRetriever\\n\\nfrom lfx.base.vectorstores.model import LCVectorStoreComponent\\nfrom lfx.helpers.data import docs_to_data\\nfrom lfx.inputs.inputs import (\\n    DropdownInput,\\n    HandleInput,\\n    MultilineInput,\\n    NestedDictInput,\\n    StrInput,\\n)\\nfrom lfx.schema.data import Data\\n\\n\\ndef traversal_strategies() -> list[str]:\\n    \\\"\\\"\\\"Retrieves a list of class names from the strategies_module.\\n\\n    This function uses the `inspect` module to get all the class members\\n    from the `strategies_module` and returns their names as a list of strings.\\n\\n    Returns:\\n        list[str]: A list of strategy class names.\\n    \\\"\\\"\\\"\\n    classes = inspect.getmembers(strategies_module, inspect.isclass)\\n    return [name for name, cls in classes if ABC not in cls.__bases__]\\n\\n\\nclass GraphRAGComponent(LCVectorStoreComponent):\\n    \\\"\\\"\\\"GraphRAGComponent is a component for performing Graph RAG traversal in a vector store.\\n\\n    Attributes:\\n        display_name (str): The display name of the component.\\n        description (str): A brief description of the component.\\n        name (str): The name of the component.\\n        icon (str): The icon representing the component.\\n        inputs (list): A list of input configurations for the component.\\n\\n    Methods:\\n        _build_search_args():\\n            Builds the arguments required for the search operation.\\n        search_documents() -> list[Data]:\\n            Searches for documents using the specified strategy, edge definition, and query.\\n        _edge_definition_from_input() -> tuple:\\n            Processes the edge definition input and returns it as a tuple.\\n    \\\"\\\"\\\"\\n\\n    display_name: str = \\\"Graph RAG\\\"\\n    description: str = \\\"Graph RAG traversal for vector store.\\\"\\n    name = \\\"GraphRAG\\\"\\n    icon: str = \\\"AstraDB\\\"\\n\\n    inputs = [\\n        HandleInput(\\n            name=\\\"embedding_model\\\",\\n            display_name=\\\"Embedding Model\\\",\\n            input_types=[\\\"Embeddings\\\"],\\n            info=\\\"Specify the Embedding Model. Not required for Astra Vectorize collections.\\\",\\n            required=False,\\n        ),\\n        HandleInput(\\n            name=\\\"vector_store\\\",\\n            display_name=\\\"Vector Store Connection\\\",\\n            input_types=[\\\"VectorStore\\\"],\\n            info=\\\"Connection to Vector Store.\\\",\\n        ),\\n        StrInput(\\n            name=\\\"edge_definition\\\",\\n            display_name=\\\"Edge Definition\\\",\\n            info=\\\"Edge definition for the graph traversal.\\\",\\n        ),\\n        DropdownInput(\\n            name=\\\"strategy\\\",\\n            display_name=\\\"Traversal Strategies\\\",\\n            options=traversal_strategies(),\\n        ),\\n        MultilineInput(\\n            name=\\\"search_query\\\",\\n            display_name=\\\"Search Query\\\",\\n            tool_mode=True,\\n        ),\\n        NestedDictInput(\\n            name=\\\"graphrag_strategy_kwargs\\\",\\n            display_name=\\\"Strategy Parameters\\\",\\n            info=(\\n                \\\"Optional dictionary of additional parameters for the retrieval strategy. \\\"\\n                \\\"Please see https://datastax.github.io/graph-rag/reference/graph_retriever/strategies/ for details.\\\"\\n            ),\\n            advanced=True,\\n        ),\\n    ]\\n\\n    def search_documents(self) -> list[Data]:\\n        \\\"\\\"\\\"Searches for documents using the graph retriever based on the selected strategy, edge definition, and query.\\n\\n        Returns:\\n            list[Data]: A list of retrieved documents.\\n\\n        Raises:\\n            AttributeError: If there is an issue with attribute access.\\n            TypeError: If there is a type mismatch.\\n            ValueError: If there is a value error.\\n        \\\"\\\"\\\"\\n        additional_params = self.graphrag_strategy_kwargs or {}\\n\\n        # Invoke the graph retriever based on the selected strategy, edge definition, and query\\n        strategy_class = getattr(strategies_module, self.strategy)\\n        retriever = GraphRetriever(\\n            store=self.vector_store,\\n            edges=[self._evaluate_edge_definition_input()],\\n            strategy=strategy_class(**additional_params),\\n        )\\n\\n        return docs_to_data(retriever.invoke(self.search_query))\\n\\n    def _edge_definition_from_input(self) -> tuple:\\n        \\\"\\\"\\\"Generates the edge definition from the input data.\\n\\n        Returns:\\n            tuple: A tuple representing the edge definition.\\n        \\\"\\\"\\\"\\n        values = self.edge_definition.split(\\\",\\\")\\n        values = [value.strip() for value in values]\\n\\n        return tuple(values)\\n\\n    def _evaluate_edge_definition_input(self) -> tuple:\\n        from graph_retriever.edges.metadata import Id\\n\\n        \\\"\\\"\\\"Evaluates the edge definition, converting any function calls from strings.\\n\\n        Args:\\n            edge_definition (tuple): The edge definition to evaluate.\\n\\n        Returns:\\n            tuple: The evaluated edge definition.\\n        \\\"\\\"\\\"\\n        evaluated_values = []\\n        for value in self._edge_definition_from_input():\\n            if value == \\\"Id()\\\":\\n                evaluated_values.append(Id())  # Evaluate Id() as a function call\\n            else:\\n                evaluated_values.append(value)\\n        return tuple(evaluated_values)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/tests/test_graph_rag_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b9d8d09375799f3cc30d3546ee2f5a288c6703814e3b8552ae13d1d9ac888fa0\",\"content\":\"import random\\n\\nimport pytest\\nfrom langchain_core.documents import Document\\nfrom langchain_core.embeddings import Embeddings\\nfrom langchain_core.vectorstores.in_memory import InMemoryVectorStore\\nfrom lfx_datastax.components.datastax.graph_rag import GraphRAGComponent\\n\\n\\nclass _DeterministicEmbeddings(Embeddings):\\n    def __init__(self, size: int):\\n        self.size = size\\n\\n    def _embed(self) -> list[float]:\\n        return [1.0] * self.size\\n\\n    def embed_documents(self, texts: list[str]) -> list[list[float]]:\\n        return [self._embed() for _ in texts]\\n\\n    def embed_query(self, text: str) -> list[float]:\\n        return self._embed()\\n\\n\\nclass TestGraphRAGComponent:\\n    \\\"\\\"\\\"Test suite for the GraphRAGComponent class, focusing on graph traversal and retrieval functionality.\\n\\n    Fixtures:\\n        component_class: Returns the GraphRAGComponent class to be tested.\\n        animals: Provides a list of Document objects representing various animals with metadata.\\n        embedding: Provides a FakeEmbeddings instance with a specified size.\\n        vector_store: Initializes an InMemoryVectorStore with the provided animals and embedding.\\n        file_names_mapping: Returns an empty list since this component doesn't have version-specific files.\\n        default_kwargs: Returns an empty dictionary since this component doesn't have any default arguments.\\n\\n    Test Cases:\\n        test_graphrag: Tests the search_documents method of the GraphRAGComponent class by setting attributes and\\n        verifying the number of results returned.\\n    \\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return GraphRAGComponent\\n\\n    @pytest.fixture\\n    def animals(self, n: int = 20, match_prob: float = 0.3) -> list[Document]:\\n        \\\"\\\"\\\"Animals dataset for testing.\\n\\n        Generate a list of animal-related document objects with random metadata.\\n\\n        Parameters:\\n            n (int): Number of documents to generate.\\n            match_prob (float): Probability of sharing metadata across documents.\\n\\n        Returns:\\n            List[Document]: A list of generated Document objects.\\n        \\\"\\\"\\\"\\n        random.seed(42)\\n\\n        # Define possible attributes for animals\\n        animal_types = [\\\"mammal\\\", \\\"bird\\\", \\\"reptile\\\", \\\"insect\\\"]\\n        habitats = [\\\"savanna\\\", \\\"marine\\\", \\\"wetlands\\\", \\\"forest\\\", \\\"desert\\\"]\\n        diets = [\\\"carnivorous\\\", \\\"herbivorous\\\", \\\"omnivorous\\\"]\\n        origins = [\\\"north america\\\", \\\"south america\\\", \\\"africa\\\", \\\"asia\\\", \\\"australia\\\"]\\n\\n        shared_metadata = {}  # Common metadata that may be shared across documents\\n\\n        def update_metadata(meta: dict) -> dict:\\n            \\\"\\\"\\\"Modify metadata based on predefined conditions and probability.\\\"\\\"\\\"\\n            if random.random() < match_prob:  # noqa: S311\\n                meta.update(shared_metadata)  # Apply shared metadata\\n            elif meta[\\\"type\\\"] == \\\"mammal\\\":\\n                meta[\\\"habitat\\\"] = random.choice(habitats)  # noqa: S311\\n            elif meta[\\\"type\\\"] == \\\"reptile\\\":\\n                meta[\\\"diet\\\"] = random.choice(diets)  # noqa: S311\\n            elif meta[\\\"type\\\"] == \\\"insect\\\":\\n                meta[\\\"origin\\\"] = random.choice(origins)  # noqa: S311\\n            return meta\\n\\n        # Generate and return a list of documents\\n        return [\\n            Document(\\n                id=f\\\"animal-{idx}\\\",\\n                page_content=f\\\"animal document {idx}\\\",\\n                metadata=update_metadata(\\n                    {\\n                        \\\"type\\\": random.choice(animal_types),  # noqa: S311\\n                        \\\"number_of_legs\\\": random.choice([0, 2, 4, 6, 8]),  # noqa: S311\\n                        \\\"keywords\\\": [f\\\"keyword-{idx}-{n}\\\" for n in range(random.randint(2, 5))],  # noqa: S311\\n                        # Add optional tags with 30% probability\\n                        **(\\n                            {\\n                                \\\"tags\\\": [\\n                                    {\\\"a\\\": random.randint(1, 10), \\\"b\\\": random.randint(1, 10)}  # noqa: S311\\n                                    for _ in range(random.randint(1, 2))  # noqa: S311\\n                                ]\\n                            }\\n                            if random.random() < 0.3  # noqa: S311\\n                            else {}\\n                        ),\\n                        # Add nested metadata with 20% probability\\n                        **({\\\"nested\\\": {\\\"a\\\": random.randint(1, 10)}} if random.random() < 0.2 else {}),  # noqa: S311\\n                    }\\n                ),\\n            )\\n            for idx in range(n)\\n        ]\\n\\n    @pytest.fixture\\n    def embedding(self):\\n        return _DeterministicEmbeddings(size=8)\\n\\n    @pytest.fixture\\n    def vector_store(self, animals: list[Document], embedding: _DeterministicEmbeddings) -> InMemoryVectorStore:\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        store = InMemoryVectorStore(embedding=embedding)\\n        store.add_documents(animals)\\n        return store\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return an empty dictionary since this component doesn't have any default arguments.\\\"\\\"\\\"\\n        return {\\\"k\\\": 10, \\\"start_k\\\": 3, \\\"max_depth\\\": 2}\\n\\n    def test_graphrag(\\n        self,\\n        component_class: GraphRAGComponent,\\n        embedding: _DeterministicEmbeddings,\\n        vector_store: InMemoryVectorStore,\\n        default_kwargs,\\n    ):\\n        \\\"\\\"\\\"Test GraphRAGComponent's document search functionality.\\n\\n        This test verifies that the component correctly retrieves documents using the\\n        provided embedding model, vector store, and search query.\\n\\n        Args:\\n            component_class (GraphRAGComponent): The component class to test.\\n            embedding (FakeEmbeddings): The embedding model for the component.\\n            vector_store (InMemoryVectorStore): The vector store used in retrieval.\\n            default_kwargs (dict): Default keyword arguments for the retrieval strategy.\\n\\n        Returns:\\n            None: The test asserts that 10 search results are returned.\\n        \\\"\\\"\\\"\\n        component = component_class()\\n\\n        component.set_attributes(\\n            {\\n                \\\"embedding_model\\\": embedding,\\n                \\\"vector_store\\\": vector_store,\\n                \\\"edge_definition\\\": \\\"type, type\\\",\\n                \\\"strategy\\\": \\\"Eager\\\",\\n                \\\"search_query\\\": \\\"information environment technology\\\",\\n                \\\"graphrag_strategy_kwargs\\\": default_kwargs,\\n            }\\n        )\\n\\n        results = component.search_documents()\\n\\n        # Quantity of documents\\n        assert len(results) == 10\\n\\n        # Ensures all the k-start_k documents returned via traversal have the same metadata as the\\n        # ones returned via the similarity search\\n        assert {doc.data[\\\"type\\\"] for doc in results if doc.data[\\\"_depth\\\"] == 0} == {\\n            doc.data[\\\"type\\\"] for doc in results if doc.data[\\\"_depth\\\"] >= 1\\n        }\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/composio/canvas_composio.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6510d212a720f6af599ec4ca84eaaec7c83dce5b0f0f305983c6a88edd6b0180\",\"content\":\"from lfx.base.composio.composio_base import ComposioBaseComponent\\n\\n\\nclass ComposioCanvasAPIComponent(ComposioBaseComponent):\\n    display_name: str = \\\"Canvas\\\"\\n    icon = \\\"Canvas\\\"\\n    documentation: str = \\\"https://docs.composio.dev\\\"\\n    app_name = \\\"canvas\\\"\\n\\n    def set_default_tools(self):\\n        \\\"\\\"\\\"Set the default tools for Canvaas component.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/scrapegraph/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a4de1f205c71991f2ee844804614afd83be2acd8ca8fc18b40c902ff1a71461b\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.utils.lazy_import import import_mod\\n\\nif TYPE_CHECKING:\\n    from .scrapegraph_markdownify_api import ScrapeGraphMarkdownifyApi\\n    from .scrapegraph_search_api import ScrapeGraphSearchApi\\n    from .scrapegraph_smart_scraper_api import ScrapeGraphSmartScraperApi\\n\\n_dynamic_imports = {\\n    \\\"ScrapeGraphMarkdownifyApi\\\": \\\"scrapegraph_markdownify_api\\\",\\n    \\\"ScrapeGraphSearchApi\\\": \\\"scrapegraph_search_api\\\",\\n    \\\"ScrapeGraphSmartScraperApi\\\": \\\"scrapegraph_smart_scraper_api\\\",\\n}\\n\\n__all__ = [\\n    \\\"ScrapeGraphMarkdownifyApi\\\",\\n    \\\"ScrapeGraphSearchApi\\\",\\n    \\\"ScrapeGraphSmartScraperApi\\\",\\n]\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    \\\"\\\"\\\"Lazily import scrapegraph components on attribute access.\\\"\\\"\\\"\\n    if attr_name not in _dynamic_imports:\\n        msg = f\\\"module '{__name__}' has no attribute '{attr_name}'\\\"\\n        raise AttributeError(msg)\\n    try:\\n        result = import_mod(attr_name, _dynamic_imports[attr_name], __spec__.parent)\\n    except (ModuleNotFoundError, ImportError, AttributeError) as e:\\n        msg = f\\\"Could not import '{attr_name}' from '{__name__}': {e}\\\"\\n        raise AttributeError(msg) from e\\n    globals()[attr_name] = result\\n    return result\\n\\n\\ndef __dir__() -> list[str]:\\n    return list(__all__)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/scrapegraph/scrapegraph_markdownify_api.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c17524dbca7aec1e80f70a99194d98bb3324309174bc7e5fed0d1b0ed8cd7b26\",\"content\":\"from lfx.custom.custom_component.component import Component\\nfrom lfx.io import (\\n    MessageTextInput,\\n    Output,\\n    SecretStrInput,\\n)\\nfrom lfx.schema.data import Data\\n\\n\\nclass ScrapeGraphMarkdownifyApi(Component):\\n    display_name: str = \\\"ScrapeGraph Markdownify API\\\"\\n    description: str = \\\"Given a URL, it will return the markdownified content of the website.\\\"\\n    name = \\\"ScrapeGraphMarkdownifyApi\\\"\\n\\n    output_types: list[str] = [\\\"Document\\\"]\\n    documentation: str = \\\"https://docs.scrapegraphai.com/services/markdownify\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"ScrapeGraph API Key\\\",\\n            required=True,\\n            password=True,\\n            info=\\\"The API key to use ScrapeGraph API.\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"url\\\",\\n            display_name=\\\"URL\\\",\\n            tool_mode=True,\\n            info=\\\"The URL to markdownify.\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"JSON\\\", name=\\\"data\\\", method=\\\"scrape\\\"),\\n    ]\\n\\n    def scrape(self) -> list[Data]:\\n        try:\\n            from scrapegraph_py import Client\\n            from scrapegraph_py.logger import sgai_logger\\n        except ImportError as e:\\n            msg = \\\"Could not import scrapegraph-py package. Please install it with `pip install scrapegraph-py`.\\\"\\n            raise ImportError(msg) from e\\n\\n        # Set logging level\\n        sgai_logger.set_logging(level=\\\"INFO\\\")\\n\\n        # Initialize the client with API key\\n        sgai_client = Client(api_key=self.api_key)\\n\\n        try:\\n            # Markdownify request\\n            response = sgai_client.markdownify(\\n                website_url=self.url,\\n            )\\n\\n            # Close the client\\n            sgai_client.close()\\n\\n            return Data(data=response)\\n        except Exception:\\n            sgai_client.close()\\n            raise\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/scrapegraph/scrapegraph_search_api.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4caa0e09ea8533871a2878584162297c21e42223c9c8bfa0c38f98846c838bc0\",\"content\":\"from lfx.custom.custom_component.component import Component\\nfrom lfx.io import (\\n    MessageTextInput,\\n    Output,\\n    SecretStrInput,\\n)\\nfrom lfx.schema.data import Data\\n\\n\\nclass ScrapeGraphSearchApi(Component):\\n    display_name: str = \\\"ScrapeGraph Search API\\\"\\n    description: str = \\\"Given a search prompt, it will return search results using ScrapeGraph's search functionality.\\\"\\n    name = \\\"ScrapeGraphSearchApi\\\"\\n\\n    documentation: str = \\\"https://docs.scrapegraphai.com/services/searchscraper\\\"\\n    icon = \\\"ScrapeGraph\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"ScrapeGraph API Key\\\",\\n            required=True,\\n            password=True,\\n            info=\\\"The API key to use ScrapeGraph API.\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"user_prompt\\\",\\n            display_name=\\\"Search Prompt\\\",\\n            tool_mode=True,\\n            info=\\\"The search prompt to use.\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"JSON\\\", name=\\\"data\\\", method=\\\"search\\\"),\\n    ]\\n\\n    def search(self) -> list[Data]:\\n        try:\\n            from scrapegraph_py import Client\\n            from scrapegraph_py.logger import sgai_logger\\n        except ImportError as e:\\n            msg = \\\"Could not import scrapegraph-py package. Please install it with `pip install scrapegraph-py`.\\\"\\n            raise ImportError(msg) from e\\n\\n        # Set logging level\\n        sgai_logger.set_logging(level=\\\"INFO\\\")\\n\\n        # Initialize the client with API key\\n        sgai_client = Client(api_key=self.api_key)\\n\\n        try:\\n            # SearchScraper request\\n            response = sgai_client.searchscraper(\\n                user_prompt=self.user_prompt,\\n            )\\n\\n            # Close the client\\n            sgai_client.close()\\n\\n            return Data(data=response)\\n        except Exception:\\n            sgai_client.close()\\n            raise\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/scrapegraph/scrapegraph_smart_scraper_api.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"229446ce1e374f3fd67a5eff13857756e95eadc60d4a503055b2b6dad6fe3b73\",\"content\":\"from lfx.custom.custom_component.component import Component\\nfrom lfx.io import (\\n    MessageTextInput,\\n    Output,\\n    SecretStrInput,\\n)\\nfrom lfx.schema.data import Data\\n\\n\\nclass ScrapeGraphSmartScraperApi(Component):\\n    display_name: str = \\\"ScrapeGraph Smart Scraper API\\\"\\n    description: str = \\\"Given a URL, it will return the structured data of the website.\\\"\\n    name = \\\"ScrapeGraphSmartScraperApi\\\"\\n\\n    output_types: list[str] = [\\\"Document\\\"]\\n    documentation: str = \\\"https://docs.scrapegraphai.com/services/smartscraper\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"ScrapeGraph API Key\\\",\\n            required=True,\\n            password=True,\\n            info=\\\"The API key to use ScrapeGraph API.\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"url\\\",\\n            display_name=\\\"URL\\\",\\n            tool_mode=True,\\n            info=\\\"The URL to scrape.\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"prompt\\\",\\n            display_name=\\\"Prompt\\\",\\n            tool_mode=True,\\n            info=\\\"The prompt to use for the smart scraper.\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"JSON\\\", name=\\\"data\\\", method=\\\"scrape\\\"),\\n    ]\\n\\n    def scrape(self) -> list[Data]:\\n        try:\\n            from scrapegraph_py import Client\\n            from scrapegraph_py.logger import sgai_logger\\n        except ImportError as e:\\n            msg = \\\"Could not import scrapegraph-py package. Please install it with `pip install scrapegraph-py`.\\\"\\n            raise ImportError(msg) from e\\n\\n        # Set logging level\\n        sgai_logger.set_logging(level=\\\"INFO\\\")\\n\\n        # Initialize the client with API key\\n        sgai_client = Client(api_key=self.api_key)\\n\\n        try:\\n            # SmartScraper request\\n            response = sgai_client.smartscraper(\\n                website_url=self.url,\\n                user_prompt=self.prompt,\\n            )\\n\\n            # Close the client\\n            sgai_client.close()\\n\\n            return Data(data=response)\\n        except Exception:\\n            sgai_client.close()\\n            raise\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/tests/test_memory_flow_id_scoping.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"be58750b4e03b6ca545a7d128684fbaf4702cd0fd8796575623f6e04dbd5f357\",\"content\":\"\\\"\\\"\\\"Tests that MemoryComponent scopes chat history retrieval by flow_id.\\n\\nRegression test for https://github.com/langflow-ai/langflow/issues/13059\\n\\nBefore the fix, ``MemoryComponent.retrieve_messages`` called\\n``aget_messages`` without ``flow_id``. Because the Langflow playground assigns\\ndefault session names (e.g. \\\"New Session 0\\\") that are not unique across flows,\\nthis caused chat history from Flow A to leak into Flow B whenever both used\\nthe same session name. The Agent component is affected because it delegates\\nits chat-history fetch to this method.\\n\\nThese tests assert that the call into ``aget_messages`` is now scoped by the\\ngraph's ``flow_id`` (coerced to ``UUID``) so flows can no longer cross-read\\neach other's history.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, patch\\nfrom uuid import UUID, uuid4\\n\\nimport pytest\\nfrom lfx.components.models_and_agents.memory import (\\n    MAX_CHAT_HISTORY_FETCH_LIMIT,\\n    MemoryComponent,\\n    _coerce_flow_id_to_uuid,\\n    aget_agent_chat_history,\\n)\\n\\n\\ndef _build_component(\\n    flow_id: str | UUID | None,\\n    session_id: str = \\\"session-shared\\\",\\n) -> MemoryComponent:\\n    component = MemoryComponent()\\n    component.set(session_id=session_id, n_messages=10, order=\\\"Ascending\\\")\\n    # ``Component.graph`` is a read-only property -> ``self._vertex.graph``,\\n    # so we wire the underlying ``_vertex`` instead of assigning ``graph``.\\n    component._vertex = SimpleNamespace(graph=SimpleNamespace(flow_id=flow_id, session_id=session_id))\\n    return component\\n\\n\\nclass TestCoerceFlowIdToUuid:\\n    \\\"\\\"\\\"Validate the small UUID-coercion helper used by retrieve_messages.\\\"\\\"\\\"\\n\\n    def test_returns_none_for_missing_values(self):\\n        assert _coerce_flow_id_to_uuid(None) is None\\n        assert _coerce_flow_id_to_uuid(\\\"\\\") is None\\n\\n    def test_passes_uuid_through_unchanged(self):\\n        value = uuid4()\\n        assert _coerce_flow_id_to_uuid(value) is value\\n\\n    def test_parses_uuid_string(self):\\n        raw = \\\"11111111-1111-1111-1111-111111111111\\\"\\n        assert _coerce_flow_id_to_uuid(raw) == UUID(raw)\\n\\n    def test_returns_none_for_invalid_string_and_does_not_raise(self):\\n        # Synthetic/test flow IDs may not be UUIDs; we must degrade gracefully.\\n        assert _coerce_flow_id_to_uuid(\\\"not-a-uuid\\\") is None\\n\\n    def test_invalid_flow_id_emits_structured_error_log(self):\\n        \\\"\\\"\\\"Fallback to unscoped retrieval is a privacy regression \u2014 alert on it.\\n\\n        See PR #13087 review I3: this path re-enables the cross-flow leak\\n        that issue #13059 closed. The log call uses ``error`` level + a\\n        structured ``event`` tag so observability pipelines can alert.\\n        \\\"\\\"\\\"\\n        with patch(\\\"lfx.components.models_and_agents.memory.logger\\\") as mock_logger:\\n            _coerce_flow_id_to_uuid(\\\"not-a-uuid\\\")\\n\\n        mock_logger.error.assert_called_once()\\n        call = mock_logger.error.call_args\\n        assert \\\"memory_flow_id_unscoped\\\" in call.args[0]\\n        assert call.kwargs.get(\\\"extra\\\", {}).get(\\\"event\\\") == \\\"memory_flow_id_unscoped\\\"\\n\\n\\nclass TestRetrieveMessagesPassesFlowId:\\n    \\\"\\\"\\\"The leak fix: retrieve_messages must pass flow_id to aget_messages.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_passes_graph_flow_id_as_uuid(self):\\n        flow_id_str = \\\"22222222-2222-2222-2222-222222222222\\\"\\n        component = _build_component(flow_id=flow_id_str)\\n\\n        with patch(\\n            \\\"lfx.components.models_and_agents.memory.aget_messages\\\",\\n            new=AsyncMock(return_value=[]),\\n        ) as mock_get:\\n            await component.retrieve_messages()\\n\\n        mock_get.assert_awaited_once()\\n        kwargs = mock_get.await_args.kwargs\\n        assert kwargs[\\\"flow_id\\\"] == UUID(flow_id_str), (\\n            \\\"retrieve_messages must scope by flow_id so default session names \\\"\\n            \\\"do not leak chat history across flows (issue #13059).\\\"\\n        )\\n        assert kwargs[\\\"session_id\\\"] == \\\"session-shared\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_isolates_two_flows_sharing_a_session_name(self):\\n        \\\"\\\"\\\"Reproduction of the leak: same session name, different flow_ids.\\n\\n        Flow A and Flow B both use session ``New Session 0``. With the fix in\\n        place, the call into ``aget_messages`` is scoped by each flow's UUID,\\n        so the database query can no longer return cross-flow rows.\\n        \\\"\\\"\\\"\\n        flow_a = \\\"aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa\\\"\\n        flow_b = \\\"bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb\\\"\\n        shared_session = \\\"New Session 0\\\"\\n\\n        with patch(\\n            \\\"lfx.components.models_and_agents.memory.aget_messages\\\",\\n            new=AsyncMock(return_value=[]),\\n        ) as mock_get:\\n            await _build_component(flow_id=flow_a, session_id=shared_session).retrieve_messages()\\n            await _build_component(flow_id=flow_b, session_id=shared_session).retrieve_messages()\\n\\n        assert mock_get.await_count == 2\\n        first_call_kwargs = mock_get.await_args_list[0].kwargs\\n        second_call_kwargs = mock_get.await_args_list[1].kwargs\\n        assert first_call_kwargs[\\\"flow_id\\\"] == UUID(flow_a)\\n        assert second_call_kwargs[\\\"flow_id\\\"] == UUID(flow_b)\\n        # Same session name reaches the DB layer, but flow_id now disambiguates.\\n        assert first_call_kwargs[\\\"session_id\\\"] == shared_session\\n        assert second_call_kwargs[\\\"session_id\\\"] == shared_session\\n\\n    @pytest.mark.asyncio\\n    async def test_falls_back_to_none_when_flow_id_missing(self):\\n        component = _build_component(flow_id=None)\\n\\n        with patch(\\n            \\\"lfx.components.models_and_agents.memory.aget_messages\\\",\\n            new=AsyncMock(return_value=[]),\\n        ) as mock_get:\\n            await component.retrieve_messages()\\n\\n        assert mock_get.await_args.kwargs[\\\"flow_id\\\"] is None\\n\\n    @pytest.mark.asyncio\\n    async def test_falls_back_to_none_when_flow_id_is_not_a_uuid(self):\\n        \\\"\\\"\\\"Tests with synthetic graph IDs must not crash retrieval.\\\"\\\"\\\"\\n        component = _build_component(flow_id=\\\"not-a-uuid\\\")\\n\\n        with patch(\\n            \\\"lfx.components.models_and_agents.memory.aget_messages\\\",\\n            new=AsyncMock(return_value=[]),\\n        ) as mock_get:\\n            await component.retrieve_messages()\\n\\n        assert mock_get.await_args.kwargs[\\\"flow_id\\\"] is None\\n\\n    @pytest.mark.asyncio\\n    async def test_external_memory_path_is_untouched(self):\\n        \\\"\\\"\\\"External Memory providers have no concept of flow_id; do not pass it.\\\"\\\"\\\"\\n\\n        class _FakeExternalMemory:\\n            session_id: str | None = None\\n            context_id: str | None = None\\n\\n            async def aget_messages(self):\\n                return []\\n\\n        component = _build_component(flow_id=\\\"33333333-3333-3333-3333-333333333333\\\")\\n        component.set(memory=_FakeExternalMemory())\\n\\n        with patch(\\n            \\\"lfx.components.models_and_agents.memory.aget_messages\\\",\\n            new=AsyncMock(return_value=[]),\\n        ) as mock_get:\\n            await component.retrieve_messages()\\n\\n        mock_get.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    async def test_fetches_desc_and_reverses_for_ascending_order(self):\\n        \\\"\\\"\\\"PR #13087 review I2: avoid the >10k row ASC slice trap.\\n\\n        Querying ``order=ASC, limit=MAX`` then slicing ``[-n:]`` would return\\n        the chronological FIRST window on huge sessions. We query DESC with\\n        the actual limit and reverse to the user-selected order, so the slice\\n        is always the genuine most-recent messages.\\n        \\\"\\\"\\\"\\n        component = _build_component(flow_id=\\\"22222222-2222-2222-2222-222222222222\\\")\\n        # MemoryComponent ``order`` defaults to Ascending in _build_component.\\n        # The mock returns DESC-ordered data (most recent first), as the DB would.\\n        desc_rows = [SimpleNamespace(id=f\\\"msg-{i}\\\") for i in (4, 3, 2, 1, 0)]\\n        with patch(\\n            \\\"lfx.components.models_and_agents.memory.aget_messages\\\",\\n            new=AsyncMock(return_value=desc_rows),\\n        ) as mock_get:\\n            result = await component.retrieve_messages()\\n\\n        assert mock_get.await_args.kwargs[\\\"order\\\"] == \\\"DESC\\\"\\n        assert mock_get.await_args.kwargs[\\\"limit\\\"] == 10  # _build_component sets n_messages=10\\n        assert [m.id for m in result] == [\\\"msg-0\\\", \\\"msg-1\\\", \\\"msg-2\\\", \\\"msg-3\\\", \\\"msg-4\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_descending_order_passthrough_keeps_desc_view(self):\\n        component = _build_component(flow_id=\\\"22222222-2222-2222-2222-222222222222\\\")\\n        component.set(order=\\\"Descending\\\")\\n        desc_rows = [SimpleNamespace(id=f\\\"msg-{i}\\\") for i in (4, 3, 2, 1, 0)]\\n        with patch(\\n            \\\"lfx.components.models_and_agents.memory.aget_messages\\\",\\n            new=AsyncMock(return_value=desc_rows),\\n        ):\\n            result = await component.retrieve_messages()\\n\\n        assert [m.id for m in result] == [\\\"msg-4\\\", \\\"msg-3\\\", \\\"msg-2\\\", \\\"msg-1\\\", \\\"msg-0\\\"]\\n\\n\\nclass TestStoreMessagePassesFlowId:\\n    \\\"\\\"\\\"PR #13087 review I1: write/read flow_id handling must be symmetric.\\n\\n    The original PR protected ``retrieve_messages`` against ``self.graph``\\n    raising on ad-hoc instantiation but left ``store_message`` calling\\n    ``self.graph.flow_id`` directly \u2014 so a custom subclass or integration\\n    test would crash on the write path before reaching the safe read path.\\n    Both paths now go through ``_coerce_flow_id_to_uuid(_safe_graph_flow_id(self))``.\\n    \\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_store_passes_coerced_flow_id_to_astore_and_aget(self):\\n        flow_id_str = \\\"22222222-2222-2222-2222-222222222222\\\"\\n        component = _build_component(flow_id=flow_id_str)\\n        component.set(mode=\\\"Store\\\", message=\\\"hi\\\", sender=\\\"User\\\", sender_name=\\\"Tester\\\")\\n\\n        stored = SimpleNamespace(id=\\\"stored-1\\\")\\n        with (\\n            patch(\\n                \\\"lfx.components.models_and_agents.memory.astore_message\\\",\\n                new=AsyncMock(return_value=None),\\n            ) as mock_store,\\n            patch(\\n                \\\"lfx.components.models_and_agents.memory.aget_messages\\\",\\n                new=AsyncMock(return_value=[stored]),\\n            ) as mock_get,\\n        ):\\n            await component.store_message()\\n\\n        assert mock_store.await_args.kwargs[\\\"flow_id\\\"] == UUID(flow_id_str)\\n        assert mock_get.await_args.kwargs[\\\"flow_id\\\"] == UUID(flow_id_str)\\n        # Symmetric scope: the same coerced UUID is used for both calls.\\n        assert mock_store.await_args.kwargs[\\\"flow_id\\\"] == mock_get.await_args.kwargs[\\\"flow_id\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_store_does_not_crash_without_vertex(self):\\n        \\\"\\\"\\\"When _vertex is None, ``self.graph`` raises AttributeError.\\n\\n        Pre-fix, ``store_message`` accessed ``self.graph.flow_id`` directly\\n        and crashed before reaching the safe read path. Now both paths\\n        share the same defensive lookup.\\n        \\\"\\\"\\\"\\n        component = MemoryComponent()\\n        component.set(\\n            session_id=\\\"s\\\",\\n            n_messages=10,\\n            order=\\\"Ascending\\\",\\n            mode=\\\"Store\\\",\\n            message=\\\"hi\\\",\\n            sender=\\\"User\\\",\\n            sender_name=\\\"Tester\\\",\\n        )\\n        # No _vertex assigned \u2014 ``self.graph`` will raise AttributeError.\\n        stored = SimpleNamespace(id=\\\"stored-1\\\")\\n        with (\\n            patch(\\n                \\\"lfx.components.models_and_agents.memory.astore_message\\\",\\n                new=AsyncMock(return_value=None),\\n            ) as mock_store,\\n            patch(\\n                \\\"lfx.components.models_and_agents.memory.aget_messages\\\",\\n                new=AsyncMock(return_value=[stored]),\\n            ),\\n        ):\\n            await component.store_message()\\n\\n        assert mock_store.await_args.kwargs[\\\"flow_id\\\"] is None\\n\\n\\nclass TestAgetAgentChatHistoryHelper:\\n    \\\"\\\"\\\"The shared helper centralizes the agent-side memory contract.\\n\\n    Both ``AgentComponent`` and ``CugaComponent`` route through this helper,\\n    so testing the helper directly covers their common behavior.\\n    \\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_passes_flow_id_as_uuid(self):\\n        flow_id_str = \\\"44444444-4444-4444-4444-444444444444\\\"\\n\\n        with patch(\\n            \\\"lfx.components.models_and_agents.memory.aget_messages\\\",\\n            new=AsyncMock(return_value=[]),\\n        ) as mock_get:\\n            await aget_agent_chat_history(\\n                session_id=\\\"New Session 0\\\",\\n                flow_id=flow_id_str,\\n                context_id=\\\"\\\",\\n                n_messages=10,\\n            )\\n\\n        mock_get.assert_awaited_once()\\n        kwargs = mock_get.await_args.kwargs\\n        assert kwargs[\\\"flow_id\\\"] == UUID(flow_id_str), \\\"aget_agent_chat_history must scope by flow_id (issue #13059).\\\"\\n        assert kwargs[\\\"session_id\\\"] == \\\"New Session 0\\\"\\n        # PR #13087 review I2: query DESC + limit=n_messages so sessions\\n        # exceeding MAX_CHAT_HISTORY_FETCH_LIMIT still get the real tail.\\n        assert kwargs[\\\"order\\\"] == \\\"DESC\\\"\\n        assert kwargs[\\\"limit\\\"] == 10\\n\\n    @pytest.mark.asyncio\\n    async def test_n_messages_zero_short_circuits_without_querying(self):\\n        \\\"\\\"\\\"Regression: ``n_messages == 0`` means \\\"memory disabled\\\".\\n\\n        Before this short-circuit, ``messages[-0:]`` returned the full\\n        bounded result, so users who set the field to 0 to disable chat\\n        memory unexpectedly got full history back.\\n        \\\"\\\"\\\"\\n        with patch(\\n            \\\"lfx.components.models_and_agents.memory.aget_messages\\\",\\n            new=AsyncMock(return_value=[SimpleNamespace(id=f\\\"msg-{i}\\\") for i in range(5)]),\\n        ) as mock_get:\\n            result = await aget_agent_chat_history(\\n                session_id=\\\"s\\\",\\n                flow_id=\\\"66666666-6666-6666-6666-666666666666\\\",\\n                n_messages=0,\\n            )\\n\\n        assert result == []\\n        mock_get.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    async def test_slices_to_n_messages_most_recent(self):\\n        # DB returns DESC (most recent first); helper reverses to ASC.\\n        desc_rows = [SimpleNamespace(id=f\\\"msg-{i}\\\") for i in (4, 3)]\\n\\n        with patch(\\n            \\\"lfx.components.models_and_agents.memory.aget_messages\\\",\\n            new=AsyncMock(return_value=desc_rows),\\n        ) as mock_get:\\n            result = await aget_agent_chat_history(\\n                session_id=\\\"s\\\",\\n                flow_id=\\\"77777777-7777-7777-7777-777777777777\\\",\\n                n_messages=2,\\n            )\\n\\n        assert mock_get.await_args.kwargs[\\\"limit\\\"] == 2\\n        assert mock_get.await_args.kwargs[\\\"order\\\"] == \\\"DESC\\\"\\n        assert [m.id for m in result] == [\\\"msg-3\\\", \\\"msg-4\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_missing_n_messages_returns_all_fetched(self):\\n        # DB returns DESC; helper reverses for the agent prompt.\\n        desc_rows = [SimpleNamespace(id=f\\\"msg-{i}\\\") for i in (2, 1, 0)]\\n\\n        with patch(\\n            \\\"lfx.components.models_and_agents.memory.aget_messages\\\",\\n            new=AsyncMock(return_value=desc_rows),\\n        ) as mock_get:\\n            result = await aget_agent_chat_history(\\n                session_id=\\\"s\\\",\\n                flow_id=None,\\n                n_messages=None,\\n            )\\n\\n        # No explicit limit \u21d2 fall back to MAX_CHAT_HISTORY_FETCH_LIMIT.\\n        assert mock_get.await_args.kwargs[\\\"limit\\\"] == MAX_CHAT_HISTORY_FETCH_LIMIT\\n        assert [m.id for m in result] == [\\\"msg-0\\\", \\\"msg-1\\\", \\\"msg-2\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_invalid_flow_id_falls_back_to_unscoped_query(self):\\n        with patch(\\n            \\\"lfx.components.models_and_agents.memory.aget_messages\\\",\\n            new=AsyncMock(return_value=[]),\\n        ) as mock_get:\\n            await aget_agent_chat_history(\\n                session_id=\\\"s\\\",\\n                flow_id=\\\"not-a-uuid\\\",\\n                n_messages=10,\\n            )\\n\\n        assert mock_get.await_args.kwargs[\\\"flow_id\\\"] is None\\n\\n    @pytest.mark.asyncio\\n    async def test_logs_warning_when_unbounded_fetch_hits_ceiling(self):\\n        \\\"\\\"\\\"PR #13087 review I2: surface the silent-truncation case.\\n\\n        When the caller did not pass ``n_messages`` and the DB returned\\n        exactly ``MAX_CHAT_HISTORY_FETCH_LIMIT`` rows, older history may\\n        have been silently dropped. Emit a structured warning so on-call\\n        has something to grep when a user reports forgotten context.\\n        \\\"\\\"\\\"\\n        # Simulate the DB returning exactly the ceiling \u2014 older rows truncated.\\n        rows = [SimpleNamespace(id=f\\\"msg-{i}\\\") for i in range(MAX_CHAT_HISTORY_FETCH_LIMIT)]\\n        with (\\n            patch(\\\"lfx.components.models_and_agents.memory.logger\\\") as mock_logger,\\n            patch(\\n                \\\"lfx.components.models_and_agents.memory.aget_messages\\\",\\n                new=AsyncMock(return_value=rows),\\n            ),\\n        ):\\n            await aget_agent_chat_history(\\n                session_id=\\\"s\\\",\\n                flow_id=None,\\n                n_messages=None,\\n            )\\n\\n        mock_logger.warning.assert_called_once()\\n        call = mock_logger.warning.call_args\\n        assert \\\"memory_chat_history_limit_reached\\\" in call.args[0]\\n        assert call.kwargs.get(\\\"extra\\\", {}).get(\\\"event\\\") == \\\"memory_chat_history_limit_reached\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_explicit_n_messages_at_ceiling_does_not_warn(self):\\n        \\\"\\\"\\\"The ceiling warning is for ``n_messages=None`` only \u2014 explicit limits are honored.\\\"\\\"\\\"\\n        rows = [SimpleNamespace(id=f\\\"msg-{i}\\\") for i in range(MAX_CHAT_HISTORY_FETCH_LIMIT)]\\n        with (\\n            patch(\\\"lfx.components.models_and_agents.memory.logger\\\") as mock_logger,\\n            patch(\\n                \\\"lfx.components.models_and_agents.memory.aget_messages\\\",\\n                new=AsyncMock(return_value=rows),\\n            ),\\n        ):\\n            await aget_agent_chat_history(\\n                session_id=\\\"s\\\",\\n                flow_id=None,\\n                n_messages=MAX_CHAT_HISTORY_FETCH_LIMIT,\\n            )\\n\\n        mock_logger.warning.assert_not_called()\\n\\n\\nclass TestAgentGetMemoryDataIntegration:\\n    \\\"\\\"\\\"End-to-end checks at the AgentComponent boundary.\\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _make_agent(flow_id: str | UUID | None, session_id: str = \\\"New Session 0\\\", n_messages: int = 10):\\n        from lfx.components.models_and_agents.agent import AgentComponent\\n\\n        agent = AgentComponent.__new__(AgentComponent)\\n        agent._vertex = SimpleNamespace(graph=SimpleNamespace(flow_id=flow_id, session_id=session_id))\\n        agent.context_id = \\\"\\\"\\n        agent.n_messages = n_messages\\n        agent.input_value = SimpleNamespace(id=\\\"current-input-id\\\")\\n        return agent\\n\\n    @pytest.mark.asyncio\\n    async def test_agent_routes_through_helper_with_flow_id(self):\\n        flow_id_str = \\\"88888888-8888-8888-8888-888888888888\\\"\\n        agent = self._make_agent(flow_id=flow_id_str)\\n\\n        with patch(\\n            \\\"lfx.components.models_and_agents.agent.aget_agent_chat_history\\\",\\n            new=AsyncMock(return_value=[]),\\n        ) as mock_helper:\\n            await agent.get_memory_data()\\n\\n        mock_helper.assert_awaited_once()\\n        kwargs = mock_helper.await_args.kwargs\\n        assert kwargs[\\\"flow_id\\\"] == flow_id_str\\n        assert kwargs[\\\"session_id\\\"] == \\\"New Session 0\\\"\\n        assert kwargs[\\\"n_messages\\\"] == 10\\n\\n    @pytest.mark.asyncio\\n    async def test_agent_filters_out_current_input_message(self):\\n        \\\"\\\"\\\"The agent must not echo the current input back as chat history.\\\"\\\"\\\"\\n        agent = self._make_agent(flow_id=\\\"55555555-5555-5555-5555-555555555555\\\")\\n\\n        current = SimpleNamespace(id=\\\"current-input-id\\\", text=\\\"ping\\\")\\n        old = SimpleNamespace(id=\\\"old-msg-id\\\", text=\\\"earlier\\\")\\n\\n        with patch(\\n            \\\"lfx.components.models_and_agents.agent.aget_agent_chat_history\\\",\\n            new=AsyncMock(return_value=[old, current]),\\n        ):\\n            result = await agent.get_memory_data()\\n\\n        assert [m.id for m in result] == [\\\"old-msg-id\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_agent_n_messages_zero_disables_memory(self):\\n        \\\"\\\"\\\"Regression: setting \\\"Number of Chat History Messages\\\" to 0 must disable memory.\\\"\\\"\\\"\\n        agent = self._make_agent(flow_id=\\\"99999999-9999-9999-9999-999999999999\\\", n_messages=0)\\n\\n        # Patch the underlying DB query so a regression resurfaces as a real call.\\n        with patch(\\n            \\\"lfx.components.models_and_agents.memory.aget_messages\\\",\\n            new=AsyncMock(return_value=[SimpleNamespace(id=f\\\"msg-{i}\\\") for i in range(5)]),\\n        ) as mock_get:\\n            result = await agent.get_memory_data()\\n\\n        assert result == []\\n        mock_get.assert_not_awaited()\\n\\n\\nclass TestCugaGetMemoryDataIntegration:\\n    \\\"\\\"\\\"The Cuga agent had the same leak pattern; verify the fix reaches it too.\\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _make_cuga(flow_id: str | UUID | None, session_id: str = \\\"shared\\\", n_messages: int = 10):\\n        pytest.importorskip(\\\"lfx_bundles\\\")\\n\\n        try:\\n            from lfx_bundles.cuga import cuga_agent\\n        except Exception as exc:  # pragma: no cover - optional deps\\n            pytest.skip(f\\\"cuga_agent not importable in this env: {exc}\\\")\\n\\n        agent = cuga_agent.CugaComponent.__new__(cuga_agent.CugaComponent)\\n        agent._vertex = SimpleNamespace(graph=SimpleNamespace(flow_id=flow_id, session_id=session_id))\\n        agent.n_messages = n_messages\\n        agent.input_value = SimpleNamespace(id=\\\"current-input-id\\\")\\n        return agent\\n\\n    @pytest.mark.asyncio\\n    async def test_cuga_scopes_by_flow_id(self):\\n        flow_id_str = \\\"cccccccc-cccc-cccc-cccc-cccccccccccc\\\"\\n        agent = self._make_cuga(flow_id=flow_id_str)\\n\\n        with patch(\\n            \\\"lfx_bundles.cuga.cuga_agent.aget_agent_chat_history\\\",\\n            new=AsyncMock(return_value=[]),\\n        ) as mock_helper:\\n            await agent.get_memory_data()\\n\\n        kwargs = mock_helper.await_args.kwargs\\n        assert kwargs[\\\"flow_id\\\"] == flow_id_str\\n        assert kwargs[\\\"session_id\\\"] == \\\"shared\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_cuga_n_messages_zero_disables_memory(self):\\n        agent = self._make_cuga(flow_id=\\\"dddddddd-dddd-dddd-dddd-dddddddddddd\\\", n_messages=0)\\n\\n        with patch(\\n            \\\"lfx.components.models_and_agents.memory.aget_messages\\\",\\n            new=AsyncMock(return_value=[SimpleNamespace(id=f\\\"msg-{i}\\\") for i in range(3)]),\\n        ) as mock_get:\\n            result = await agent.get_memory_data()\\n\\n        assert result == []\\n        mock_get.assert_not_awaited()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/CustomEdges/__tests__/CustomEdges.a11y.test.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fdb70c697f21a4aa00f9c8af1c49b723c9f245b822d560c7834c15562eb7ad56\",\"content\":\"import { render } from \\\"@testing-library/react\\\";\\nimport { Position } from \\\"@xyflow/react\\\";\\nimport useFlowStore from \\\"@/stores/flowStore\\\";\\nimport type { AllNodeType } from \\\"@/types/flow\\\";\\nimport type { FlowStoreType } from \\\"@/types/zustand/flow\\\";\\nimport { axe } from \\\"@/utils/a11y-test\\\";\\nimport { DefaultEdge } from \\\"../index\\\";\\n\\nfunction setNodes(\\n  nodes: Record<string, { display_name?: string } | undefined>,\\n) {\\n  useFlowStore.setState({\\n    getNode: (id: string) => {\\n      const node = nodes[id];\\n      if (node === undefined) return undefined;\\n      return {\\n        id,\\n        position: { x: 0, y: 0 },\\n        data: { node: { display_name: node.display_name } },\\n      } as unknown as AllNodeType;\\n    },\\n    edges: [],\\n    setEdges: jest.fn(),\\n  } as Partial<FlowStoreType>);\\n}\\n\\nconst baseProps = {\\n  id: \\\"e1\\\",\\n  source: \\\"n1\\\",\\n  target: \\\"n2\\\",\\n  sourceX: 0,\\n  sourceY: 0,\\n  targetX: 100,\\n  targetY: 100,\\n  sourceHandleId: \\\"sh\\\",\\n  targetHandleId: JSON.stringify({ fieldName: \\\"x\\\" }),\\n  sourcePosition: Position.Right,\\n  targetPosition: Position.Left,\\n};\\n\\n// The accessible name for an edge now comes from `edge.ariaLabel`, set once\\n// at build time in PageComponent (see get-edge-aria-label.ts) and read\\n// natively by ReactFlow's EdgeWrapper <g>. DefaultEdge itself must NOT\\n// render a competing role/aria-label on its interaction path: doing so\\n// either duplicates the wrapper's name (editable canvas, wrapper is\\n// role=\\\"group\\\" and focusable) or is silently dropped (locked/preview,\\n// wrapper is role=\\\"img\\\" and its subtree is pruned from the a11y tree).\\ndescribe(\\\"DefaultEdge acc";
